/**
 * Internal dependencies
 */
import './style.scss';

import ItemPicker from '@components/item-picker';

interface Pattern {
	blocks: unknown[];
	category?: string;
}

interface Layout {
	patterns: Pattern[];
}

interface PatternPickerMenuProps {
	patterns: Layout[];
	clientId?: string;
	isHeroPattern?: boolean;
	isFullLayout?: boolean;
}

export default function PatternPickerMenu( {
	patterns,
	clientId,
	isHeroPattern,
	isFullLayout,
}: PatternPickerMenuProps ): JSX.Element {
	return (
		<div className="big-sky__dock__menu__pattern-picker picker-component">
			<ItemPicker
				items={ patterns }
				clientId={ clientId }
				isHeroPattern={ isHeroPattern }
				isFullLayout={ isFullLayout }
			/>
		</div>
	);
}
