/**
 * Sentinel target root meaning "stage into the editor's document root" — a plain
 * post/page editor that has neither a section container nor a core/post-content
 * wrapper, so the top-level blocks ARE the post body. The shared renderer treats
 * any non-null target as "canvas ready" and passes it straight back to
 * stageBlocks/commitFinalDesign, so StandardEditorHost is the only place that
 * interprets this value. ESE always resolves a real clientId and never sees it.
 */
export const DOCUMENT_ROOT = '__big-sky-page-design-document-root__';

/**
 * Decide where the shared renderer should stage streamed page-design blocks.
 *
 * Order: an explicit section container, then a core/post-content wrapper, then
 * (for a plain post/page editor with neither) the document root — but only once
 * the editor has a resolved post id, so a still-mounting canvas returns null and
 * the renderer retries instead of staging into nothing.
 *
 * @param root0                     Resolver inputs.
 * @param root0.sectionRootClientId Section container clientId, or null.
 * @param root0.postContentClientId core/post-content clientId, or null.
 * @param root0.hasResolvedPost     Whether the editor has a resolved post id.
 * @return The target root clientId, the DOCUMENT_ROOT sentinel, or null when not ready.
 */
export function resolvePageDesignTargetRoot( {
	sectionRootClientId,
	postContentClientId,
	hasResolvedPost,
}: {
	sectionRootClientId: string | null;
	postContentClientId: string | null;
	hasResolvedPost: boolean;
} ): string | null {
	if ( sectionRootClientId ) {
		return sectionRootClientId;
	}
	if ( postContentClientId ) {
		return postContentClientId;
	}
	return hasResolvedPost ? DOCUMENT_ROOT : null;
}
