/**
 * Internal dependencies
 */
import siteAdminAssistant from './site-admin/index.js';
import {
	getAssistantById,
	getAssistants,
	registerAssistant,
} from './assistant-registry.js';

// Register all assistants
[ siteAdminAssistant ].forEach( registerAssistant );

// Export the assistants array and lookup functions
export const assistants = getAssistants();
export const assistantsById = ( id ) => getAssistantById( id );

// Named exports for specific assistants
export { siteAdminAssistant };

// Re-export registry functions (importing from here ensures registration has happened)
export { getAssistantById, getAssistants };
