/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';

/**
 * Internal dependencies
 */

import { store as aiStore } from '@store';
import setDelay from '@utils/set-delay';
import log from '@utils/log-debug';
import useValidation from '@hooks/use-validation';
import { __ } from '@wordpress/i18n';

const useCreateToolCallback = () => {
	const { getBlock } = useSelect( blockEditorStore );
	const { isValidClientId } = useValidation();

	const { decrementPendingToolCallbacks, incrementPendingToolCallbacks } =
		useDispatch( aiStore );

	const withPendingToolCallback = useCallback(
		( callback ) => async ( args ) => {
			incrementPendingToolCallbacks();
			// A delay is needed here for the pending increment to be registered by the dock component.
			await setDelay( 200 );
			try {
				return await callback( args );
			} catch ( error ) {
				throw error;
			} finally {
				decrementPendingToolCallbacks();
			}
		},
		[ decrementPendingToolCallbacks, incrementPendingToolCallbacks ]
	);

	const validateTargetedBlock = ( args, targetedBlockValidTypes ) => {
		if ( ! args.clientId || ! isValidClientId( args.clientId ) ) {
			return false;
		}

		const block = getBlock( args.clientId );

		if ( targetedBlockValidTypes && ! block ) {
			return false;
		}

		// If no targetedBlockValidTypes provided, just validate clientId was valid
		if ( ! targetedBlockValidTypes ) {
			return true;
		}

		// If targetedBlockValidTypes is a function, use it as a validator
		if ( typeof targetedBlockValidTypes === 'function' ) {
			return targetedBlockValidTypes( block.name );
		}

		// Otherwise treat it as an array of valid block types
		return targetedBlockValidTypes.includes( block.name );
	};

	const defaultFailValidatorAction = async ( args, error ) => {
		const message =
			error?.message ?? __( 'Failed to validate arguments', 'big-sky' );

		return message;
	};

	const createToolCallback =
		( {
			action,
			closeChatWhenDone = () => true, // Set to false to keep the chat open after the tool runs.
			validator = null,
			failValidatorAction = defaultFailValidatorAction,
			getTargetedBlockRequired = () => false,
			getTargetedBlockValidTypes = () => null,
		} ) =>
		async ( args ) => {
			if ( getTargetedBlockRequired( args ) ) {
				if (
					! validateTargetedBlock(
						args,
						getTargetedBlockValidTypes( args )
					)
				) {
					return await failValidatorAction( args, {
						message: __(
							`I couldn't find the block you mentioned. Describe where it is on the page or select it and try again.`,
							'big-sky'
						),
					} );
				}
			}

			if ( validator ) {
				try {
					const isValid = await validator( args );
					if ( ! isValid ) {
						if ( typeof failValidatorAction === 'function' ) {
							return await failValidatorAction( args, {
								message: __(
									'Failed to validate arguments',
									'big-sky'
								),
							} );
						}
					}
				} catch ( error ) {
					if ( typeof failValidatorAction === 'function' ) {
						return await failValidatorAction( args, error );
					}
				}
			}

			const executeAction = async ( _args ) => {
				try {
					return await action( _args );
				} catch ( error ) {
					log.error( 'Tool error:', error );
					return {
						message: __(
							`I couldn't complete that request. Please try again.`,
							'big-sky'
						),
					};
				}
			};

			// Some tools keep the chat open, some close afterward.
			// closeChatWhenDone() is a function because it needs to be called when the callback runs, not when the tool is created.
			if ( closeChatWhenDone() ) {
				return await withPendingToolCallback( executeAction )( args );
			}
			return await executeAction( args );
		};

	return {
		withPendingToolCallback,
		createToolCallback,
	};
};

export default useCreateToolCallback;
