/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { store as coreStore } from '@wordpress/core-data';
import { serialize } from '@wordpress/blocks';

export default function useTemplateParts() {
	const { getCurrentTheme, getEntityRecord } = useSelect( coreStore );
	const { editEntityRecord } = useDispatch( coreStore );

	const buildTemplatePartId = useCallback(
		( templatePartName ) => {
			return `${ getCurrentTheme().stylesheet }//${ templatePartName }`;
		},
		[ getCurrentTheme ]
	);

	const editTemplatePart = useCallback(
		async ( templatePartId, blocks ) => {
			const record = getEntityRecord(
				'postType',
				'wp_template_part',
				templatePartId
			);
			if ( ! record ) {
				return;
			}

			await editEntityRecord(
				'postType',
				'wp_template_part',
				templatePartId,
				{ blocks, content: serialize( blocks ) }
			);
		},
		[ editEntityRecord, getEntityRecord ]
	);

	const replaceTemplatePart = async ( templatePartName, blocks ) => {
		const templatePartId = buildTemplatePartId( templatePartName );
		await editTemplatePart( templatePartId, blocks );
	};

	return {
		buildTemplatePartId,
		editTemplatePart,
		replaceTemplatePart,
	};
}
