/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { useUpdateTheme } from '@hooks/use-update-theme';
import { captureCanvasFileParts, type FilePart } from '@utils/canvas-capture';
// Side-effect import: without a registered rasterizer every capture returns
// null and no picture is ever attached.
import '@utils/register-canvas-rasterizer';
import useCheckpoint from '@hooks/use-checkpoint';
import { checkpointKeys } from '@utils/constants';
import { getToolCallIdFromConversationHistory } from '@utils/tool-call-history';

/**
 * Types
 */
interface ColorPaletteItem {
	color: string;
	name: string;
	slug: string;
}

interface FontFamily {
	fontFamily: string;
	name: string;
	slug: string;
}

interface FontSize {
	size: string;
	name: string;
	slug: string;
}

interface ThemeSettings {
	color?: {
		palette?: ColorPaletteItem[];
		[ key: string ]: unknown;
	};
	typography?: {
		fontFamilies?: FontFamily[];
		fontSizes?: FontSize[];
		[ key: string ]: unknown;
	};
	[ key: string ]: unknown;
}

interface ThemeStyles {
	[ key: string ]: unknown;
}

interface UpdateThemeArgs {
	settings?: ThemeSettings;
	styles?: ThemeStyles;
	summary?: string;
	followUpTasks?: boolean;
	messageId?: string;
}

interface UpdateThemeResultData {
	success: boolean;
	message: string;
	error?: string;
	details?: unknown;
}

interface UpdateThemeResult {
	result: UpdateThemeResultData;
	returnToAgent: boolean;
	// A sibling of `result`, not part of it: the agent client lifts this onto
	// the tool-result part rather than into the text the model reads.
	__file_parts?: FilePart[];
}

interface ThemeUpdate {
	settings?: ThemeSettings;
	styles?: ThemeStyles;
}

const UPDATE_THEME_TOOL_ID = 'big_sky__apply_update_theme';
export default function useUpdateThemeTool(): {
	updateTheme: ( args: UpdateThemeArgs ) => Promise< UpdateThemeResult >;
} {
	const updateTheme = useUpdateTheme();
	const { setCheckpoint, hasCheckpoint } = useCheckpoint();

	const updateThemeSettings = async (
		args: UpdateThemeArgs
	): Promise< UpdateThemeResult > => {
		const { settings, styles, summary, messageId } = args || {};
		const failMessage = __(
			'Failed to make the theme update. Please try again.',
			'big-sky'
		);

		// Validate that at least one of settings or styles is provided
		if ( ! settings && ! styles ) {
			return {
				result: {
					success: false,
					message: failMessage,
					error: __(
						'Invalid arguments. Provide either settings or styles to update the theme.',
						'big-sky'
					),
				},
				returnToAgent: true,
			};
		}

		// Validate settings structure if provided
		if ( settings && typeof settings !== 'object' ) {
			return {
				result: {
					success: false,
					message: failMessage,
					error: __(
						'Invalid settings format. Settings must be an object.',
						'big-sky'
					),
				},
				returnToAgent: true,
			};
		}

		// Validate styles structure if provided
		if ( styles && typeof styles !== 'object' ) {
			return {
				result: {
					success: false,
					message: failMessage,
					error: __(
						'Invalid styles format. Styles must be an object.',
						'big-sky'
					),
				},
				returnToAgent: true,
			};
		}

		// Everything below has actually touched the theme, so it is worth showing
		// the agent the result. The validation returns above have not, and a
		// picture of an unchanged page tells it nothing about its own bad
		// arguments.
		const applyThemeUpdate = async (): Promise< UpdateThemeResult > => {
			try {
				const themeCheckpointKeys = [
					checkpointKeys.COLOR,
					checkpointKeys.FONT,
					checkpointKeys.BUTTON,
				];
				const toolCallId = getToolCallIdFromConversationHistory(
					UPDATE_THEME_TOOL_ID,
					messageId
				);

				if ( toolCallId && ! hasCheckpoint( toolCallId ) ) {
					setCheckpoint( toolCallId, themeCheckpointKeys, {
						toolCallId,
						toolId: UPDATE_THEME_TOOL_ID,
						messageId,
						summary,
					} );
				}

				// Create the theme update object
				const themeUpdate: ThemeUpdate = {};
				if ( settings ) {
					themeUpdate.settings = settings;
				}
				if ( styles ) {
					themeUpdate.styles = styles;
				}

				// Call the updateTheme function
				const success = await updateTheme( themeUpdate );

				const successMessage =
					summary || __( 'Theme updated successfully', 'big-sky' );
				if ( success ) {
					return {
						result: {
							success: true,
							message: successMessage,
							details: {
								updatedSettings: !! settings,
								updatedStyles: !! styles,
							},
						},
						returnToAgent: true,
					};
				}

				return {
					result: {
						success: false,
						message: failMessage,
						error: 'Theme update returned false.',
					},
					returnToAgent: true,
				};
			} catch ( error ) {
				const errorDetails =
					error instanceof Error ? error.message : String( error );
				return {
					result: {
						success: false,
						message: failMessage,
						error: errorDetails,
					},
					returnToAgent: true,
				};
			}
		};

		const outcome = await applyThemeUpdate();

		// The whole page, not one screenful. A theme change is judged across all
		// of it — colour, type scale, spacing, the rhythm of one section against
		// the next — and this is the case the block tree can least speak to: the
		// write can land exactly as asked and be invisible because block
		// attributes and Additional CSS out-specify it (BSKY-1999).
		const fileParts = await captureCanvasFileParts( { fullPage: true } );

		return fileParts ? { ...outcome, __file_parts: fileParts } : outcome;
	};

	return {
		updateTheme: updateThemeSettings,
	};
}
