/**
 * Turns canvas capture on.
 *
 * A side-effect module: importing it registers the browser rasterizer as the
 * implementation behind `captureCanvasFileParts`, so tools that capture start
 * producing images. Without this import the seam has no rasterizer and every
 * capture returns null, which is the dormant state.
 *
 * Kept separate from both the seam and the rasterizer so that "which renderer"
 * and "is capture on" stay one edit each, and so tests can exercise either side
 * without the other being wired up.
 */

/**
 * Internal dependencies
 */
import { setCanvasRasterizer } from '@utils/canvas-capture';
import { rasterizeCanvas } from '@utils/canvas-rasterizer';

setCanvasRasterizer( rasterizeCanvas );
