/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { select } from '@wordpress/data';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Internal dependencies
 */
import { showComponent as showComponentCallback } from './show-component';
import { store as aiStore } from '@store';

/**
 * Checkpoint functions type
 */
type CheckpointFunctions = {
	setCheckpoint: ( messageId: string, keys: string[] ) => void;
	addNewPageToCheckpoint: ( pageId: string ) => void;
};

/**
 * Show component ability
 *
 * Displays a component in the UI with specified props (button picker, font picker, color picker, pattern picker).
 *
 * @param checkpointFunctions - The checkpoint functions from useCheckpoint hook
 * @return The show component ability definition
 */
export const showComponentAbility = (
	checkpointFunctions: CheckpointFunctions
): Ability => ( {
	name: 'big-sky/show-component',
	label: __( 'Show Component', 'big-sky' ),
	category: 'big-sky',
	description: 'Display a component in the UI with specified props',
	input_schema: {
		type: 'object',
		properties: {
			type: {
				type: 'string',
				description: 'The type of component to show',
				enum: [
					'button-picker',
					'font-picker',
					'color-picker',
					'pattern-picker',
				],
			},
			props: {
				type: 'object',
				description: 'The props to pass to the component',
			},
			summary: {
				type: 'string',
				description: 'Summary message to show to the user',
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Deprecated. This tool always returns to the agent with a success or error message.',
			},
			zoomOut: {
				type: 'boolean',
				description:
					'Whether to zoom out before showing the component. Ignored for color-picker and font-picker.',
			},
			clientId: {
				type: 'string',
				description: 'The compressed client ID of the block to target',
			},
			insertIndex: {
				type: 'number',
				description: 'The index at which to insert the component',
			},
		},
		required: [ 'type', 'props' ],
	},
	output_schema: {
		type: 'object',
		properties: {
			result: {
				type: 'object',
				properties: {
					success: {
						type: 'boolean',
						description:
							'Whether the picker was shown successfully.',
					},
					message: {
						type: 'string',
						description: 'Human-readable success or error message.',
					},
					error: {
						type: 'string',
						description: 'Error details when success is false.',
					},
					details: {
						type: 'object',
						description: 'Optional details about the shown picker.',
					},
				},
				required: [ 'success', 'message' ],
			},
			returnToAgent: {
				type: 'boolean',
			},
			agentMessage: {
				type: 'string',
			},
		},
		required: [ 'result', 'returnToAgent' ],
	},
	callback: async ( input ) => {
		// Get clientIdMap from store
		const clientIdMap =
			select( aiStore ).getFullPageStructure()?.clientIdMap || {};

		// Call the existing showComponent function with checkpoint functions
		return await showComponentCallback(
			{
				...input,
				reverseMap: clientIdMap,
			},
			checkpointFunctions
		);
	},
} );
