/**
 * WordPress dependencies
 */
import { useDispatch, useRegistry } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { __, sprintf } from '@wordpress/i18n';
import { createBlock, parse, serialize } from '@wordpress/blocks';
import { store as aiStore } from '@store/index.js';
import useNavigation from '@hooks/use-navigation.js';
import { ChatSuggestions } from '@ai/assistants/shared/make-suggestions/index.js';
import useSiteMetadata from '@hooks/use-site-metadata.js';
import useCurrentScreen from '@hooks/use-current-screen.js';
import useNavigateTool from '../editor-navigate/use-navigate-tool';
import log from '@utils/log-debug.js';
import useCheckpoint from '@hooks/use-checkpoint';
import { checkpointKeys } from '@utils/constants';
import { getToolCallIdFromConversationHistory } from '@utils/tool-call-history';

interface EntityToAdd {
	entityType: string;
	entityName: string;
	record: Record< string, unknown >;
	options?: Record< string, unknown >;
}

interface NavigationItemInput {
	clientId?: string;
	label?: string;
	url?: string;
	id?: string | number;
	kind?: string;
	type?: string;
	opensInNewTab?: boolean;
	items?: NavigationItemInput[];
}

interface EntityToEdit {
	entityType: string;
	entityName: string;
	recordId: string | number;
	record:
		| Record< string, unknown >
		| { title: string }
		| { navigationItems: NavigationItemInput[] };
	options?: Record< string, unknown >;
}

interface EntityToDelete {
	entityType: string;
	entityName: string;
	recordId: string | number;
	options?: Record< string, unknown >;
}

interface ManageEntitiesArgs {
	addEntities?: EntityToAdd[];
	editEntities?: EntityToEdit[];
	deleteEntities?: EntityToDelete[];
	confirmationMessage?: string;
	summary?: string;
	followUpTasks?: boolean;
	messageId?: string;
}

interface CreatedEntity {
	entityType: string;
	entityName: string;
	record: {
		id: number;
		title?: { rendered?: string } | string;
		link?: string;
		[ key: string ]: unknown;
	};
}

interface UpdatedEntity {
	entityType?: string;
	entityName?: string;
	recordId?: string | number;
	record?: {
		title?: string;
		[ key: string ]: unknown;
	};
	navigationId?: string | number;
	pageId?: string | number;
	newTitle?: string;
}

interface DeletedEntity {
	entityType?: string;
	entityName?: string;
	recordId?: string | number;
	deleted: boolean;
	navigationId?: string | number;
	pageId?: string | number;
}

interface ApplyEntityChangesResult {
	createdEntities: CreatedEntity[];
	updatedEntities: UpdatedEntity[];
	deletedEntities: DeletedEntity[];
}

interface EntityRecordResult {
	success: boolean;
	message: string;
	error?: string;
	details?: unknown;
}

interface ManageEntitiesResult {
	result: EntityRecordResult | Promise< EntityRecordResult >;
	returnToAgent: boolean;
	agentMessage?: string | unknown;
}

const EDIT_ENTITY_RECORD_TOOL_ID = 'big_sky__edit_entity_record';

const logEditEntityDebug = () => {};

const buildFailureMessage = ( error: unknown ) =>
	`Failed to manage entities. Error: ${
		( error as Error )?.message || error
	}`;

const getCheckpointKeysForEntityChanges = ( {
	addEntities,
	editEntities,
	deleteEntities,
}: Pick<
	ManageEntitiesArgs,
	'addEntities' | 'editEntities' | 'deleteEntities'
> ): string[] => {
	const keys = new Set< string >();

	const addKeyForEntity = (
		entityName?: string,
		recordId?: string | number
	) => {
		if ( entityName === 'page' ) {
			keys.add( checkpointKeys.PAGE );
			keys.add( checkpointKeys.NAVIGATION );
		}
		if ( entityName === 'wp_navigation' ) {
			keys.add( checkpointKeys.NAVIGATION );
		}
		if ( recordId === 'big_sky_site_metadata' ) {
			keys.add( checkpointKeys.SITE_METADATA );
		}
		if ( recordId === 'site_title' ) {
			keys.add( checkpointKeys.SITE_TITLE );
			keys.add( checkpointKeys.SITE_METADATA );
		}
	};

	addEntities?.forEach( ( entity ) => addKeyForEntity( entity?.entityName ) );
	editEntities?.forEach( ( entity ) =>
		addKeyForEntity( entity?.entityName, entity?.recordId )
	);
	deleteEntities?.forEach( ( entity ) =>
		addKeyForEntity( entity?.entityName, entity?.recordId )
	);

	return [ ...keys ];
};

const getNavigationContent = ( navigation: Record< string, unknown > ) => {
	return typeof navigation.content === 'string'
		? navigation.content
		: ( navigation.content as { raw?: string; rendered?: string } )?.raw ||
				( navigation.content as { raw?: string; rendered?: string } )
					?.rendered ||
				'';
};

const getNavigationEntityBlocks = ( navigation: Record< string, unknown > ) => {
	if ( Array.isArray( navigation.blocks ) && navigation.blocks.length > 0 ) {
		return navigation.blocks;
	}

	const content = getNavigationContent( navigation );

	return content ? parse( content ) : [];
};

const getNavigationItemKey = ( item: NavigationItemInput ) => {
	if ( item.clientId ) {
		return `clientId:${ item.clientId }`;
	}
	if ( item.id ) {
		return `id:${ item.id }`;
	}
	if ( item.url ) {
		return `url:${ item.url }`;
	}
	if ( item.label ) {
		return `label:${ item.label }`;
	}
	return '';
};

const getRecordTitle = ( record?: Record< string, unknown > | null ) => {
	const title = record?.title;
	if ( typeof title === 'object' && title !== null ) {
		return (
			( title as { raw?: string; rendered?: string } ).raw ||
			( title as { raw?: string; rendered?: string } ).rendered ||
			''
		);
	}
	return typeof title === 'string' ? title : '';
};

const getNavigationBlockName = (
	item: NavigationItemInput,
	fallback = 'core/navigation-link'
) => {
	if ( ! Array.isArray( item.items ) ) {
		return fallback;
	}

	return item.items.length
		? 'core/navigation-submenu'
		: 'core/navigation-link';
};

const createNavigationBlockFromItem = ( item: NavigationItemInput ) => {
	const attributes = {
		...( item.label ? { label: item.label } : {} ),
		...( item.url ? { url: item.url } : {} ),
		...( item.id ? { id: item.id } : {} ),
		...( item.kind ? { kind: item.kind } : {} ),
		...( item.type ? { type: item.type } : {} ),
		...( typeof item.opensInNewTab === 'boolean'
			? { opensInNewTab: item.opensInNewTab }
			: {} ),
	};

	return createBlock( getNavigationBlockName( item ), attributes );
};

const buildNavigationBlocksFromItems = (
	items: NavigationItemInput[],
	existingBlocks: any[],
	clientIdMap: Record< string, string >,
	navigationItemMap: Record<
		string,
		{ ref?: string | number; attributes?: Record< string, unknown > }
	> = {}
) => {
	const existingByKey = new Map< string, any >();

	// Inverted once rather than scanned per block: indexBlock() runs for every block at every level
	// of the menu, and clientIdMap does not change while it does.
	const compressedByClientId = new Map< string, string >();
	Object.keys( clientIdMap ).forEach( ( compressedId ) => {
		compressedByClientId.set( clientIdMap[ compressedId ], compressedId );
	} );

	const indexBlock = ( block: any ) => {
		if ( block.clientId ) {
			existingByKey.set( `clientId:${ block.clientId }`, block );

			const compressedId = compressedByClientId.get( block.clientId );
			if ( compressedId ) {
				existingByKey.set( `clientId:${ compressedId }`, block );
			}
		}

		if ( block.attributes?.id ) {
			existingByKey.set( `id:${ block.attributes.id }`, block );
		}
		if ( block.attributes?.url ) {
			existingByKey.set( `url:${ block.attributes.url }`, block );
		}
		if ( block.attributes?.label ) {
			existingByKey.set( `label:${ block.attributes.label }`, block );
		}

		block.innerBlocks?.forEach( indexBlock );
	};

	existingBlocks.forEach( indexBlock );

	// Looks a clientId up in the map the editor built while walking the page and returns its
	// attributes, or undefined when the entry holds nothing to rebuild the item from. Finding an
	// entry is not enough: the editor stores `attributes: block.attributes || {}`, so both
	// `{ ref: 1843 }` and `{ attributes: {} }` occur, and neither says anything about the item.
	//
	// Callers read undefined as "this clientId told me nothing" and refuse the edit, rather than
	// building a navigation-link with no label and no url and serializing it over the menu.
	const getMappedAttributes = ( clientId?: string ) => {
		const attributes = clientId
			? navigationItemMap[ clientId ]?.attributes
			: undefined;

		return attributes?.label || attributes?.url ? attributes : undefined;
	};

	// getNavigationItemKey() short-circuits on clientId, so an item carrying both a clientId and an
	// id never reaches the id index. Ids are unique, so falling back to them cannot resolve to the
	// wrong item the way url or label can — two items can share a label, they cannot share an id.
	const findExistingBlock = ( item: NavigationItemInput ) =>
		existingByKey.get( getNavigationItemKey( item ) ) ||
		( item.id ? existingByKey.get( `id:${ item.id }` ) : undefined );

	const buildLevel = ( levelItems: NavigationItemInput[] ): any[] => {
		// An item identified *only* by clientId has to resolve to something that carries its
		// attributes: either a block already in the menu, or the navigationItemMap the editor built
		// when it walked the page. If neither has it, there is no data for that item —
		// createNavigationBlockFromItem() would build a navigation-link with no label and no url,
		// and serializing that over the menu reads to the user as the menu having been wiped.
		//
		// An item that brought its own label or url is not in that position: it has everything
		// needed to build a correct block, so a clientId that resolves to nothing alongside real
		// data is stale bookkeeping, not data loss, and is no reason to refuse the edit.
		//
		// Deliberately no fallback to url/label matching for the rest: existingByKey is a Map, so
		// two items sharing a label or url overwrite each other in the index, and a fallback would
		// quietly resolve to whichever was last. Blanking an item is at least visible; editing the
		// wrong one is not.
		//
		// The usual cause is the header not being part of the page open in the editor ("show
		// template" off), which leaves navigationItemMap empty while the model still holds
		// clientIds from a turn when the template was visible.
		const unresolved = levelItems.filter(
			( item ) =>
				item.clientId &&
				! item.label &&
				! item.url &&
				! getMappedAttributes( item.clientId ) &&
				! findExistingBlock( item )
		);

		if ( unresolved.length ) {
			const ids = [
				...new Set( unresolved.map( ( item ) => item.clientId ) ),
			].join( ', ' );
			throw new Error(
				sprintf(
					/* translators: %s: comma-separated list of navigation item identifiers that could not be resolved. */
					__(
						'Navigation items not found: %s. These are not in the menu or in the current page structure, so there is nothing to reorder them from — they are most likely from an earlier turn, or the header is not part of the page currently open in the editor. Read the page structure again and use the clientIds it returns, or identify each item by its url or label instead. This reorder was not applied.',
						'big-sky'
					),
					ids
				)
			);
		}

		return levelItems.map( ( item ) => {
			const itemWithFallbacks = {
				...getMappedAttributes( item.clientId ),
				...item,
			} as NavigationItemInput;
			const existingBlock =
				findExistingBlock( item ) ||
				findExistingBlock( itemWithFallbacks );
			const block =
				existingBlock ||
				createNavigationBlockFromItem( itemWithFallbacks );
			const nextBlockName = getNavigationBlockName( item, block.name );
			const nextBlock = {
				...block,
				name: nextBlockName,
				attributes: {
					...block.attributes,
					...( itemWithFallbacks.label
						? { label: itemWithFallbacks.label }
						: {} ),
					...( itemWithFallbacks.url
						? { url: itemWithFallbacks.url }
						: {} ),
					...( typeof itemWithFallbacks.opensInNewTab === 'boolean'
						? { opensInNewTab: itemWithFallbacks.opensInNewTab }
						: {} ),
				},
			};

			if ( item.items ) {
				// Resolved against the index built over the whole menu, not just this parent's
				// current children. Re-indexing from block.innerBlocks made nesting an existing
				// item under another impossible: the child's clientId is real and in the menu,
				// just not among the children of the block it is being moved under.
				nextBlock.innerBlocks = buildLevel( item.items );
			}

			return nextBlock;
		} );
	};

	return buildLevel( items );
};

export default function useEditEntityRecordTool() {
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const registry = useRegistry() as any;
	const { editEntityRecord } = useDispatch( coreStore );
	const {
		addNavigationItem,
		renameGlobalNavigationById,
		deleteGlobalNavigationPageById,
	} = useNavigation();
	const { setSiteMetadata, getSiteMetadata } = useSiteMetadata();
	const { postId: currentPostId } = useCurrentScreen();
	const { goToHomePage } = useNavigateTool();
	const {
		setCheckpoint,
		hasCheckpoint,
		addNavigationToCheckpoint,
		addPageRenameToCheckpoint,
	} = useCheckpoint();

	const buildNavigationRecord = async (
		recordId: string | number,
		record: Record< string, unknown >
	) => {
		const navigationItems = record.navigationItems as
			| NavigationItemInput[]
			| undefined;

		if ( ! Array.isArray( navigationItems ) ) {
			return record;
		}

		const navigation = ( await registry
			.resolveSelect( coreStore )
			.getEditedEntityRecord(
				'postType',
				'wp_navigation',
				recordId
			) ) as Record< string, unknown > | null;

		if ( ! navigation ) {
			throw new Error( `Navigation record not found: ${ recordId }` );
		}

		const fullPageStructure =
			registry.select( aiStore ).getFullPageStructure?.() || {};
		const clientIdMap = fullPageStructure.clientIdMap || {};
		const navigationItemMap = fullPageStructure.navigationItemMap || {};
		const blocks = buildNavigationBlocksFromItems(
			navigationItems,
			getNavigationEntityBlocks( navigation ),
			clientIdMap,
			navigationItemMap
		);

		const { navigationItems: _navigationItems, ...recordRest } = record;

		return {
			...recordRest,
			blocks,
			content: serialize( blocks ),
		};
	};

	const manageEntities = async (
		args: ManageEntitiesArgs
	): Promise< ManageEntitiesResult > => {
		const {
			addEntities = [],
			editEntities = [],
			deleteEntities = [],
			confirmationMessage,
			summary,
			messageId,
		} = args || {};

		if (
			! Array.isArray( addEntities ) ||
			! Array.isArray( editEntities ) ||
			! Array.isArray( deleteEntities )
		) {
			return {
				result: {
					success: false,
					message:
						'Invalid arguments. Provide arrays for addEntities, editEntities, and deleteEntities.',
					error: 'Invalid arguments. Provide arrays for addEntities, editEntities, and deleteEntities.',
				},
				returnToAgent: true,
			};
		}

		const createToolCallCheckpoint = () => {
			const entityCheckpointKeys = getCheckpointKeysForEntityChanges( {
				addEntities,
				editEntities,
				deleteEntities,
			} );
			const toolCallId = getToolCallIdFromConversationHistory(
				EDIT_ENTITY_RECORD_TOOL_ID,
				messageId
			);

			if ( toolCallId && ! hasCheckpoint( toolCallId ) ) {
				setCheckpoint( toolCallId, entityCheckpointKeys, {
					toolCallId,
					toolId: EDIT_ENTITY_RECORD_TOOL_ID,
					messageId,
					summary,
				} );
			}

			return toolCallId;
		};

		// Held outside applyEntityChanges() so a throw part-way through can still report what did
		// apply. addEntities runs first and has already saved records — and appended to the menu —
		// by the time a later edit fails, so "failed" on its own would have the agent re-create
		// entities that already exist.
		const appliedChanges: ApplyEntityChangesResult = {
			createdEntities: [],
			updatedEntities: [],
			deletedEntities: [],
		};

		// Shared function to apply create/edit/delete changes
		const applyEntityChanges =
			async (): Promise< ApplyEntityChangesResult > => {
				const checkpointId = createToolCallCheckpoint();
				const result: ApplyEntityChangesResult = appliedChanges;

				// Create entities
				for ( const item of addEntities ) {
					const { entityType, entityName, record, options } =
						item || {};
					if ( ! entityType || ! entityName || ! record ) continue;
					const created = ( await registry
						.dispatch( coreStore )
						.saveEntityRecord(
							entityType,
							entityName,
							record,
							options
						) ) as CreatedEntity[ 'record' ] | null;
					if ( created ) {
						result.createdEntities.push( {
							entityType,
							entityName,
							record: created,
						} );

						// Update navigation if the page was created
						if ( entityName === 'page' ) {
							try {
								const updatedNavigation =
									await addNavigationItem( {
										label:
											( typeof created.title === 'object'
												? created.title?.rendered
												: created.title ) ||
											created.title,
										type: 'page',
										id: created.id,
										url: created.link,
										kind: 'post-type',
									} );
								if ( updatedNavigation ) {
									result.updatedEntities.push( {
										navigationId: updatedNavigation.id,
										pageId: created.id,
										newTitle: created.title as string,
									} );
								}
							} catch ( error ) {
								log.error(
									'[Navigation] Error adding navigation item:',
									error
								);
							}
						}
					}
				}

				// Prefetch and edit entities
				for ( const item of editEntities ) {
					let oldPageTitle = '';
					let newPageTitle = '';
					const {
						entityType,
						entityName,
						recordId,
						record,
						options,
					} = item || {};
					if (
						! entityType ||
						! entityName ||
						record === null ||
						record === undefined
					)
						continue;
					let updated: Record< string, unknown > | null = null;
					if ( recordId === 'big_sky_site_metadata' ) {
						// This is a bit of a hack to update the site metadata.
						// We need to do this because the site metadata is not a regular entity record.
						// It is a custom field on the site entity record.
						// We need to update the site metadata directly.
						// TODO: Look if we can turn metadata into a regular entity record.
						await setSiteMetadata(
							record as Record< string, unknown >
						);
						const newSiteMetadata = await getSiteMetadata();
						// Only the new values of the keys we requested to update.
						updated = Object.keys( record ).reduce(
							( acc, key ) => {
								if ( key in newSiteMetadata ) {
									acc[ key ] = newSiteMetadata[ key ];
								}
								return acc;
							},
							{} as Record< string, unknown >
						);
					} else if ( recordId === 'site_title' ) {
						// Update the site title.
						await setSiteMetadata( {
							siteTitle: ( record as { title: string } ).title,
						} );
						await editEntityRecord(
							'root',
							'site',
							undefined,
							record
						);
					} else {
						// Regular update flow of the arbitrary entity record.
						const existingRecord = await registry
							.resolveSelect( coreStore )
							.getEditedEntityRecord(
								entityType,
								entityName,
								recordId
							);
						if ( entityName === 'page' ) {
							logEditEntityDebug( 'page edit detected', {
								entityType,
								entityName,
								recordId,
								record,
								existingRecord,
							} );
							const persistedRecord = await registry
								.resolveSelect( coreStore )
								.getEntityRecord(
									entityType,
									entityName,
									recordId
								);
							oldPageTitle =
								getRecordTitle( existingRecord ) ||
								getRecordTitle( persistedRecord );
							newPageTitle = getRecordTitle(
								record as Record< string, unknown >
							);
							logEditEntityDebug( 'page rename titles resolved', {
								recordId,
								oldPageTitle,
								newPageTitle,
								persistedRecord,
								existingRecord,
							} );
							if (
								oldPageTitle &&
								newPageTitle &&
								oldPageTitle !== newPageTitle
							) {
								addPageRenameToCheckpoint(
									recordId,
									oldPageTitle,
									newPageTitle
								);
							}
						}
						const recordToEdit =
							entityName === 'wp_navigation'
								? await buildNavigationRecord(
										recordId,
										record as Record< string, unknown >
								  )
								: record;

						// After the record is built, so a refused reorder does not leave behind a
						// restore point for an edit the same tool result says never happened. The
						// write itself is editEntityRecord() below, so this still snapshots the
						// menu as it was.
						if ( entityName === 'wp_navigation' ) {
							addNavigationToCheckpoint( checkpointId, recordId );
						}
						await editEntityRecord(
							entityType,
							entityName,
							recordId,
							recordToEdit,
							options
						);
						updated = registry
							.select( coreStore )
							.getEditedEntityRecord(
								entityType,
								entityName,
								recordId
							);
					}
					if ( updated ) {
						result.updatedEntities.push( {
							entityType,
							entityName,
							recordId,
							record: updated as UpdatedEntity[ 'record' ],
						} );

						// Update navigation if the page was updated
						if ( entityName === 'page' ) {
							const titleForNavigation =
								newPageTitle || getRecordTitle( updated );
							logEditEntityDebug(
								'renaming navigation for page edit',
								{
									recordId,
									oldPageTitle,
									titleForNavigation,
									updated,
								}
							);
							const updatedNavigation =
								await renameGlobalNavigationById(
									recordId,
									titleForNavigation,
									oldPageTitle
								);
							logEditEntityDebug( 'navigation rename result', {
								recordId,
								updatedNavigation,
							} );
							if ( updatedNavigation ) {
								result.updatedEntities.push( {
									navigationId: updatedNavigation.id,
									pageId: recordId,
									newTitle: titleForNavigation,
								} );
							}
						}
					}
				}

				// Prefetch and delete entities
				for ( const item of deleteEntities ) {
					const { entityType, entityName, recordId, options } =
						item || {};
					if ( ! entityType || ! entityName ) continue;

					// Update navigation if a page is being deleted
					if ( entityName === 'page' ) {
						const updatedNavigation =
							await deleteGlobalNavigationPageById( recordId );
						if ( updatedNavigation ) {
							result.deletedEntities.push( {
								navigationId: updatedNavigation.id,
								pageId: recordId,
								deleted: true,
							} );
						}
						// If deleting the current page, redirect to home
						if (
							parseInt( String( recordId ), 10 ) ===
							parseInt( String( currentPostId ), 10 )
						) {
							await goToHomePage();
						}
					}

					await registry
						.resolveSelect( coreStore )
						.getEditedEntityRecord(
							entityType,
							entityName,
							recordId
						);
					await registry
						.dispatch( coreStore )
						.deleteEntityRecord(
							entityType,
							entityName,
							recordId,
							options
						);
					result.deletedEntities.push( {
						entityType,
						entityName,
						recordId,
						deleted: true,
					} );
				}

				return result;
			};

		// If confirmation is requested and there are deletions, prompt the user and pause
		if ( confirmationMessage ) {
			registry.dispatch( aiStore ).setThinking( false );
			registry.dispatch( aiStore ).deleteMarkedMessages();
			const yesLabel = __( 'Yes', 'big-sky' );
			const noLabel = __( 'No', 'big-sky' );
			const yesAction = {
				actionName: yesLabel,
				description: __( 'Proceed', 'big-sky' ),
				type: 'confirmationDestructive',
				key: 'confirm-yes',
			};
			const noAction = {
				actionName: noLabel,
				description: __( 'I changed my mind', 'big-sky' ),
				type: 'confirmation',
				key: 'confirm-no',
			};

			const confirmationMessages: { buttonsId?: string } = {};

			const hideConfirmationMessages = async () => {
				await registry.dispatch( aiStore ).deleteMarkedMessages();

				// Also delete directly from the local store. In the unified chat the
				// custom delete action and local store can get out of sync; deleting by
				// the captured ID ensures the buttons disappear immediately.
				if ( confirmationMessages.buttonsId ) {
					registry
						.dispatch( aiStore )
						.deleteMessage( confirmationMessages.buttonsId );
				}
			};

			// Extracted respond handler for confirmation flow. The original tool
			// call returns immediately with returnToAgent=false, so these clicks run
			// as a new user turn after the tool result has been recorded.
			const handleConfirmEditEntityRecord = async (
				responseArgs: string
			) => {
				await hideConfirmationMessages();

				// User clicked "No". Hide the confirmation UI, then send the
				// cancellation back to the agent as a new user turn.
				if ( responseArgs?.startsWith( noLabel ) ) {
					await registry.dispatch( aiStore ).runAgent( noLabel );
					return;
				}

				// Nothing awaits this handler — createSuggestionClickHandler() calls respond()
				// without a catch — and the tool call already returned with returnToAgent: false,
				// so there is no tool result left to fail into. An uncaught throw here would be an
				// unhandled rejection: buttons dismissed, no error shown, conversation stalled.
				try {
					await applyEntityChanges();
				} catch ( error ) {
					await registry
						.dispatch( aiStore )
						.runAgent( buildFailureMessage( error ) );
					return;
				}

				await registry
					.dispatch( aiStore )
					.runAgent( __( 'Yes', 'big-sky' ) );
			};

			// Keep the confirmation text in the transcript, but render the buttons
			// separately so they can dismiss themselves after Yes/No is clicked.
			await registry.dispatch( aiStore ).addMessage( {
				role: 'assistant',
				content: [
					{
						type: 'text',
						text: confirmationMessage,
					},
				],
			} );

			const confirmEditEntityRecordMessage = await registry
				.dispatch( aiStore )
				.addMessage( {
					role: 'assistant',
					content: [
						{
							type: 'component',
							component: ChatSuggestions,
							componentProps: {
								args: {
									dismissOnClick: true,
									actions: [ yesAction, noAction ],
								},
							},
							respond: handleConfirmEditEntityRecord,
						},
					],
				} );

			confirmationMessages.buttonsId =
				confirmEditEntityRecordMessage?.message?.id;
			registry.dispatch( aiStore ).addMessageToDelete( {
				id: confirmationMessages.buttonsId,
			} );

			return {
				result: {
					success: false,
					message: __(
						'Awaiting user confirmation before making this change.',
						'big-sky'
					),
				},
				returnToAgent: false,
			};
		}

		// No confirmation needed, applying changes as they are.
		try {
			const changes = await applyEntityChanges();

			return {
				result: {
					success: true,
					message:
						summary ||
						__( 'Updated the entity records.', 'big-sky' ),
					details: changes,
				},
				returnToAgent: true,
			};
		} catch ( error ) {
			const errorMessage = buildFailureMessage( error );
			return {
				result: {
					success: false,
					message: errorMessage,
					error: errorMessage,
					// Whatever applied before the throw. A batch that creates a page and then
					// fails a menu edit has already created the page.
					details: appliedChanges,
				},
				returnToAgent: true,
			};
		}
	};

	return {
		editEntity: manageEntities,
	};
}
