/**
 * WordPress dependencies
 */
import { useEffect } from '@wordpress/element';
import { registerAbility, registerAbilityCategory } from '@wordpress/abilities';

/**
 * Internal dependencies
 */
import {
	addPagesAbility,
	applyBlockEditsAbility,
	clientAssistantsAbility,
	editEntityRecordAbility,
	editorNavigateAbility,
	restoreCheckpointAbility,
	setSiteLogoAbility,
	setStylesAbility,
	showComponentAbility,
	updateThemeAbility,
} from './index';
import useNavigateTool from './editor-navigate/use-navigate-tool';
import useApplyBlockEditsTool from './apply-block-edits/use-apply-block-edits-tool';
import useRunAssistant from './client-assistants/run-assistant';
import useCheckpoint from '@hooks/use-checkpoint';
import useEditEntityRecordTool from './edit-entity-record/use-edit-entity-record-tool';
import useUpdateThemeTool from './update-theme/use-update-theme-tool';
import { useSetSiteLogo } from './site-logo/set-site-logo';
import useAddPagesTool from './add-pages/use-add-pages-tool';
import useSetStylesTool from './set-styles/use-set-styles-tool';
import useRestoreCheckpointTool from './restore-checkpoint/use-restore-checkpoint-tool';
import useStreamPageDesignTool from './stream-page-design/use-stream-page-design-tool';
import { streamPageDesignAbility } from './stream-page-design';

let hasRegisteredAbilities = false;

/**
 * Custom hook to register Big Sky abilities that depend on React hooks
 *
 * This hook calls various use-*-tool hooks to get callbacks that have access to
 * React context (useSelect, useDispatch, etc.), then registers abilities with
 * those callbacks.
 *
 * Uses a global flag to ensure registration only happens once across all
 * component instances, even when multiple components use this hook.
 */
const useAbilitiesRegistration = () => {
	// Get callbacks from existing tool hooks
	const { navigate } = useNavigateTool();
	const { applyBlockEdits } = useApplyBlockEditsTool();
	const { runAssistant } = useRunAssistant();
	const { setCheckpoint, addNewPageToCheckpoint } = useCheckpoint();
	const { editEntity } = useEditEntityRecordTool();
	const { updateTheme } = useUpdateThemeTool();
	const { setSiteLogo } = useSetSiteLogo();
	const { addPages } = useAddPagesTool();
	const { setStyles } = useSetStylesTool();
	const { restoreCheckpointById } = useRestoreCheckpointTool();
	// Registers the streamed page-design apply handler against the editor; the
	// ability itself is registered below from the shared core's factory.
	useStreamPageDesignTool();

	useEffect( () => {
		if ( hasRegisteredAbilities ) {
			// Already ran in some component; do nothing here
			return;
		}
		hasRegisteredAbilities = true;

		// This should fail gracefully if the category is already registered via API, otherwise it will solve the problem on Woo 10.3.5 which prevents Abilities 0.4.0 from loading rest endpoints over wp-abilitis/v1.
		Promise.all( [
			registerAbilityCategory( 'big-sky', {
				label: 'Big Sky',
				description: 'Big Sky abilities',
			} ).catch( ( error ) => {
				// Category already registered - this is OK
				console.debug( 'Big Sky category already registered:', error );
			} ),
			registerAbilityCategory( 'wpcom', {
				label: 'WPCOM',
				description: 'WPCOM abilities',
			} ).catch( ( error ) => {
				// Category already registered - this is OK
				console.debug( 'WPCOM category already registered:', error );
			} ),
		] ).then( () => {
			// Register hook-dependent abilities after categories are registered
			registerAbility( editorNavigateAbility( navigate ) );
			registerAbility( applyBlockEditsAbility( applyBlockEdits ) );
			registerAbility( clientAssistantsAbility( runAssistant ) );
			registerAbility(
				showComponentAbility( {
					setCheckpoint,
					addNewPageToCheckpoint,
				} )
			);
			registerAbility( editEntityRecordAbility( editEntity ) );
			registerAbility( updateThemeAbility( updateTheme ) );
			registerAbility( setSiteLogoAbility( setSiteLogo ) );
			registerAbility( addPagesAbility( addPages ) );
			registerAbility( setStylesAbility( setStyles ) );
			registerAbility(
				restoreCheckpointAbility( restoreCheckpointById )
			);
			registerAbility( streamPageDesignAbility() );
		} );
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [] ); // Empty deps - only run once on mount

	return {
		abilitiesEnabled: true,
	};
};

export default useAbilitiesRegistration;
