/**
 * WordPress dependencies
 */
import {
	resolveSelect,
	useDispatch,
	useSelect,
	dispatch as wpDispatch,
	select as wpSelect,
} from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { store as commandsStore } from '@wordpress/commands';
import { privateApis as routerPrivateApis } from '@wordpress/router';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as editorStore } from '@wordpress/editor';
import { useEffect } from '@wordpress/element';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import useSaveEverything from '@hooks/use-save-everything';
import { getCurrentScreenContext } from '@utils/env';
import { unlock } from '@utils/lock-unlock';
import useCurrentScreen from '@hooks/use-current-screen';
import { TemplatePartSlug } from '@utils/template-parts';
import setDelay from '@utils/set-delay';

const { useHistory } = unlock( routerPrivateApis );

const INVALID_EDITOR_PATH_MESSAGE = __(
	'Invalid editor path. Page navigation requires /page/{numeric-id}. Look up the page ID first.',
	'big-sky'
);
const INVALID_EDITOR_PATH_ERROR = __(
	'Invalid editor path. look up the numeric id from <site_pages>, then retry navigation with the numeric editor_path.',
	'big-sky'
);
const isValidEditorNavigatePath = ( path: string ) =>
	/^\/?page\/\d+\/?$/.test( path );

/**
 * How long to wait for the editor to finish loading the page we navigated to.
 *
 * `history.navigate()` resolves once the route has changed, not once the editor
 * has resolved the new entity, so for a short window the URL points at the
 * destination while the block editor still holds the previous page's blocks.
 * Anything reading page content in that window — including the client context
 * we send to the agent — describes the wrong page.
 */
const EDITOR_LOAD_POLL_ATTEMPTS = 20;
const EDITOR_LOAD_POLL_INTERVAL_MS = 250;

/**
 * The numeric post id a valid `/page/{id}` navigate path refers to.
 *
 * @param path The navigate path.
 * @return The post id, or null when the path is not a page route.
 */
const getNavigatePathPostId = ( path: string ): number | null => {
	const match = /^\/?page\/(\d+)\/?$/.exec( path );
	return match ? Number( match[ 1 ] ) : null;
};

/**
 * The post the editor currently has loaded, read fresh rather than from a hook
 * value captured at render.
 */
const getLoadedEditorPostId = (): number | null => {
	const postId = ( wpSelect( editorStore ) as any )?.getCurrentPostId?.();
	const numeric = Number( postId );
	return Number.isFinite( numeric ) && numeric > 0 ? numeric : null;
};

/**
 * Poll until the editor reports the page we asked for as its current post.
 *
 * Mirrors the retry shape `refreshNavigationBlocks()` already uses for the same
 * underlying reason: the site editor settles asynchronously and there is no
 * promise to await.
 *
 * @param postId The post id navigation was requested for.
 * @return Whether the editor settled on that post within the timeout.
 */
const waitForEditorToLoadPost = async (
	postId: number
): Promise< boolean > => {
	for ( let attempt = 0; attempt < EDITOR_LOAD_POLL_ATTEMPTS; attempt++ ) {
		if ( getLoadedEditorPostId() === postId ) {
			return true;
		}
		await setDelay( EDITOR_LOAD_POLL_INTERVAL_MS );
	}

	return getLoadedEditorPostId() === postId;
};

/**
 * Types
 */
interface NavigateArgs {
	path: string;
	refresh_navigation?: boolean;
	summary?: string;
	followUpTasks?: boolean;
}

interface NavigateResult {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
}

interface Block {
	clientId: string;
	name: string;
	attributes?: Record< string, unknown >;
	innerBlocks?: Block[];
	[ key: string ]: unknown;
}

interface SiteRecord {
	page_on_front?: number;
	[ key: string ]: unknown;
}

interface History {
	navigate: ( path: string ) => Promise< void >;
}

interface ScreenContext {
	screen: string;
	[ key: string ]: unknown;
}

export default function useNavigateTool() {
	const saveEverything = useSaveEverything();
	const history = useHistory() as History;
	const { getBlock, getBlocks, getBlocksByName } = useSelect(
		( select ) => select( blockEditorStore ),
		[]
	) as {
		getBlock: ( clientId: string ) => Block | null;
		getBlocks: ( rootClientId?: string ) => Block[];
		getBlocksByName: ( name: string ) => string[];
	};
	const { setBlockEditingMode } = useDispatch( blockEditorStore ) as any;
	const { postId: currentPostId, previousPostId } = useCurrentScreen();

	useEffect( () => {
		if ( ! previousPostId ) return;

		if ( currentPostId !== previousPostId ) {
			// In Gutenberg 20.6.0, the post content block has block editing mode disabled when switching pages
			// need to set block editing mode to default in order for blocks to be editable
			const postContentBlock = getBlocksByName( 'core/post-content' );
			setBlockEditingMode( postContentBlock?.[ 0 ], 'default' );
		}
	}, [
		currentPostId,
		previousPostId,
		getBlocksByName,
		setBlockEditingMode,
	] );
	const { close } = useDispatch( commandsStore ) as any;

	const getNavigationBlocksFromTemplateParts = () => {
		const targetSlugs = [
			TemplatePartSlug.HeaderHero,
			TemplatePartSlug.Header,
			TemplatePartSlug.Footer,
		];
		const templatePartClientIds =
			getBlocksByName( 'core/template-part' ) || [];
		const templateParts = templatePartClientIds
			.map( ( clientId ) => getBlock( clientId ) )
			.filter(
				( block ): block is Block =>
					Boolean( block ) &&
					targetSlugs.includes( block?.attributes?.slug as string )
			);

		const findNavigationBlocks = ( blocks: Block[] ): Block[] =>
			blocks.flatMap( ( block ) => {
				const innerBlocks =
					getBlocks( block.clientId ) || block.innerBlocks || [];
				return [
					...( block.name === 'core/navigation' ? [ block ] : [] ),
					...findNavigationBlocks( innerBlocks ),
				];
			} );

		return templateParts.flatMap( ( templatePart ) =>
			findNavigationBlocks( getBlocks( templatePart.clientId ) || [] )
		);
	};

	const refreshNavigationBlocks = async () => {
		const coreDispatch = wpDispatch( coreStore ) as any;
		const coreResolveSelect = resolveSelect( coreStore ) as any;
		let navigationRefs: unknown[] = [];

		for ( let attempt = 0; attempt < 10; attempt++ ) {
			const navigationBlocks = getNavigationBlocksFromTemplateParts();
			navigationRefs = [
				...new Set(
					navigationBlocks
						.map( ( block ) => block.attributes?.ref )
						.filter( Boolean )
				),
			];

			if ( navigationRefs.length ) {
				break;
			}

			await setDelay( 150 );
		}

		for ( const navigationRef of navigationRefs ) {
			coreDispatch.invalidateResolution?.( 'getEditedEntityRecord', [
				'postType',
				'wp_navigation',
				navigationRef,
			] );
			coreDispatch.invalidateResolution?.( 'getEntityRecord', [
				'postType',
				'wp_navigation',
				navigationRef,
			] );

			try {
				await coreResolveSelect.getEditedEntityRecord(
					'postType',
					'wp_navigation',
					navigationRef
				);
			} catch {}
		}

		return navigationRefs.length;
	};

	const navigate = async (
		args: NavigateArgs
	): Promise< NavigateResult > => {
		const { path, summary } = args;

		if ( ! path || typeof path !== 'string' ) {
			return {
				result: {
					success: false,
					message:
						'Invalid path provided. Path must be a non-empty string.',
					error: 'Invalid path provided. Path must be a non-empty string.',
				},
				returnToAgent: true,
			};
		}

		if ( ! isValidEditorNavigatePath( path ) ) {
			return {
				result: {
					success: false,
					message: INVALID_EDITOR_PATH_MESSAGE,
					error: INVALID_EDITOR_PATH_ERROR,
				},
				returnToAgent: true,
			};
		}

		// Proceed with normal navigation
		try {
			// Save everything first
			await saveEverything();

			// Get current screen context to determine navigation method
			const currentScreenContext =
				getCurrentScreenContext() as ScreenContext;

			// Navigate using the same logic as goToPath
			if ( currentScreenContext.screen === 'site-editor' ) {
				await history.navigate( path + '?canvas=edit' );
				// Ensure the mosaic view is closed. Perhaps we should deep link
				// this in the future.
				await close();

				// Do not report success until the editor actually holds the page
				// we navigated to. history.navigate() resolves on the route change
				// alone, so returning here would tell the agent it is on the new
				// page while the block editor still has the previous one loaded —
				// and the client context built next describes that previous page.
				// An agent has been observed authoring edits for the destination
				// page against the departed page's block tree, emitting deletes
				// for every top-level block on it.
				const targetPostId = getNavigatePathPostId( path );
				if (
					targetPostId !== null &&
					! ( await waitForEditorToLoadPost( targetPostId ) )
				) {
					const timeoutMessage = `Navigated to ${ path }, but the editor did not finish loading that page in time. Do not edit content yet — the editor may still be showing the previous page. Tell the user the page did not open, and stop.`;
					return {
						result: {
							success: false,
							message: timeoutMessage,
							error: timeoutMessage,
							details: { path },
						},
						returnToAgent: true,
					};
				}
			} else {
				// If we're not in site editor, do a full navigation
				window.location.href = `/wp-admin/site-editor.php?p=${ encodeURIComponent(
					path
				) }&canvas=edit`;
			}

			const shouldRefreshNavigation = Boolean( args.refresh_navigation );
			const refreshedNavigationBlocks = shouldRefreshNavigation
				? await refreshNavigationBlocks()
				: 0;

			return {
				result: {
					success: true,
					message:
						summary ||
						`Successfully saved everything and navigated to: ${ path }`,
					details: {
						path,
						refreshNavigation: shouldRefreshNavigation,
						refreshedNavigationBlocks,
					},
				},
				returnToAgent: true,
			};
		} catch ( error ) {
			const shouldRefreshNavigation = Boolean( args.refresh_navigation );
			const errorMessage = `Failed to navigate to ${ path }. Error: ${
				( error as Error ).message
			}`;
			return {
				result: {
					success: false,
					message: errorMessage,
					error: errorMessage,
					details: {
						path,
						refreshNavigation: shouldRefreshNavigation,
					},
				},
				returnToAgent: true,
			};
		}
	};

	const goToHomePage = async (): Promise< NavigateResult > => {
		const siteRecord = ( await (
			resolveSelect( coreStore ) as any
		 ).getEntityRecord( 'root', 'site' ) ) as SiteRecord | null;
		const pageOnFront = siteRecord?.page_on_front;
		const path =
			pageOnFront && pageOnFront !== 0 ? `/page/${ pageOnFront }` : '/';
		return navigate( { path } );
	};

	return {
		navigate,
		goToHomePage,
	};
}
