/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import useStyles from '@hooks/use-styles';

export default function useSetStylesTool() {
	const { setStyles } = useStyles();

	const setStylesCallback = async ( args: {
		color?: string;
		font?: string;
		button?: string;
		updateBlocks?: boolean;
	} ) => {
		// eslint-disable-next-line @typescript-eslint/no-unused-vars
		const { color, font, button, updateBlocks = false } = args || {};

		// Validate that at least one style parameter is provided
		if ( ! color && ! font && ! button ) {
			return {
				result: __(
					'Invalid arguments. Provide at least one of: color, font, or button.',
					'big-sky'
				),
				returnToAgent: true,
			};
		}

		// Validate color if provided
		if ( color && typeof color !== 'string' ) {
			return {
				result: __(
					'Invalid color format. Color must be a string (variation title).',
					'big-sky'
				),
				returnToAgent: true,
			};
		}

		// Validate font if provided
		if ( font && typeof font !== 'string' ) {
			return {
				result: __(
					'Invalid font format. Font must be a string (variation title).',
					'big-sky'
				),
				returnToAgent: true,
			};
		}

		// Validate button if provided
		if ( button && typeof button !== 'string' ) {
			return {
				result: __(
					'Invalid button format. Button must be a string (variation title).',
					'big-sky'
				),
				returnToAgent: true,
			};
		}

		try {
			// Call setStyles from useStyles hook
			const result = setStyles( {
				color,
				font,
				button,
				undoIgnore: true, // Don't add to undo history for tool calls
			} );

			if ( result ) {
				// Create a summary of what was updated
				const updatedParts = [];
				if ( color ) {
					updatedParts.push(
						`color palette to "${ result.selectedColorVariation }"`
					);
				}
				if ( font ) {
					updatedParts.push(
						`font to "${ result.selectedFontVariation }"`
					);
				}
				if ( button ) {
					updatedParts.push( `button style` );
				}

				const resultMessage = __(
					'Styles updated successfully.',
					'big-sky'
				);
				const details =
					updatedParts.length > 0
						? ' ' +
						  __( 'Updated:', 'big-sky' ) +
						  ' ' +
						  updatedParts.join( ', ' ) +
						  '.'
						: '';

				return {
					result: resultMessage + details,
					returnToAgent: true,
				};
			}

			return {
				result: __(
					'Failed to update styles. The style variation may be invalid.',
					'big-sky'
				),
				returnToAgent: true,
			};
		} catch ( error: any ) {
			return {
				result:
					__( 'Failed to update styles:', 'big-sky' ) + error.message,
				returnToAgent: true,
			};
		}
	};

	return {
		setStyles: setStylesCallback,
	};
}
