/**
 * WordPress dependencies
 */
import { store as coreStore } from '@wordpress/core-data';

/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import logger from '@utils/log-debug';

/**
 * Core function to set the site logo in WordPress
 * This is a pure function that doesn't depend on React hooks,
 * making it reusable in both hook and non-hook contexts.
 *
 * @param {Object} options              - Configuration options
 * @param {string} options.attachmentId - The WordPress attachment ID for the logo
 * @param {string} options.logoUrl      - The URL of the logo image
 * @param {Object} options.registry     - WordPress data registry (optional for batch support)
 * @return {Promise<Object>} Result object with success status
 */
export async function setSiteLogoCore( {
	attachmentId,
	logoUrl,
	registry = null,
} ) {
	try {
		const { editEntityRecord } = window.wp.data.dispatch( coreStore );

		// Function to execute the logo setting operations
		const setLogoOperations = () => {
			editEntityRecord( 'root', 'site', undefined, {
				site_logo: attachmentId,
			} );
		};

		// Use batch if registry is provided (hook context), otherwise just execute
		if ( registry && typeof registry.batch === 'function' ) {
			registry.batch( setLogoOperations );
		} else {
			setLogoOperations();
		}

		// Update the CSS variable in the canvas iframe
		const { canvasiFrameRoot } = getCanvasIframeElements();
		canvasiFrameRoot?.style?.setProperty(
			'--site-logo-url',
			`url(${ logoUrl })`
		);

		logger.info( '✅ Site logo set successfully:', {
			attachmentId,
			logoUrl,
		} );

		return {
			success: true,
			attachmentId,
			logoUrl,
		};
	} catch ( error ) {
		logger.error( '❌ Error setting site logo:', error );
		return {
			success: false,
			error: error.message,
		};
	}
}
