/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Set site logo ability callback type
 */
export type SetSiteLogoCallback = ( args: {
	fileObj: {
		attachment_id: string;
		url: string;
	};
	clientId: string;
	followUpTasks?: boolean;
	summary?: string;
	messageId?: string;
} ) => Promise< {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
} >;

/**
 * Set site logo ability
 *
 * Sets the site logo in the editor.
 *
 * @param callback - The set site logo callback function from the hook
 * @return The set site logo ability definition
 */
export const setSiteLogoAbility = (
	callback: SetSiteLogoCallback
): Ability => ( {
	name: 'big-sky/set-site-logo',
	label: __( 'Set Site Logo', 'big-sky' ),
	category: 'big-sky',
	description: 'Set the site logo',
	input_schema: {
		type: 'object',
		properties: {
			fileObj: {
				type: 'object',
				properties: {
					attachment_id: { type: 'string' },
					url: { type: 'string' },
				},
			},
			clientId: { type: 'string' },
			followUpTasks: {
				type: 'boolean',
				description:
					'Deprecated. This tool always returns to the agent with a success or error message.',
			},
			summary: {
				type: 'string',
				description:
					"A short, friendly confirmation in the agent's own voice to show to the user after the site logo is set. Mention that the logo was updated briefly.",
			},
		},
		required: [ 'fileObj', 'clientId' ],
		additionalProperties: false,
	},
	output_schema: {
		type: 'object',
		properties: {
			result: {
				type: 'object',
				properties: {
					success: {
						type: 'boolean',
						description:
							'Whether the site logo was set successfully.',
					},
					message: {
						type: 'string',
						description: 'Human-readable success or error message.',
					},
					error: {
						type: 'string',
						description: 'Error details when success is false.',
					},
					details: {
						type: 'object',
						description:
							'Optional details about the updated site logo.',
					},
				},
				required: [ 'success', 'message' ],
			},
			returnToAgent: {
				type: 'boolean',
			},
		},
		required: [ 'result', 'returnToAgent' ],
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
