/**
 * Framework-agnostic core for the page-design streaming feature, shared between
 * the main Big Sky plugin and the Easy Site Editor.
 *
 * This is the transport layer: it parses the agent's streamed tool-argument
 * deltas, computes per-tool-call markup deltas, retains the latest markup for
 * late-mount replay, and exposes a handler registry so each surface can plug in
 * its own editor-apply logic. The surface-specific rendering (incremental block
 * preview, registry writes, undo strategy) lives in each host's own code.
 *
 * HARD CONSTRAINTS — keep this module consumable by BOTH builds, which differ:
 *  - No React / `@wordpress/element` / `@wordpress/block-editor` / `@wordpress/data`.
 *  - Does NOT import `@wordpress/abilities`. Main externalizes it to the
 *    `wp.abilities` global (and may not install the package at all); ESE bundles
 *    its own copy. So the ability is returned as a plain descriptor — structurally
 *    compatible with `registerAbility`'s `Ability` arg — for each surface to
 *    register with its own `registerAbility`.
 *  - No `@wordpress/i18n` / `__()`. Translatable, user/agent-facing strings are
 *    passed in per surface (each with its own textdomain) via
 *    `buildStreamPageDesignAbilityDescriptor`. The babel makepot extractor only
 *    scans each package's `src/**`, so strings placed here would never be
 *    extracted into a POT anyway.
 */

import {
	PAGE_DESIGN_STREAM_STARTED_EVENT,
	type PageDesignStreamStartedDetail,
} from './events';

// Re-exported so the transport's own importers get the event name from the same
// module they get everything else from; listeners import './events' directly.
export { PAGE_DESIGN_STREAM_STARTED_EVENT, type PageDesignStreamStartedDetail };

// Canonical identifiers shared by every surface. The tool id is what the backend
// agent emits in task-update parts and what each surface matches on, so it MUST
// be identical across surfaces.
export const STREAM_PAGE_DESIGN_ABILITY_NAME = 'big-sky/stream-page-design';
export const STREAM_PAGE_DESIGN_TOOL_ID = 'big_sky__stream_page_design';

export interface StreamPageDesignArgs {
	markup?: string;
	summary?: string;
	toolCallId?: string;
	toolId?: string;
}

export interface StreamPageDesignResult {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
	agentMessage?: string;
}

export interface StreamPageDesignUpdate {
	toolCallId: string;
	markup: string;
	delta: string;
	rawArguments?: string;
	isFinal?: boolean;
}

export type StreamPageDesignHandler = (
	update: StreamPageDesignUpdate
) => Promise< StreamPageDesignResult | void > | StreamPageDesignResult | void;
export type PrepareStreamPageDesignHandler = () => Promise< void > | void;

/** The named sections a page-design stream is split into. */
export type StreamTarget = 'page' | 'style';

interface AgentTaskUpdateLike {
	sessionId?: string;
	status?: {
		message?: {
			parts?: Array< {
				type?: string;
				data?: Record< string, unknown >;
			} >;
		};
	};
}

/**
 * User/agent-facing strings. Supplied per surface so each keeps its own
 * textdomain; English defaults below keep the module usable if a surface only
 * imports the transport functions without building the ability descriptor.
 */
export interface StreamPageDesignStrings {
	/** Returned when a stream arrives before any editor handler has registered. */
	editorLoadingMessage: string;
	/** The ability's human-readable label. */
	label: string;
	/** The ability's description (agent-facing). */
	description: string;
	/** The ability's `meta.instructions` (agent-facing). */
	instructions: string;
	/**
	 * Success message once the generated design has been staged. Used as the
	 * fallback when the model supplied no `summary` tool argument.
	 */
	stagedMessage: string;
}

const DEFAULT_STRINGS: StreamPageDesignStrings = {
	editorLoadingMessage:
		'The editor is still loading. Try the page design again once the page is editable.',
	label: 'Stream page design',
	description:
		'Streams generated page-design block markup into the editor for review before saving.',
	instructions:
		'Use this so generated Gutenberg markup can stream into the editor. The markup argument must contain wpcom:page-design-section delimiters for the page body and an optional style section.',
	stagedMessage:
		'The generated page content has been staged in the editor for review.',
};

// The strings the most-recently-built descriptor was configured with. The
// missing-handler fallback reads from here so its message matches the host
// surface's wording/textdomain once the descriptor has been built.
let configuredStrings: StreamPageDesignStrings = DEFAULT_STRINGS;

const streamStateByToolCallId = new Map<
	string,
	{
		lastMarkup: string;
		lastRawArguments: string;
	}
>();

// Retains the latest markup per tool call so it can be replayed when a real
// handler registers. The editor canvas (and therefore the stream handler) can
// finish mounting only after the markup has already streamed in; without this,
// every delta would hit the missing-handler default and be dropped.
const latestUpdateByToolCallId = new Map< string, StreamPageDesignUpdate >();

// Tool calls that have streamed markup but not yet received their end-of-stream
// final flush. The live task-update path only ever sends non-final deltas (a
// per-tool-call "final" signal can't be derived from task state alone); the
// genuine end of the stream is the ability callback (the tool round-trip
// completion). On that callback we flush these tool calls with isFinal:true so
// the editor can commit the redesign as a single native undo level.
const pendingFinalFlushToolCallIds = new Set< string >();

// Tool calls whose start has already been broadcast, so a surface listening for
// it hears the edge of the stream rather than every delta of it.
const announcedStreamToolCallIds = new Set< string >();

/**
 * Tell the page a page-design stream has started, once per tool call.
 *
 * Fired from the transport rather than the renderer because the surface that
 * needs it may not be showing the editor yet: easy mode covers the canvas with
 * its front-end preview, and has to reveal it BEFORE the first frame is staged
 * or the user watches a design build behind a screen.
 *
 * Never throws. A listener that cannot be reached must not stop the stream from
 * painting the editor underneath it.
 *
 * @param toolCallId The tool call that is streaming.
 */
function announceStreamStarted( toolCallId: string ): void {
	if ( announcedStreamToolCallIds.has( toolCallId ) ) {
		return;
	}
	announcedStreamToolCallIds.add( toolCallId );

	if ( typeof window === 'undefined' ) {
		return;
	}

	try {
		window.dispatchEvent(
			new CustomEvent< PageDesignStreamStartedDetail >(
				PAGE_DESIGN_STREAM_STARTED_EVENT,
				{ detail: { toolCallId } }
			)
		);
	} catch {
		// Nothing to do: the stream still applies.
	}
}

// The two maps above are keyed by toolCallId and would otherwise grow for the
// lifetime of the page. We scope retention to the current agent session: when a
// new session's first update arrives, the previous session's entries are cleared
// so they cannot leak memory or be replayed into an unrelated session's editor.
let lastSeenSessionId: string | undefined;

const missingStreamPageDesignHandler: StreamPageDesignHandler = async () => {
	return {
		result: {
			success: false,
			message: configuredStrings.editorLoadingMessage,
		},
		returnToAgent: false,
	};
};

// SINGLE ACTIVE RENDERER PER RUNTIME. `streamPageDesignHandler` and the retention
// maps above are module-level singletons, so at most one
// useStreamPageDesignRenderer may be mounted per JS runtime at a time. The main
// plugin mounts useStreamPageDesignTool on two mutually-exclusive surfaces (the
// wp-admin Dock via use-abilities-registration, and the Calypso unified
// experience via useAbilitiesSetup), and ESE mounts its own — each in a separate
// bundle/runtime, so they never coexist. If two renderers ever mount in the SAME
// runtime, the second setStreamPageDesignHandler() wins and the first surface's
// unmount clears the shared retention maps for both. Keep these surfaces mutually
// exclusive, or migrate this module to a per-surface keyed registry.
let streamPageDesignHandler = missingStreamPageDesignHandler;
let prepareStreamPageDesignHandler: PrepareStreamPageDesignHandler = () => {};

function isRecord( value: unknown ): value is Record< string, unknown > {
	return !! value && typeof value === 'object' && ! Array.isArray( value );
}

function decodeJsonStringEscape( escapeSequence: string ): string {
	switch ( escapeSequence ) {
		case '"':
			return '"';
		case '\\':
			return '\\';
		case '/':
			return '/';
		case 'b':
			return '\b';
		case 'f':
			return '\f';
		case 'n':
			return '\n';
		case 'r':
			return '\r';
		case 't':
			return '\t';
		default:
			return escapeSequence;
	}
}

function escapeRegExp( value: string ): string {
	return value.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
}

export function extractPartialJsonStringProperty(
	rawJson: string,
	propertyName: string
): string | null {
	const propertyPattern = new RegExp(
		`"${ escapeRegExp( propertyName ) }"\\s*:\\s*"`
	);
	const match = propertyPattern.exec( rawJson );
	if ( ! match ) {
		return null;
	}

	let index = match.index + match[ 0 ].length;
	let value = '';

	while ( index < rawJson.length ) {
		const char = rawJson[ index ];

		if ( char === '"' ) {
			return value;
		}

		if ( char === '\\' ) {
			const next = rawJson[ index + 1 ];
			if ( typeof next === 'undefined' ) {
				return value;
			}

			if ( next === 'u' ) {
				const hex = rawJson.slice( index + 2, index + 6 );
				if ( hex.length < 4 || ! /^[0-9a-fA-F]{4}$/.test( hex ) ) {
					return value;
				}
				value += String.fromCharCode( parseInt( hex, 16 ) );
				index += 6;
				continue;
			}

			value += decodeJsonStringEscape( next );
			index += 2;
			continue;
		}

		value += char;
		index += 1;
	}

	return value;
}

export function getMarkupFromArguments(
	argumentsValue: unknown
): { markup: string; rawArguments?: string } | null {
	if ( ! isRecord( argumentsValue ) ) {
		return null;
	}

	if ( typeof argumentsValue.markup === 'string' ) {
		return { markup: argumentsValue.markup };
	}

	if ( typeof argumentsValue._raw === 'string' ) {
		const markup = extractPartialJsonStringProperty(
			argumentsValue._raw,
			'markup'
		);
		if ( markup === null ) {
			return null;
		}
		return {
			markup,
			rawArguments: argumentsValue._raw,
		};
	}

	return null;
}

function stripTrailingPartialPageDesignClose( content: string ): string {
	const closeDelimiter = '<!-- /wpcom:page-design-section -->';
	const lastCommentStart = content.lastIndexOf( '<!--' );

	if ( lastCommentStart === -1 ) {
		return content;
	}

	const trailingComment = content.slice( lastCommentStart );

	if (
		trailingComment.length < closeDelimiter.length &&
		closeDelimiter.startsWith( trailingComment )
	) {
		return content.slice( 0, lastCommentStart );
	}

	return content;
}

/**
 * Extracts matching page-design section content from the accumulated markup.
 *
 * Handles a section that is still streaming (no closing delimiter yet) by
 * returning everything up to the next section start or the end of the buffer.
 * Multiple sections for the same target are concatenated; the model may emit
 * separate page sections for each top-level design section.
 *
 * @param markup The full accumulated markup.
 * @param target The section target to extract.
 * @return The aggregated section content and whether all matching sections are fully closed, or null.
 */
export function extractSection(
	markup: string,
	target: StreamTarget
): { content: string; complete: boolean } | null {
	// Match every section opening delimiter and capture its JSON body up to the
	// comment terminator, then parse the JSON to read `target`. Parsing (rather
	// than matching the closing brace with a `[^}]*` character class) tolerates
	// nested braces and `}` characters inside string values in the delimiter
	// attributes — a `[^}]*` class stops at the first `}` and silently drops the
	// whole section.
	const startPattern =
		/<!--\s*wpcom:page-design-section\s+([\s\S]*?)\s*-->/gi;
	const sectionStartPattern = /<!--\s*wpcom:page-design-section\b/gi;
	const sectionContents: string[] = [];
	let allComplete = true;
	let startMatch: RegExpExecArray | null;

	while ( ( startMatch = startPattern.exec( markup ) ) !== null ) {
		let parsedTarget: unknown;
		try {
			const parsed = JSON.parse( startMatch[ 1 ].trim() );
			parsedTarget = isRecord( parsed ) ? parsed.target : undefined;
		} catch {
			parsedTarget = undefined;
		}

		if ( parsedTarget !== target ) {
			continue;
		}

		const contentStart = startMatch.index + startMatch[ 0 ].length;
		const afterStart = markup.slice( contentStart );

		const endMatch = /<!--\s*\/wpcom:page-design-section\s*-->/i.exec(
			afterStart
		);
		if ( endMatch ) {
			sectionContents.push( afterStart.slice( 0, endMatch.index ) );
			startPattern.lastIndex =
				contentStart + endMatch.index + endMatch[ 0 ].length;
			continue;
		}

		// Section still open — stop at the next section start if one has begun.
		sectionStartPattern.lastIndex = contentStart;
		const nextStartMatch = sectionStartPattern.exec( markup );
		sectionContents.push(
			stripTrailingPartialPageDesignClose(
				markup.slice(
					contentStart,
					nextStartMatch ? nextStartMatch.index : markup.length
				)
			)
		);
		allComplete = false;
		break;
	}

	if ( sectionContents.length === 0 ) {
		return null;
	}

	return {
		content: sectionContents.join( '\n' ),
		complete: allComplete,
	};
}

/**
 * Strip surrounding `<style>` tags from a streamed style section's content.
 * @param css
 */
export function stripStyleTags( css: string ): string {
	return css
		.replace( /<style[^>]*>/gi, '' )
		.replace( /<\/style>/gi, '' )
		.trim();
}

export function setStreamPageDesignHandler(
	handler: StreamPageDesignHandler | null
): void {
	const wasMissing =
		streamPageDesignHandler === missingStreamPageDesignHandler;
	streamPageDesignHandler = handler || missingStreamPageDesignHandler;
	const isReal = streamPageDesignHandler !== missingStreamPageDesignHandler;

	// Unsetting the handler (null) means the editor that owned this stream is
	// going away — e.g. the user navigated to another page. Drop the retained
	// markup so it is NOT replayed onto the next page's editor when that editor
	// registers its handler (which would re-apply the previous page's design to
	// an unrelated page). The retained buffer only exists to catch up an editor
	// that mounts late during the SAME generation; once the editor unmounts it
	// is stale. An ongoing live stream re-populates from its cumulative markup.
	if ( ! handler ) {
		streamStateByToolCallId.clear();
		latestUpdateByToolCallId.clear();
		pendingFinalFlushToolCallIds.clear();
		announcedStreamToolCallIds.clear();
		return;
	}

	// When a real handler registers after markup has already streamed (the
	// editor canvas mounts asynchronously), replay the latest accumulated
	// markup so the editor catches up. The handler recomputes its own delta
	// from the full markup, so a single replay renders the whole page.
	//
	// Replay with isFinal:false: this is a catch-up, not necessarily the end of
	// the stream. The handler's throttled-flush path still renders the buffered
	// markup (and fires onApplied when it stages), but routing through the
	// throttle avoids a synchronous full-page parse on the main thread at the
	// moment the canvas is mounting, and avoids firing onApplied prematurely for
	// a design that is still streaming. The genuine end-of-stream final flush is
	// delivered by the live update path.
	if ( wasMissing && isReal && latestUpdateByToolCallId.size > 0 ) {
		for ( const update of latestUpdateByToolCallId.values() ) {
			void Promise.resolve(
				streamPageDesignHandler( { ...update, isFinal: false } )
			);
		}
	}
}

export function setPrepareStreamPageDesignHandler(
	handler: PrepareStreamPageDesignHandler | null
): void {
	prepareStreamPageDesignHandler = handler || ( () => {} );
}

export function taskUpdateIncludesStreamPageDesign(
	update: AgentTaskUpdateLike
): boolean {
	return Boolean(
		update.status?.message?.parts?.some(
			( part ) =>
				part.type === 'data' &&
				part.data?.toolId === STREAM_PAGE_DESIGN_TOOL_ID &&
				part.data?.toolCallId
		)
	);
}

export function taskUpdateIncludesStreamPageDesignMarkup(
	update: AgentTaskUpdateLike
): boolean {
	return Boolean(
		update.status?.message?.parts?.some(
			( part ) =>
				part.type === 'data' &&
				part.data?.toolId === STREAM_PAGE_DESIGN_TOOL_ID &&
				part.data?.toolCallId &&
				getMarkupFromArguments( part.data.arguments )
		)
	);
}

export async function handleStreamPageDesignTaskUpdate(
	update: AgentTaskUpdateLike
): Promise< void > {
	// Clear retained stream state from a previous session before processing a
	// new session's updates, so stale markup is neither leaked nor replayed into
	// an unrelated session's editor.
	if (
		update.sessionId &&
		lastSeenSessionId &&
		update.sessionId !== lastSeenSessionId
	) {
		streamStateByToolCallId.clear();
		latestUpdateByToolCallId.clear();
		pendingFinalFlushToolCallIds.clear();
		announcedStreamToolCallIds.clear();
	}
	if ( update.sessionId ) {
		lastSeenSessionId = update.sessionId;
	}

	const parts = update.status?.message?.parts || [];
	for ( const part of parts ) {
		if (
			part.type !== 'data' ||
			part.data?.toolId !== STREAM_PAGE_DESIGN_TOOL_ID ||
			typeof part.data.toolCallId !== 'string'
		) {
			continue;
		}

		const markupData = getMarkupFromArguments( part.data.arguments );
		if ( ! markupData ) {
			continue;
		}

		const toolCallId = part.data.toolCallId;

		// Before any bookkeeping and before the handler stages a single frame:
		// a surface that has to uncover the editor needs the news first.
		announceStreamStarted( toolCallId );

		const state = streamStateByToolCallId.get( toolCallId ) || {
			lastMarkup: '',
			lastRawArguments: '',
		};
		const delta = markupData.markup.startsWith( state.lastMarkup )
			? markupData.markup.slice( state.lastMarkup.length )
			: markupData.markup;

		streamStateByToolCallId.set( toolCallId, {
			lastMarkup: markupData.markup,
			lastRawArguments: markupData.rawArguments || state.lastRawArguments,
		} );

		// Retain the latest full markup so it can be replayed once the editor
		// handler registers (the canvas may still be mounting while we stream).
		latestUpdateByToolCallId.set( toolCallId, {
			toolCallId,
			markup: markupData.markup,
			delta,
			rawArguments: markupData.rawArguments,
		} );

		// Mark this tool call as awaiting its end-of-stream final flush, which
		// the ability callback delivers once the tool round-trip completes.
		pendingFinalFlushToolCallIds.add( toolCallId );

		if ( ! delta ) {
			continue;
		}

		await streamPageDesignHandler( {
			toolCallId,
			markup: markupData.markup,
			delta,
			rawArguments: markupData.rawArguments,
		} );
	}
}

/**
 * A plain ability descriptor. Structurally compatible with the `Ability` shape
 * `@wordpress/abilities`' `registerAbility` accepts, but declared locally so this
 * module never imports `@wordpress/abilities` (see the file header).
 */
export interface StreamPageDesignAbilityDescriptor {
	name: string;
	label: string;
	category: string;
	description: string;
	input_schema: Record< string, unknown >;
	output_schema: Record< string, unknown >;
	meta: Record< string, unknown >;
	callback: (
		args?: StreamPageDesignArgs
	) => Promise< StreamPageDesignResult >;
}

export interface BuildStreamPageDesignAbilityOptions {
	/** The host surface's ability category slug (e.g. 'big-sky'). */
	category: string;
	/** Per-surface translated strings; merged over English defaults. */
	strings?: Partial< StreamPageDesignStrings >;
	/** Optional error logger; defaults to a no-op. */
	logError?: ( ...args: unknown[] ) => void;
}

/**
 * Build the stream-page-design ability descriptor for a host surface. The caller
 * registers the returned descriptor with its own `registerAbility` (and decides
 * whether to guard against double-registration). The markup itself is applied
 * through the registered stream handler during the live task-update stream; this
 * ability's callback delivers the genuine end-of-stream final flush.
 *
 * @param options Host configuration.
 */
export function buildStreamPageDesignAbilityDescriptor(
	options: BuildStreamPageDesignAbilityOptions
): StreamPageDesignAbilityDescriptor {
	configuredStrings = { ...DEFAULT_STRINGS, ...options.strings };
	const strings = configuredStrings;
	const logError = options.logError || ( () => undefined );

	return {
		name: STREAM_PAGE_DESIGN_ABILITY_NAME,
		label: strings.label,
		category: options.category,
		description: strings.description,
		input_schema: {
			type: 'object',
			required: [ 'markup' ],
			additionalProperties: false,
			properties: {
				markup: {
					type: 'string',
					description:
						'Delimited Gutenberg block markup for the page design stream.',
				},
				summary: {
					type: 'string',
					description:
						'Short, user-friendly summary of the finished page design, in natural language a non-technical user understands. Shown to the user when the design has been staged. No block names or technical details.',
				},
			},
		},
		output_schema: {
			type: 'object',
			properties: {
				result: {
					type: 'object',
					properties: {
						success: {
							type: 'boolean',
							description:
								'Whether the generated page design was staged successfully.',
						},
						message: {
							type: 'string',
							description:
								'Human-readable success or error message.',
						},
						error: {
							type: 'string',
							description: 'Error details when success is false.',
						},
						details: {
							type: 'object',
							description:
								'Optional details about the staged page design.',
						},
					},
					required: [ 'success', 'message' ],
				},
				returnToAgent: {
					type: 'boolean',
				},
				agentMessage: {
					type: 'string',
				},
			},
			required: [ 'result', 'returnToAgent' ],
		},
		meta: {
			streaming: {
				enabled: true,
				mode: 'tool_argument_delta',
				argumentPath: 'markup',
				eagerInputStreaming: true,
			},
			instructions: strings.instructions,
		},
		callback: async ( args?: StreamPageDesignArgs ) => {
			// The markup has already streamed into the editor via onTaskUpdate;
			// this delegated call just completes the agent's tool round-trip.
			// returnToAgent must be true (like apply-block-edits) so the agent
			// receives the result and finishes its turn; false leaves it
			// hanging in input-required and the chat freezes on "thinking".
			await prepareStreamPageDesignHandler();

			// Model-written summary of the design (like apply-block-edits'
			// `summary` argument). It becomes the user-visible completion
			// message: chat clients render it from the tool result / the
			// agentMessage below, and dolly's echoed-result ack repeats it.
			const summary =
				typeof args?.summary === 'string' && args.summary.trim()
					? args.summary.trim()
					: strings.stagedMessage;

			// The live task-update path only streams non-final deltas, so this
			// round-trip completion is the genuine end of the stream. Deliver a
			// final flush for each tool call that streamed (keyed by its retained
			// full markup) so the editor finalizes preview blocks and commits the
			// redesign as a single native undo level.
			const toolCallIdsToFinalize = Array.from(
				pendingFinalFlushToolCallIds
			);
			pendingFinalFlushToolCallIds.clear();
			for ( const toolCallId of toolCallIdsToFinalize ) {
				const update = latestUpdateByToolCallId.get( toolCallId );
				if ( ! update ) {
					continue;
				}
				try {
					await streamPageDesignHandler( {
						...update,
						isFinal: true,
					} );
				} catch ( finalFlushError ) {
					// Don't fail the tool round-trip if the final flush throws;
					// the streamed preview is already in the editor.
					logError(
						'Page design final flush failed:',
						finalFlushError
					);
				}
			}

			return {
				result: {
					success: true,
					message: summary,
				},
				returnToAgent: true,
				// `data.summary` (not `message`) so tool-summary renderers —
				// e.g. Agents Manager's getDisplayMessageFromToolData, which
				// reads data.summary / data.result.message — can display it.
				agentMessage: JSON.stringify( {
					tool_id: STREAM_PAGE_DESIGN_TOOL_ID,
					data: {
						summary,
						isCurrent: true,
					},
				} ),
			};
		},
	};
}
