/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Internal dependencies
 */
import type { FilePart } from '@utils/canvas-capture';

/**
 * Apply block edits ability callback type
 */
export type ApplyBlockEditsCallback = ( args: {
	updates?: any[];
	inserts?: any[];
	deletes?: any[];
	summary?: string;
	followUpTasks?: boolean;
	messageId?: string;
	toolCallId?: string;
	suppressAssistantMessage?: boolean;
	visualCheckPending?: boolean;
	resetBlockProcessingStates?: boolean;
	reverseMap?: any;
	customCSS?: string;
} ) => Promise< {
	result: {
		success: boolean;
		message: string;
		outcome?: 'updated' | 'no-changes';
		changeType?: 'text-content' | 'other';
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
	agentMessage?: string;
	// A sibling of `result`, not part of it: the agent client lifts this onto the
	// tool-result part rather than into the result the model reads as text.
	__file_parts?: FilePart[];
} >;

/**
 * Apply block edits ability
 *
 * Applies a collection of block edits (updates, insertions, deletions) to the canvas.
 *
 * @param callback - The apply block edits callback function from the hook
 * @return The apply block edits ability definition
 */
export const applyBlockEditsAbility = (
	callback: ApplyBlockEditsCallback
): Ability => ( {
	name: 'big-sky/apply-block-edits',
	label: __( 'Apply Block Edits', 'big-sky' ),
	category: 'big-sky',
	description: 'Applies a collection of block edits to the canvas',
	input_schema: {
		type: 'object',
		properties: {
			updates: {
				type: 'array',
				description: 'Array of block updates to apply',
			},
			inserts: {
				type: 'array',
				description: 'Array of block insertions to apply',
			},
			deletes: {
				type: 'array',
				description: 'Array of block deletions (clientIds) to apply',
			},
			summary: {
				type: 'string',
				description: 'Summary message to show to the user',
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Deprecated. This tool always returns to the agent with a success or error message.',
			},
			messageId: {
				type: 'string',
				description: 'Optional message ID for context',
			},
			suppressAssistantMessage: {
				type: 'boolean',
				description: 'Whether to suppress assistant message',
			},
			visualCheckPending: {
				type: 'boolean',
				description:
					'Set by the server, never by the model: the acknowledgement for this call may be held back until the canvas capture attached to the result has been looked at. Forwarded to the client only when a capture was actually produced.',
			},
			resetBlockProcessingStates: {
				type: 'boolean',
				description: 'Whether to reset block processing states',
			},
			reverseMap: {
				type: 'object',
				description: 'Optional reverse mapping for client IDs',
			},
			customCSS: {
				type: 'string',
				description:
					'Full custom CSS value to replace the site global styles CSS',
			},
		},
	},
	output_schema: {
		type: 'object',
		properties: {
			result: {
				type: 'object',
				properties: {
					success: {
						type: 'boolean',
						description:
							'Whether the block edits were applied successfully.',
					},
					message: {
						type: 'string',
						description: 'Human-readable success or error message.',
					},
					outcome: {
						type: 'string',
						enum: [ 'updated', 'no-changes' ],
						description:
							'Whether a successful call changed editor content.',
					},
					changeType: {
						type: 'string',
						enum: [ 'text-content', 'other' ],
						description:
							'Whether the edit only updated block text content or included another change type.',
					},
					error: {
						type: 'string',
						description: 'Error details when success is false.',
					},
					details: {
						type: 'object',
						description:
							'Optional details about the applied changes.',
					},
				},
				required: [ 'success', 'message' ],
			},
			returnToAgent: {
				type: 'boolean',
			},
			agentMessage: {
				type: 'string',
			},
			__file_parts: {
				type: 'array',
				description:
					'Files (typically a canvas screenshot) sent alongside the result rather than inside it. Omitted when the tool produced none.',
			},
		},
		required: [ 'result', 'returnToAgent' ],
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
