/**
 * Console helpers for inspecting a canvas capture during development.
 *
 * `captureCanvasFileParts` swallows every failure and returns null, which is
 * right for the tool — a capture must never fail an edit — but useless when the
 * question is why no image came back. These call the rasterizer directly so the
 * refusal surfaces, and render the result in the console.
 *
 * Available in the browser as `bigSkyCaptureCanvas()` and
 * `bigSkyCheckCanvasStyles()` wherever the abilities are registered.
 */

/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import {
	buildCanvasSvg,
	bytesToBase64,
	getLastCaptureStages,
	rasterizeCanvas,
} from '@utils/canvas-rasterizer';

/* eslint-disable no-console */

interface DebugCaptureResult {
	dataUrl: string;
	blobUrl: string;
	width: number;
	height: number;
	kilobytes: number;
	milliseconds: number;
}

/**
 * Runs `work` and reports how long it took.
 *
 * Timing is measured around the rasterizer alone, so the number reflects what a
 * real capture would cost rather than including the preview work below it.
 *
 * @param {Function} work The work to time.
 * @return {Promise<{value: any, milliseconds: number}>} The result and duration.
 */
const timed = async < T >(
	work: () => Promise< T >
): Promise< { value: T; milliseconds: number } > => {
	const startedAt = performance.now();
	const value = await work();

	return { value, milliseconds: Math.round( performance.now() - startedAt ) };
};

const base64ToBlob = ( base64: string, mimeType: string ): Blob => {
	const binary = atob( base64 );
	const bytes = new Uint8Array( binary.length );

	for ( let index = 0; index < binary.length; index++ ) {
		bytes[ index ] = binary.charCodeAt( index );
	}

	return new Blob( [ bytes ], { type: mimeType } );
};

/**
 * Reports which of the canvas stylesheets can be read directly.
 *
 * A sheet listed as unreadable here is not necessarily lost: a `<link>` written
 * without `crossorigin="anonymous"` is opaque to `cssRules` however permissive
 * its server is, and the capture refetches those over the network, where the
 * CORS headers apply. Read this as the list of sheets whose fate depends on that
 * second attempt — and check the network tab for their hrefs when a capture
 * comes back looking unstyled.
 *
 * @return {Array<{href: string, readable: boolean, rules: number}>} Per sheet.
 */
export const checkCanvasStyles = () => {
	const { canvasiFrameDocument } = getCanvasIframeElements();

	if ( ! canvasiFrameDocument ) {
		console.error( '[Canvas Capture] No canvas iframe on this screen.' );
		return [];
	}

	const report = (
		Array.from( canvasiFrameDocument.styleSheets ) as CSSStyleSheet[]
	 ).map( ( sheet ) => {
		try {
			return {
				href: sheet.href || '(inline)',
				readable: true,
				rules: sheet.cssRules.length,
			};
		} catch ( error ) {
			return {
				href: sheet.href || '(inline)',
				readable: false,
				rules: 0,
			};
		}
	} );

	console.table( report );

	const blocked = report.filter( ( sheet ) => ! sheet.readable );
	if ( blocked.length ) {
		console.warn(
			`[Canvas Capture] ${ blocked.length } stylesheet(s) cannot be read directly; the capture will refetch them, and drop any whose server sends no CORS headers.`,
			blocked.map( ( sheet ) => sheet.href )
		);
	}

	return report;
};

/**
 * Captures the canvas and previews it in the console.
 *
 * @param {string[]} clientIds        Blocks to frame; omit to capture the viewport.
 * @param {Object}   options          Capture options.
 * @param {boolean}  options.fullPage Capture the whole page, stitched from bands.
 * @return {Promise<DebugCaptureResult|null>} The capture, or null when refused.
 */
export const debugCaptureCanvas = async (
	clientIds: string[] = [],
	{ fullPage = false }: { fullPage?: boolean } = {}
): Promise< DebugCaptureResult | null > => {
	const { canvasiFrameDocument, canvasiFrameWindow } =
		getCanvasIframeElements();

	if ( ! canvasiFrameDocument || ! canvasiFrameWindow ) {
		console.error( '[Canvas Capture] No canvas iframe on this screen.' );
		return null;
	}

	let capture;

	try {
		capture = await timed( () =>
			rasterizeCanvas( {
				canvasDocument: canvasiFrameDocument,
				canvasWindow: canvasiFrameWindow,
				clientIds,
				fullPage,
			} )
		);
	} catch ( error ) {
		// The interesting case. In the tool this becomes a silent null, so this
		// is the only place the reason is visible.
		console.error( '[Canvas Capture] Refused to capture:', error );
		return null;
	}

	const { value: fileParts, milliseconds } = capture;
	const part = fileParts?.[ 0 ];

	if ( ! part?.file?.bytes ) {
		console.warn( '[Canvas Capture] Produced no image.' );
		return null;
	}

	const mimeType = part.file.mimeType || 'image/webp';
	const dataUrl = `data:${ mimeType };base64,${ part.file.bytes }`;
	const blobUrl = URL.createObjectURL(
		base64ToBlob( part.file.bytes, mimeType )
	);

	const image = new window.Image();
	image.src = dataUrl;
	await image.decode();

	// Chrome renders a background image behind console output, which is the only
	// way to see the capture without leaving the page.
	console.log(
		'%c ',
		[
			'font-size: 1px',
			`padding: ${ Math.floor(
				image.naturalHeight / 2
			) }px ${ Math.floor( image.naturalWidth / 2 ) }px`,
			`background: url( ${ dataUrl } ) no-repeat`,
			`background-size: ${ image.naturalWidth }px ${ image.naturalHeight }px`,
		].join( ';' )
	);

	const result = {
		dataUrl,
		blobUrl,
		width: image.naturalWidth,
		height: image.naturalHeight,
		kilobytes: Math.round( ( part.file.bytes.length * 3 ) / 4 / 1024 ),
		milliseconds,
		// `css` splits into `css_read` (walking ~12,000 rules) and `css_fonts`
		// (fetching and base64-encoding them). They have different fixes, so
		// which dominates decides whether a cache is worth its invalidation
		// risk or whether the immutable font URLs are enough on their own.
		stages: getLastCaptureStages(),
	};

	console.log( '[Canvas Capture]', {
		...result,
		dataUrl: `${ dataUrl.slice( 0, 48 ) }…`,
	} );
	console.log(
		`[Canvas Capture] Open full size: ${ blobUrl } — images are placeholders by design.`
	);

	return result;
};

/**
 * Opens the SVG a capture would rasterize, as a document.
 *
 * When the rendered image disagrees with the page, an `<img>` gives nothing to
 * inspect. Opened as a document the same SVG is a live DOM: DevTools can show
 * whether the content laid out and what the cascade actually resolved to.
 *
 * One caveat when reading the result — an SVG viewed as a document may load
 * external resources that the `<img>` path blocks, so it is a view of the layout
 * and cascade, not a pixel-exact preview of the capture.
 *
 * @param {string[]} clientIds Blocks to frame; omit for the viewport.
 * @return {Promise<string|null>} The SVG source.
 */
export const debugCanvasSvg = async (
	clientIds: string[] = []
): Promise< string | null > => {
	const { canvasiFrameDocument, canvasiFrameWindow } =
		getCanvasIframeElements();

	if ( ! canvasiFrameDocument || ! canvasiFrameWindow ) {
		console.error( '[Canvas Capture] No canvas iframe on this screen.' );
		return null;
	}

	const built = await buildCanvasSvg( {
		canvasDocument: canvasiFrameDocument,
		canvasWindow: canvasiFrameWindow,
		clientIds,
	} );

	if ( ! built ) {
		console.warn( '[Canvas Capture] Produced no SVG.' );
		return null;
	}

	const url = URL.createObjectURL(
		new Blob( [ built.svg ], { type: 'image/svg+xml' } )
	);

	console.log( '[Canvas Capture] SVG', {
		bytes: built.svg.length,
		rect: built.rect,
		url,
	} );
	window.open( url, '_blank' );

	return built.svg;
};

/**
 * Rasterizes the whole document with no cropping, and previews it.
 *
 * The one experiment that separates "the SVG does not rasterize" from "the crop
 * is wrong". Captures that work have all been roughly viewport-sized; a
 * full-page SVG is several times taller, and a `foreignObject` that fails to
 * rasterize at that size looks exactly like a bad crop — both produce a blank
 * draw. Drawing the entire image, scaled to fit, tells the two apart.
 *
 * @param {string[]} clientIds Ignored for framing; kept so the same call shape
 *                             works as the other helpers.
 * @return {Promise<string|null>} A blob URL for the full-page render.
 */
export const debugCanvasFullPage = async (
	clientIds: string[] = []
): Promise< string | null > => {
	const { canvasiFrameDocument, canvasiFrameWindow } =
		getCanvasIframeElements();

	if ( ! canvasiFrameDocument || ! canvasiFrameWindow ) {
		console.error( '[Canvas Capture] No canvas iframe on this screen.' );
		return null;
	}

	const built = await buildCanvasSvg( {
		canvasDocument: canvasiFrameDocument,
		canvasWindow: canvasiFrameWindow,
		clientIds,
	} );

	if ( ! built ) {
		console.warn( '[Canvas Capture] Produced no SVG.' );
		return null;
	}

	const image = new window.Image();
	// Chunked, via the rasterizer's own encoder: spreading a multi-megabyte byte
	// array into `String.fromCharCode` overflows the call stack.
	image.src = `data:image/svg+xml;base64,${ bytesToBase64(
		new TextEncoder().encode( built.svg )
	) }`;
	await image.decode();
	await new Promise( ( resolve ) => setTimeout( resolve, 500 ) );

	const scale = Math.min(
		1,
		1400 / Math.max( image.naturalWidth, image.naturalHeight )
	);
	const canvas = document.createElement( 'canvas' );
	canvas.width = Math.round( image.naturalWidth * scale );
	canvas.height = Math.round( image.naturalHeight * scale );
	canvas
		.getContext( '2d' )
		?.drawImage( image, 0, 0, canvas.width, canvas.height );

	const dataUrl = canvas.toDataURL( 'image/webp', 0.8 );

	console.log(
		'%c ',
		[
			'font-size: 1px',
			`padding: ${ Math.floor( canvas.height / 2 ) }px ${ Math.floor(
				canvas.width / 2
			) }px`,
			`background: url( ${ dataUrl } ) no-repeat`,
			`background-size: ${ canvas.width }px ${ canvas.height }px`,
		].join( ';' )
	);
	console.log( '[Canvas Capture] Full page', {
		svgSize: { width: image.naturalWidth, height: image.naturalHeight },
		drawnSize: { width: canvas.width, height: canvas.height },
		kilobytes: Math.round( dataUrl.length / 1024 ),
	} );

	return dataUrl;
};

declare global {
	interface Window {
		bigSkyCaptureCanvas?: typeof debugCaptureCanvas;
		bigSkyCheckCanvasStyles?: typeof checkCanvasStyles;
		bigSkyCanvasSvg?: typeof debugCanvasSvg;
		bigSkyCanvasFullPage?: typeof debugCanvasFullPage;
	}
}

if ( typeof window !== 'undefined' ) {
	window.bigSkyCaptureCanvas = debugCaptureCanvas;
	window.bigSkyCheckCanvasStyles = checkCanvasStyles;
	window.bigSkyCanvasSvg = debugCanvasSvg;
	window.bigSkyCanvasFullPage = debugCanvasFullPage;
}
