/**
 * Internal dependencies
 */
import uuidv4 from '@utils/uuid';
import {
	defaultSiteMetadata,
	EXTERNAL_IMAGE_MODELS,
	INTERNAL_IMAGE_MODELS,
} from '@utils/constants';

export const initialState = {
	bigSkyInitialState: window?.bigSkyInitialState, // Initial state passed from localized_script
	bigSkyPendingSpec: null, // Initial state of pending spec data - used to determine if build task should be triggered

	// chat completion
	apiKey: '',
	pendingToolCallbacks: 0,
	hasRetriedChatRequest: false,
	messages: [],
	isThinking: false,
	thinkingMessage: '',

	isSiteBuildStructurePhase: false, // True during structure phase (dock hidden)

	// chat model
	advancedChatModel: 'gpt-4.1-2025-04-14',
	basicChatModel: 'gpt-4.1-nano-2025-04-14',
	imageGenModel:
		typeof window !== 'undefined' &&
		window.localStorage.getItem( 'useLocalImageModel' ) === 'true'
			? INTERNAL_IMAGE_MODELS.FLUX
			: EXTERNAL_IMAGE_MODELS.GEMINI_2_5_FLASH,
	imageGenQuality: 'medium',
	logoGenModel: EXTERNAL_IMAGE_MODELS.GPT_IMAGE_1,
	logoGenQuality: 'low',
	openAIUsage: {},
	anthropicUsage: {},

	// content
	cachedContent: {},
	fullPageStructure: {
		summary: '',
		clientIdMap: {},
	},

	// delay settings
	delaySettings: {
		onboarding: {
			afterBlockProcessed: 1000,
			afterScrollToBlock: 1500,
		},
	},

	// dock state
	isDraggingOver: false, // used to track if files are being dragged over the chat view
	inputtedFiles: [],
	suppressSuggestions: false,
	messagesToDelete: [],
	hideImageUploader: false,

	// editor state
	isEditorReady: false, // used to determine if the editor is loaded and contains blocks
	isEditorIframeLoaded: false, // used to determine if the editor iframe DOM elements are loaded
	siteEditorActions: {}, // recent user actions in the site editor surfaced to agent client context
	legacyCssBlocks: [], // legacy Easy Site Editor CSS blocks found in the user's Additional CSS
	checkpoints: [], // used to store multiple checkpoints as an array to preserve order
	mosaicEnabled: false, // used to determine if the mosaic feature is enabled

	// image drop
	draggedImageFile: null,

	// routing
	currentAiStep:
		new URL( window.location.href ).searchParams.get( 'ai-step' ) || null,
	previousAiStep: null,

	// session logging
	logSessions: true,
	sessionId: uuidv4(),

	// site design
	// TODO: update the defaults
	generatedVariations: [],
	isBuildingSite: false,
	headerSectionIsReady: false,
	pendingPageImageProcessing: [],
	currentColor: '',
	currentFont: '',
	imageStyle: '',
	isTyping: false,
	siteMetadata:
		window?.bigSkyInitialState?.siteMetadata ?? defaultSiteMetadata,
	initializedCustomScheme: false,
	customVariationTemplates: [],
	currentPaletteColors: [],

	// Google Fonts
	googleFonts: {
		font_families: [],
	},

	// assistant state
	callbacks: {},
	contexts: {},
	error: null,

	// build error dialog
	buildErrorDialog: {
		isOpen: false,
		message: null,
	},
};

export function reducer( state = initialState, action ) {
	const cachedContentKey = `bigSkyCachedContent${ window.Jetpack_Editor_Initial_State?.wpcomBlogId }`;
	switch ( action.type ) {
		case 'SET_GOOGLE_FONTS_COLLECTION':
			return {
				...state,
				googleFonts: action.payload,
			};
		case 'SET_IS_DRAGGING_OVER':
			return {
				...state,
				isDraggingOver: action.payload,
			};
		case 'SET_SESSION_ID':
			return {
				...state,
				sessionId: action.payload,
			};
		case 'SET_SESSION_LOGGED':
			return {
				...state,
				sessionLogged: action.payload,
			};
		case 'SET_IS_EDITOR_READY':
			return {
				...state,
				isEditorReady: action.payload,
			};
		case 'SET_IS_EDITOR_IFRAME_LOADED':
			return {
				...state,
				isEditorIframeLoaded: action.payload,
			};
		case 'SET_CACHED_CONTENT':
			// eslint-disable-next-line no-undef
			localStorage.setItem(
				cachedContentKey,
				JSON.stringify( { ...action.payload, lastUpdated: Date.now() } )
			);
			return {
				...state,
				cachedContent: action.payload,
			};
		case 'ADD_CACHED_IMAGE':
			const { cacheKey, imageData } = action.payload;
			const existingData = state.cachedContent[ cacheKey ];
			let updatedData;

			if ( Array.isArray( existingData ) ) {
				// Filter out any null values from existing data
				const cleanExistingData = existingData.filter(
					( item ) => item !== null
				);

				// If existing data is an array, check if imageData with same URL exists
				const existingIndex = cleanExistingData.findIndex(
					( item ) => item && item.url === imageData.url
				);

				if ( existingIndex !== -1 ) {
					// Update existing imageData
					updatedData = [ ...cleanExistingData ];
					updatedData[ existingIndex ] = imageData;
				} else {
					// Append new imageData
					updatedData = [ ...cleanExistingData, imageData ];
				}
			} else {
				// If no existing data or it's not an array, store as single item
				updatedData = [ imageData ];
			}

			const updatedCachedContent = {
				...state.cachedContent,
				[ cacheKey ]: updatedData,
			};
			// eslint-disable-next-line no-undef
			localStorage.setItem(
				cachedContentKey,
				JSON.stringify( {
					...updatedCachedContent,
					lastUpdated: Date.now(),
				} )
			);
			return {
				...state,
				cachedContent: updatedCachedContent,
			};
		case 'SET_IS_BUILDING_SITE':
			return {
				...state,
				isBuildingSite: action.payload,
			};
		case 'SET_IS_SITE_BUILD_STRUCTURE_PHASE':
			return {
				...state,
				isSiteBuildStructurePhase: action.payload,
			};
		case 'SET_IS_PROCESSING_SPEC':
			return {
				...state,
				isProcessingSpec: action.payload,
			};
		case 'INCREMENT_PENDING_TOOL_CALLBACKS':
			return {
				...state,
				pendingToolCallbacks: state.pendingToolCallbacks + 1,
			};
		case 'DECREMENT_PENDING_TOOL_CALLBACKS':
			return {
				...state,
				pendingToolCallbacks: Math.max(
					0,
					state.pendingToolCallbacks - 1
				),
			};
		case 'SET_INITIALIZED_CUSTOM_SCHEME':
			return {
				...state,
				initializedCustomScheme: action.payload,
			};
		case 'PUSH_GENERATED_VARIATIONS':
			return {
				...state,
				generatedVariations: [
					...action.payload,
					...state.generatedVariations,
				],
			};
		case 'MODIFY_GENERATED_VARIATION':
			const { name, variation } = action.payload;
			const variations = state.generatedVariations.map( ( v ) =>
				v.title === name ? variation : v
			);

			if ( ! variations.includes( variation ) ) {
				variations.push( variation );
			}

			return {
				...state,
				generatedVariations: variations,
			};
		case 'CLEAR_GENERATED_VARIATIONS':
			return {
				...state,
				generatedVariations: [],
			};
		case 'SET_IMAGE_STYLE':
			return {
				...state,
				imageStyle: action.payload,
			};
		case 'SET_INPUTTED_FILES':
			const current = state.inputtedFiles ?? [];
			const next = action.payload ?? [];

			for ( const currentFile of current ) {
				if (
					next.some(
						( nextFile ) => nextFile.url === currentFile.url
					)
				) {
					continue;
				}

				// Only revoke blob URLs, not server URLs
				if (
					currentFile.url &&
					currentFile.url.startsWith( 'blob:' )
				) {
					URL.revokeObjectURL( currentFile.url );
				}
			}
			return {
				...state,
				inputtedFiles: next,
			};
		case 'SET_SUPPRESS_SUGGESTIONS':
			return {
				...state,
				suppressSuggestions: action.payload,
			};
		case 'SET_CURRENT_COLOR':
			return {
				...state,
				currentColor: action.payload,
			};
		case 'SET_CURRENT_FONT':
			return {
				...state,
				currentFont: action.payload,
			};
		case 'SET_CURRENT_BUTTON_STYLE':
			return {
				...state,
				currentButtonStyle: action.payload,
			};
		case 'SET_IS_TYPING':
			return {
				...state,
				isTyping: action.payload,
			};
		case 'SET_SITE_EDITOR_ACTION':
			return {
				...state,
				siteEditorActions: {
					...state.siteEditorActions,
					[ action.payload.name ]: action.payload.value,
				},
			};
		case 'SET_API_KEY':
			return {
				...state,
				apiKey: action.payload,
			};
		case 'SET_HAS_RETRIED_CHAT_REQUEST':
			return {
				...state,
				hasRetriedChatRequest: action.payload,
			};
		case 'SET_SITE_METADATA':
			return {
				...state,
				siteMetadata: {
					...state.siteMetadata,
					...action.payload,
				},
			};
		case 'RESET_STORE':
			// this gets called in the error boundary
			return {
				...initialState,
				// we need to keep some values from the current state
				apiKey: state.apiKey,
				cachedContent: state.cachedContent,
				siteMetadata: state.siteMetadata,
			};
		case 'SET_CUSTOM_VARIATION_TEMPLATES':
			return {
				...state,
				customVariationTemplates: action.payload,
			};
		case 'SET_CURRENT_PALETTE_COLORS':
			return {
				...state,
				currentPaletteColors: action.payload,
			};
		case 'SET_LEGACY_CSS_BLOCKS':
			return {
				...state,
				legacyCssBlocks: action.payload,
			};
		case 'ADD_MESSAGE_TO_DELETE':
			return {
				...state,
				messagesToDelete: [ ...state.messagesToDelete, action.message ],
			};
		case 'CLEAR_MESSAGES_TO_DELETE':
			return {
				...state,
				messagesToDelete: [],
			};
		case 'ADD_CHECKPOINT':
			return {
				...state,
				checkpoints: [
					...state.checkpoints,
					{
						...action.editorState,
						id: action.id,
					},
				],
			};
		case 'CHANGE_CHECKPOINT_ID':
			// given an original id and a new id, update the checkpoint
			return {
				...state,
				checkpoints: state.checkpoints.map( ( checkpoint ) =>
					checkpoint.id === action.originalId
						? { ...checkpoint, id: action.newId }
						: checkpoint
				),
			};
		case 'UPDATE_CHECKPOINT':
			return {
				...state,
				checkpoints: state.checkpoints.map( ( checkpoint ) =>
					checkpoint.id === action.id
						? { ...action.editorState, id: action.id }
						: checkpoint
				),
			};
		case 'REMOVE_CHECKPOINT':
			return {
				...state,
				checkpoints: state.checkpoints.filter(
					( checkpoint ) => checkpoint.id !== action.id
				),
			};
		case 'ADD_MESSAGE':
			return {
				...state,
				messages: [ ...state.messages, action.message ],
			};
		case 'SET_THINKING':
			return {
				...state,
				isThinking: action.payload,
			};
		case 'SET_THINKING_MESSAGE':
			return {
				...state,
				thinkingMessage: action.payload,
			};
		case 'CLEAR_MESSAGES':
			return {
				...state,
				messages: [],
				checkpoints: [],
			};
		case 'DELETE_MESSAGE':
			return {
				...state,
				messages: state.messages.filter(
					( m ) => m.id !== action.payload
				),
			};
		case 'UPDATE_MESSAGE':
			return {
				...state,
				messages: state.messages.map( ( message ) =>
					message.id === action.id
						? { ...message, ...action.updates }
						: message
				),
			};
		case 'REGISTER_CALLBACKS':
			return {
				...state,
				callbacks: {
					...state.callbacks,
					[ action.name ]: action.callbacks,
				},
			};
		case 'SET_ERROR':
			return { ...state, error: action.error };
		case 'SET_BUILD_ERROR_DIALOG':
			return {
				...state,
				buildErrorDialog: action.payload,
			};
		case 'SET_HEADER_SECTION_IS_READY':
			return {
				...state,
				headerSectionIsReady: action.payload,
			};
		case 'SET_PENDING_PAGE_IMAGE_PROCESSING':
			return {
				...state,
				pendingPageImageProcessing: action.payload,
			};
		case 'CLEAR_PENDING_PAGE_IMAGE_PROCESSING':
			return {
				...state,
				pendingPageImageProcessing: [],
			};
		case 'SET_FULL_PAGE_STRUCTURE':
			return {
				...state,
				fullPageStructure: action.payload,
			};
		case 'SET_AI_STEP':
			return {
				...state,
				previousAiStep:
					action.previousStep !== null &&
					action.previousStep !== undefined
						? action.previousStep
						: state.currentAiStep,
				currentAiStep: action.payload,
			};
		case 'SET_DRAGGED_IMAGE_FILE':
			return {
				...state,
				draggedImageFile: action.payload,
			};
		case 'SET_IMAGE_GEN_MODEL':
			return {
				...state,
				imageGenModel: action.payload,
			};
		case 'SET_IMAGE_GEN_QUALITY':
			return {
				...state,
				imageGenQuality: action.payload,
			};
		case 'SET_HIDE_IMAGE_UPLOADER':
			return {
				...state,
				hideImageUploader: action.payload,
			};
		case 'SET_BIG_SKY_PENDING_SPEC':
			return {
				...state,
				bigSkyPendingSpec: action.payload,
			};
		case 'SET_MOSAIC_ENABLED':
			return {
				...state,
				mosaicEnabled: action.payload,
			};
		default:
			return state;
	}
}
