/**
 * WordPress dependencies
 */
import { ThumbsDownIcon, ThumbsUpIcon } from '@automattic/agenttic-ui';
import { Button } from '@wordpress/components';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import useFeedback from '@hooks/use-feedback.js';
import { FeedbackInput } from '@components/chat/components/feedback-input.js';

/**
 * MessageFeedback Component
 * Displays thumbs up/down feedback buttons for assistant messages
 *
 * @param {Object} props    - Component props
 * @param {string} props.id - The message ID to associate feedback with
 * @return {JSX.Element} The message feedback component
 */
export default function MessageFeedback( { id } ) {
	const {
		selectedFeedback,
		showFeedbackInput,
		handleFeedback,
		handleSubmitFeedback,
		handleCancelFeedback,
		isInternalTester,
	} = useFeedback( id );

	return (
		<>
			<div className="big-sky__completed-plan">
				<Button
					label={ __( 'Good response', 'big-sky' ) }
					icon={ ThumbsUpIcon }
					onClick={ () => handleFeedback( 'up' ) }
					disabled={ selectedFeedback === 'down' }
					isPressed={ selectedFeedback === 'up' }
					size="compact"
				/>
				<Button
					label={ __( 'Bad response', 'big-sky' ) }
					icon={ ThumbsDownIcon }
					onClick={ () => handleFeedback( 'down' ) }
					disabled={ selectedFeedback === 'up' }
					isPressed={ selectedFeedback === 'down' }
					size="compact"
				/>
			</div>
			{ showFeedbackInput && isInternalTester && (
				<FeedbackInput
					onSubmit={ handleSubmitFeedback }
					onCancel={ handleCancelFeedback }
				/>
			) }
		</>
	);
}
