/**
 * Extracts and sanitizes text content from HTML strings.
 *
 * This utility function removes HTML tags, control characters, and normalizes
 * whitespace to produce clean text suitable for use in alt text, descriptions,
 * and other text-only contexts.
 *
 * @param {string} html - The HTML string to extract text from.
 * @return {string} The sanitized text content.
 */
export function textFromHtml( html ) {
	if ( ! html || typeof html !== 'string' ) {
		return '';
	}

	const parser = new window.DOMParser();
	const doc = parser.parseFromString( html, 'text/html' );
	let sanitized = doc.body.textContent || '';

	// Normalize whitespace
	sanitized = sanitized.replace( /\s+/g, ' ' );

	// Remove all control characters
	sanitized = sanitized.replace( /[\p{C}]/gu, '' );

	// Clean up any remaining multiple spaces
	sanitized = sanitized.replace( / +/g, ' ' );

	// Trim leading and trailing whitespace
	sanitized = sanitized.trim();

	return sanitized;
}
