/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { store as editorStore } from '@wordpress/editor';
import { doAction } from '@wordpress/hooks';
import { parse, serialize } from '@wordpress/blocks';

/**
 * Internal dependencies
 */
import useBlocks from '@hooks/use-blocks';
import usePages from '@hooks/use-pages';
import useTemplateParts from '@hooks/use-template-parts';
import useSiteMetadata from '@hooks/use-site-metadata';
import useStyles from '@hooks/use-styles';
import useVariations from '@hooks/use-variations';
import { store as aiStore } from '@store';
import { checkpointKeys } from '@utils/constants';
import { TemplatePartSlug } from '@utils/template-parts';
import { recordTracksEvent } from '@utils/tracks';

const APPLY_BLOCK_EDITS_TOOL_ID = 'big_sky__apply_block_edits';
const STREAM_PAGE_DESIGN_TOOL_ID = 'big_sky__stream_page_design';
const UPDATE_THEME_TOOL_ID = 'big_sky__apply_update_theme';
const EDIT_ENTITY_RECORD_TOOL_ID = 'big_sky__edit_entity_record';
const RESTORE_CHECKPOINT_TOOL_ID = 'big_sky__restore_checkpoint';
const BLOCK_SECTION_KEYS = [
	'headerBlocks',
	'headerHeroBlocks',
	'footerBlocks',
	'contentBlocks',
];

const removeBlockProcessingState = ( blocks ) => {
	if ( ! Array.isArray( blocks ) ) {
		return;
	}

	blocks.forEach( ( block ) => {
		removeBlockProcessingState( block?.innerBlocks );
		if ( block?.attributes?.className ) {
			block.attributes.className = block.attributes.className
				.split( ' ' )
				.filter(
					( className ) =>
						! className.startsWith( 'big-sky__is-processing' ) &&
						! className.startsWith( 'big-sky__has-processed' )
				)
				.join( ' ' );
		}
	} );
};

const cloneCheckpointBlocks = ( blocksState ) => {
	if ( blocksState === undefined || blocksState === null ) {
		return null;
	}

	const blocks = JSON.parse( JSON.stringify( blocksState ) );
	removeBlockProcessingState( blocks.headerBlocks );
	removeBlockProcessingState( blocks.headerHeroBlocks );
	removeBlockProcessingState( blocks.footerBlocks );
	removeBlockProcessingState( blocks.contentBlocks );
	return blocks;
};

const getCheckpointBlocksSignature = ( blocksState ) => {
	const blocks = cloneCheckpointBlocks( blocksState );
	if ( ! blocks ) {
		return null;
	}

	try {
		const serializedSections = BLOCK_SECTION_KEYS.map( ( key ) =>
			serialize( Array.isArray( blocks[ key ] ) ? blocks[ key ] : [] )
		);
		if (
			serializedSections.some(
				( section ) => typeof section !== 'string'
			)
		) {
			return null;
		}

		return JSON.stringify( serializedSections );
	} catch {
		return null;
	}
};

const getNavigationContent = ( navigationRecord ) => {
	return typeof navigationRecord.content === 'string'
		? navigationRecord.content
		: navigationRecord.content?.raw ||
				navigationRecord.content?.rendered ||
				'';
};

const getCheckpointKeySet = ( checkpoint ) =>
	new Set(
		Array.isArray( checkpoint?.checkpointKeys )
			? checkpoint.checkpointKeys
			: []
	);

const hasExplicitCheckpointKeys = ( checkpoint ) =>
	getCheckpointKeySet( checkpoint ).size > 0;

const isLegacyOrRedoCheckpoint = ( checkpoint ) =>
	! checkpoint?.toolId || checkpoint.toolId === RESTORE_CHECKPOINT_TOOL_ID;

const shouldRestoreBlocks = ( checkpoint ) => {
	const keys = getCheckpointKeySet( checkpoint );
	if ( keys.size > 0 ) {
		return keys.has( checkpointKeys.BLOCKS );
	}

	return (
		isLegacyOrRedoCheckpoint( checkpoint ) ||
		checkpoint.toolId === APPLY_BLOCK_EDITS_TOOL_ID ||
		checkpoint.toolId === STREAM_PAGE_DESIGN_TOOL_ID
	);
};

const shouldRestoreTheme = ( checkpoint ) => {
	const keys = getCheckpointKeySet( checkpoint );
	if ( keys.size > 0 ) {
		return (
			keys.has( checkpointKeys.COLOR ) ||
			keys.has( checkpointKeys.FONT ) ||
			keys.has( checkpointKeys.BUTTON )
		);
	}

	return (
		isLegacyOrRedoCheckpoint( checkpoint ) ||
		checkpoint.toolId === UPDATE_THEME_TOOL_ID
	);
};

const shouldRestoreCustomCSS = ( checkpoint ) =>
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.CUSTOM_CSS );

const shouldRestoreThemePart = ( checkpoint, key ) => {
	const keys = getCheckpointKeySet( checkpoint );
	if ( keys.size > 0 ) {
		return keys.has( key );
	}

	return shouldRestoreTheme( checkpoint );
};

const shouldRestoreSiteMetadata = ( checkpoint ) => {
	const keys = getCheckpointKeySet( checkpoint );
	if ( keys.size > 0 ) {
		return (
			keys.has( checkpointKeys.LOCATION ) ||
			keys.has( checkpointKeys.SITE_METADATA ) ||
			keys.has( checkpointKeys.SITE_TITLE )
		);
	}

	return (
		isLegacyOrRedoCheckpoint( checkpoint ) ||
		checkpoint.toolId === EDIT_ENTITY_RECORD_TOOL_ID
	);
};

const shouldRestoreSiteTitle = ( checkpoint ) =>
	! hasExplicitCheckpointKeys( checkpoint ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.LOCATION ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.SITE_METADATA ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.SITE_TITLE );

const shouldRestoreSiteLogo = ( checkpoint ) =>
	! hasExplicitCheckpointKeys( checkpoint ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.LOGO );

const shouldRestoreNavigationRecords = ( checkpoint ) =>
	! hasExplicitCheckpointKeys( checkpoint ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.BLOCKS ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.PAGE ) ||
	getCheckpointKeySet( checkpoint ).has( checkpointKeys.NAVIGATION );

const hasThemeBeforeUpdateTypographySnapshot = ( checkpoint ) =>
	!! checkpoint?.themeBeforeUpdate?.settings?.typography;

const countBlocks = ( blocks ) => {
	if ( ! Array.isArray( blocks ) ) {
		return 0;
	}

	return blocks.reduce(
		( count, block ) => count + 1 + countBlocks( block?.innerBlocks ),
		0
	);
};

const getSerializedLength = ( blocks ) => {
	if ( ! Array.isArray( blocks ) ) {
		return 0;
	}

	try {
		return serialize( blocks ).length;
	} catch {
		return JSON.stringify( blocks ).length;
	}
};

const getBlocksSummary = ( blocksState ) => {
	if ( ! blocksState || typeof blocksState !== 'object' ) {
		return;
	}

	return BLOCK_SECTION_KEYS.reduce( ( summary, key ) => {
		const blocks = blocksState[ key ];
		summary[ key ] = {
			count: countBlocks( blocks ),
			serializedLength: getSerializedLength( blocks ),
		};
		return summary;
	}, {} );
};

const getTotalBlocksSummary = ( summary ) => {
	if ( ! summary ) {
		return { count: 0, serializedLength: 0 };
	}

	return Object.values( summary ).reduce(
		( total, section ) => ( {
			count: total.count + ( section?.count || 0 ),
			serializedLength:
				total.serializedLength + ( section?.serializedLength || 0 ),
		} ),
		{ count: 0, serializedLength: 0 }
	);
};

const hasEditorScope = ( scope ) =>
	!! scope && Object.values( scope ).some( ( value ) => value !== undefined );

const isSameEditorScope = ( checkpointScope, currentScope ) => {
	if ( ! hasEditorScope( checkpointScope ) ) {
		return true;
	}

	return (
		checkpointScope.postId === currentScope.postId &&
		checkpointScope.postType === currentScope.postType
	);
};

const recordBlockedCheckpointRestore = ( {
	reason,
	checkpoint,
	currentEditorScope,
	currentSummary,
	restoreSummary,
} ) => {
	try {
		const currentTotal = getTotalBlocksSummary( currentSummary );
		const restoreTotal = getTotalBlocksSummary( restoreSummary );

		recordTracksEvent( 'checkpoint_restore_blocked', {
			reason,
			checkpoint_id: checkpoint?.id || checkpoint?.toolCallId || '',
			checkpoint_tool_id: checkpoint?.toolId || '',
			current_post_id: currentEditorScope?.postId || '',
			current_post_type: currentEditorScope?.postType || '',
			checkpoint_post_id: checkpoint?.editorScope?.postId || '',
			checkpoint_post_type: checkpoint?.editorScope?.postType || '',
			current_block_count: currentTotal.count,
			restore_block_count: restoreTotal.count,
			current_serialized_length: currentTotal.serializedLength,
			restore_serialized_length: restoreTotal.serializedLength,
		} );
	} catch {
		// Never let analytics failures affect checkpoint restore behavior.
	}
};

const validateBlockRestoreSafety = (
	checkpoint,
	currentBlocksState,
	currentEditorScope
) => {
	if ( ! checkpoint.blocks ) {
		return;
	}

	const currentSummary = getBlocksSummary( currentBlocksState );
	const restoreSummary =
		checkpoint.blockSummary || getBlocksSummary( checkpoint.blocks );
	const currentTotal = getTotalBlocksSummary( currentSummary );
	const restoreTotal = getTotalBlocksSummary( restoreSummary );
	const wouldCollapseBlocks =
		currentTotal.count >= 5 && restoreTotal.count <= 2;
	const wouldDropMostSerializedContent =
		currentTotal.serializedLength >= 1000 &&
		restoreTotal.serializedLength < currentTotal.serializedLength * 0.2;
	const wouldCollapseSection = Object.keys( currentSummary || {} ).some(
		( key ) => {
			const currentSection = currentSummary?.[ key ];
			const restoreSection = restoreSummary?.[ key ];

			return (
				( currentSection?.count >= 3 &&
					( restoreSection?.count || 0 ) === 0 ) ||
				( currentSection?.serializedLength >= 500 &&
					( restoreSection?.serializedLength || 0 ) <
						currentSection.serializedLength * 0.2 )
			);
		}
	);

	if (
		wouldCollapseBlocks ||
		wouldDropMostSerializedContent ||
		wouldCollapseSection
	) {
		recordBlockedCheckpointRestore( {
			reason: 'content_shrink',
			checkpoint,
			currentEditorScope,
			currentSummary,
			restoreSummary,
		} );
		throw new Error(
			'Checkpoint restore was blocked because it would replace the current editor content with a much smaller block snapshot.'
		);
	}
};

export default function useCheckpoint() {
	const {
		getLastEditorState,
		getEditedEntityRecord,
		getMessages,
		getCheckpoint,
		currentPostId,
		currentPostType,
	} = useSelect( ( select ) => {
		const ai = select( aiStore );
		const core = select( coreStore );
		const editor = select( editorStore );

		return {
			getLastEditorState: ai.getLastEditorState,
			getEditedEntityRecord: core.getEditedEntityRecord,
			getMessages: ai.getMessages,
			getCheckpoint: ai.getCheckpoint,
			currentPostId: editor.getCurrentPostId?.(),
			currentPostType: editor.getCurrentPostType?.(),
		};
	} );
	const { getCurrentTheme, setStyles } = useStyles();
	const {
		modifyGeneratedVariation,
		addCheckpoint,
		removeCheckpoint,
		updateCheckpoint,
	} = useDispatch( aiStore );
	const { replaceInnerBlocks } = useDispatch( blockEditorStore );
	const { editEntityRecord, saveEntityRecord } = useDispatch( coreStore );
	const { undo } = useDispatch( editorStore );
	const { getRootBlocksState, getSectionRootClientId } = useBlocks();

	const { getCurrentColor, getCurrentFont, getCurrentButtonStyle } =
		useSelect( aiStore );
	const {
		getSiteMetadata: getSiteMetadataFromHook,
		setCurrentFont,
		setSiteLocation,
		setSiteMetadata,
	} = useSiteMetadata();
	const siteMetadata = getSiteMetadataFromHook();
	const {
		currentColor: currentColorMeta,
		currentFont: currentFontMeta,
		currentButtonStyle: currentButtonMeta,
		siteLocation,
		siteTitle,
	} = siteMetadata;
	const { replaceTemplatePart } = useTemplateParts();
	const { deletePage, renamePage, goBackPage } = usePages();
	const { getColorVariationByTitle } = useVariations();

	// Get global styles ID for theme restoration
	const { globalStylesId } = useSelect( ( select ) => {
		const core = select( coreStore );
		return {
			globalStylesId: core.__experimentalGetCurrentGlobalStylesId(),
		};
	}, [] );

	// Helper function to get the latest user message ID
	const getLatestUserMessageId = useCallback( () => {
		const messages = getMessages();
		const userMessages = messages.filter(
			( message ) => message.role === 'user'
		);
		const latestUserMessage = userMessages[ userMessages.length - 1 ];
		return latestUserMessage?.id;
	}, [ getMessages ] );

	const setCheckpoint = useCallback(
		( id, keys = [], metadata = {} ) => {
			if ( ! id ) {
				return;
			}

			const entityRecord = getEditedEntityRecord(
				'root',
				'site',
				undefined
			);

			// copy the current color theme
			const currentColor = getCurrentColor() || currentColorMeta;
			const currentTheme = JSON.parse(
				JSON.stringify(
					getColorVariationByTitle( currentColor ) ||
						getCurrentTheme()
				)
			);

			const currentBlocks = cloneCheckpointBlocks( getRootBlocksState() );

			// Get current global styles entity record for theme restoration
			const currentGlobalStyles = getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			const globalStylesBeforeUpdate = currentGlobalStyles
				? JSON.parse( JSON.stringify( currentGlobalStyles ) )
				: null;

			const editorScope = {
				postId: currentPostId,
				postType: currentPostType,
			};
			const blockSummary = getBlocksSummary( currentBlocks );
			const editorState = {
				...metadata,
				blocks: currentBlocks,
				...( hasEditorScope( editorScope ) && { editorScope } ),
				...( blockSummary && { blockSummary } ),
				color: {
					name: currentColor,
					theme: currentTheme,
				},
				font: getCurrentFont() || currentFontMeta,
				button: getCurrentButtonStyle() || currentButtonMeta,
				siteLocation,
				siteTitle: entityRecord?.title ?? siteTitle,
				siteMetadata: siteMetadata
					? JSON.parse( JSON.stringify( siteMetadata ) )
					: undefined,
				siteLogo: entityRecord?.site_logo,
				checkpointKeys: keys,
				...( globalStylesBeforeUpdate && {
					themeBeforeUpdate: {
						settings: globalStylesBeforeUpdate.settings || {},
						styles: globalStylesBeforeUpdate.styles || {},
					},
				} ),
			};

			addCheckpoint( id, editorState );
		},
		[
			getEditedEntityRecord,
			getCurrentColor,
			currentColorMeta,
			getColorVariationByTitle,
			getCurrentTheme,
			addCheckpoint,
			getRootBlocksState,
			getCurrentFont,
			currentFontMeta,
			getCurrentButtonStyle,
			currentButtonMeta,
			siteLocation,
			siteTitle,
			siteMetadata,
			globalStylesId,
			currentPostId,
			currentPostType,
		]
	);

	const addCheckpointKeys = useCallback(
		( id, keys ) => {
			if ( ! id ) {
				return;
			}
			if ( ! keys ) keys = [];

			const existingCheckpoint = getCheckpoint( id );
			if ( existingCheckpoint ) {
				// Update the existing checkpoint with the new keys
				const updatedEditorState = {
					...existingCheckpoint,
					checkpointKeys: [
						...new Set( [
							...( existingCheckpoint?.checkpointKeys || [] ),
							...keys,
						] ),
					],
				};

				updateCheckpoint( id, updatedEditorState );
			}
		},
		[ getCheckpoint, updateCheckpoint ]
	);

	const removeCheckpointKeys = useCallback(
		( id, keys = [] ) => {
			if ( ! id || keys.length === 0 ) {
				return;
			}

			const existingCheckpoint = getCheckpoint( id );
			if ( ! existingCheckpoint ) {
				return;
			}

			const keysToRemove = new Set( keys );
			const remainingKeys = (
				existingCheckpoint.checkpointKeys || []
			).filter( ( key ) => ! keysToRemove.has( key ) );

			if ( remainingKeys.length === 0 ) {
				removeCheckpoint( id );
				return;
			}

			updateCheckpoint( id, {
				...existingCheckpoint,
				checkpointKeys: remainingKeys,
			} );
		},
		[ getCheckpoint, removeCheckpoint, updateCheckpoint ]
	);

	const addNewPageToCheckpoint = useCallback(
		( pageId ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					newPageId: pageId,
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const addPageRenameToCheckpoint = useCallback(
		( pageId, oldTitle, newTitle ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					pageRename: {
						pageId,
						oldTitle,
						newTitle,
					},
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const addPageRemovalToCheckpoint = useCallback(
		( pageId, pageTitle, { shouldRestoreNavigation = false } = {} ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					pageRemoval: {
						pageId,
						pageTitle,
						shouldRestoreNavigation,
					},
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const addNavigationToCheckpoint = useCallback(
		( id, navigationId ) => {
			if ( ! id || ! navigationId ) {
				return;
			}

			const checkpoint = getCheckpoint( id );
			if ( ! checkpoint?.id ) {
				return;
			}

			const navigationRecord = getEditedEntityRecord(
				'postType',
				'wp_navigation',
				navigationId
			);
			if ( ! navigationRecord ) {
				return;
			}

			const navigationBlocks = Array.isArray( navigationRecord.blocks )
				? navigationRecord.blocks
				: parse( getNavigationContent( navigationRecord ) );
			const navigationSnapshot = {
				id: navigationId,
				blocks: navigationBlocks,
				content: serialize( navigationBlocks ),
				title: navigationRecord.title,
			};

			const updatedCheckpoint = {
				...checkpoint,
				navigationRecords: {
					...( checkpoint.navigationRecords || {} ),
					[ navigationId ]: JSON.parse(
						JSON.stringify( navigationSnapshot )
					),
				},
			};
			updateCheckpoint( id, updatedCheckpoint );
		},
		[ getCheckpoint, getEditedEntityRecord, updateCheckpoint ]
	);

	const getCurrentBlocksSignature = useCallback( () => {
		return getCheckpointBlocksSignature( getRootBlocksState() );
	}, [ getRootBlocksState ] );

	const sealCheckpointForSwap = useCallback(
		( id ) => {
			const checkpoint = getCheckpoint( id );
			const keys = getCheckpointKeySet( checkpoint );
			if (
				! checkpoint ||
				checkpoint.toolId !== APPLY_BLOCK_EDITS_TOOL_ID ||
				checkpoint.changeType !== 'text-content' ||
				keys.size !== 1 ||
				! keys.has( checkpointKeys.BLOCKS )
			) {
				return false;
			}

			const expectedBlocks = getCurrentBlocksSignature();
			if ( ! expectedBlocks ) {
				return false;
			}

			updateCheckpoint( id, {
				...checkpoint,
				inlineSwapAction: 'undo',
				inlineSwapExpectedBlocks: expectedBlocks,
			} );
			return true;
		},
		[ getCheckpoint, getCurrentBlocksSignature, updateCheckpoint ]
	);

	const canSwapCheckpoint = useCallback(
		( id ) => {
			const checkpoint = getCheckpoint( id );
			if ( ! checkpoint ) {
				return undefined;
			}
			const keys = getCheckpointKeySet( checkpoint );
			if (
				! [ 'undo', 'redo' ].includes( checkpoint.inlineSwapAction ) ||
				checkpoint.changeType !== 'text-content' ||
				keys.size !== 1 ||
				! keys.has( checkpointKeys.BLOCKS )
			) {
				return undefined;
			}

			const currentEditorScope = {
				postId: currentPostId,
				postType: currentPostType,
			};
			return (
				isSameEditorScope(
					checkpoint.editorScope,
					currentEditorScope
				) &&
				checkpoint.inlineSwapExpectedBlocks ===
					getCurrentBlocksSignature()
			);
		},
		[
			currentPostId,
			currentPostType,
			getCheckpoint,
			getCurrentBlocksSignature,
		]
	);

	const restoreCheckpoint = useCallback(
		async ( id ) => {
			const checkpoint = getCheckpoint( id );

			if ( checkpoint ) {
				// Handle page operations restoration before block-snapshot guards,
				// since page undo can intentionally occur from a different editor target.
				// Handle page deletion if a new page was created
				if ( checkpoint.newPageId ) {
					deletePage( checkpoint.newPageId );
					goBackPage();
					return;
				}

				// Handle page removal restoration
				if ( checkpoint.pageRemoval ) {
					const { pageId, shouldRestoreNavigation } =
						checkpoint.pageRemoval;

					// Reinstate the Page from Trash.
					saveEntityRecord( 'postType', 'page', {
						id: pageId,
						status: 'publish',
					} );

					// Revert the change to the Navigation Menu.
					if ( shouldRestoreNavigation ) {
						undo();
					}
					return;
				}

				const restoreBlocks = shouldRestoreBlocks( checkpoint );
				const restoreTheme = shouldRestoreTheme( checkpoint );
				const restoreCustomCSS = shouldRestoreCustomCSS( checkpoint );
				const restoreSiteMetadata =
					shouldRestoreSiteMetadata( checkpoint );
				const restoreSiteTitle = shouldRestoreSiteTitle( checkpoint );
				const restoreSiteLogo = shouldRestoreSiteLogo( checkpoint );
				const restoreNavigationRecords =
					shouldRestoreNavigationRecords( checkpoint );
				const currentEditorScope = {
					postId: currentPostId,
					postType: currentPostType,
				};

				if (
					restoreCustomCSS &&
					( ! checkpoint.themeBeforeUpdate ||
						! globalStylesId ||
						! getEditedEntityRecord(
							'root',
							'globalStyles',
							globalStylesId
						)?.styles )
				) {
					throw new Error(
						'Checkpoint restore was blocked because current global styles are unavailable.'
					);
				}

				if ( restoreBlocks ) {
					const currentBlocksState = getRootBlocksState();
					if (
						checkpoint.inlineSwapExpectedBlocks &&
						checkpoint.inlineSwapExpectedBlocks !==
							getCurrentBlocksSignature()
					) {
						throw new Error(
							'Checkpoint restore was blocked because the editor content changed after the checkpoint was created.'
						);
					}

					if (
						checkpoint.blocks &&
						! isSameEditorScope(
							checkpoint.editorScope,
							currentEditorScope
						)
					) {
						recordBlockedCheckpointRestore( {
							reason: 'editor_scope_mismatch',
							checkpoint,
							currentEditorScope,
							currentSummary:
								getBlocksSummary( currentBlocksState ),
							restoreSummary:
								checkpoint.blockSummary ||
								getBlocksSummary( checkpoint.blocks ),
						} );
						throw new Error(
							'Checkpoint restore was blocked because it was captured for a different editor target.'
						);
					}

					validateBlockRestoreSafety(
						checkpoint,
						currentBlocksState,
						currentEditorScope
					);
				}

				// Restore only the parts of the checkpoint that match the original tool/change.

				// Restore theme state FIRST if it was stored before theme update
				// This ensures setStyles works with the complete global styles structure
				let restoredThemeBeforeUpdate = false;
				if (
					restoreTheme &&
					checkpoint.themeBeforeUpdate &&
					globalStylesId
				) {
					// Handle both old format (direct color.palette) and new format (settings.color.palette)
					let settingsToRestore = {};
					let stylesToRestore = {};

					if ( checkpoint.themeBeforeUpdate.settings ) {
						// New format: has settings and styles
						settingsToRestore =
							checkpoint.themeBeforeUpdate.settings;
						stylesToRestore =
							checkpoint.themeBeforeUpdate.styles || {};
					} else if ( checkpoint.themeBeforeUpdate.color ) {
						// Old format: direct color.palette structure
						// Convert to new format
						settingsToRestore = {
							color: {
								palette:
									checkpoint.themeBeforeUpdate.color
										.palette || {},
							},
						};
						stylesToRestore =
							checkpoint.themeBeforeUpdate.styles || {};
					}

					editEntityRecord(
						'root',
						'globalStyles',
						globalStylesId,
						{
							settings: settingsToRestore,
							styles: stylesToRestore,
						},
						{ undoIgnore: true }
					);
					restoredThemeBeforeUpdate = true;
				}

				if ( restoreCustomCSS ) {
					const currentGlobalStyles = getEditedEntityRecord(
						'root',
						'globalStyles',
						globalStylesId
					);
					if ( ! currentGlobalStyles?.styles ) {
						throw new Error(
							'Checkpoint restore was blocked because current global styles are unavailable.'
						);
					}

					const restoredStyles = { ...currentGlobalStyles.styles };
					const previousStyles =
						checkpoint.themeBeforeUpdate.styles || {};
					if (
						Object.prototype.hasOwnProperty.call(
							previousStyles,
							'css'
						)
					) {
						restoredStyles.css = previousStyles.css;
					} else {
						delete restoredStyles.css;
					}

					editEntityRecord(
						'root',
						'globalStyles',
						globalStylesId,
						{
							...currentGlobalStyles,
							styles: restoredStyles,
						},
						{ undoIgnore: true }
					);
				}

				const stylesToRestore = {};
				let skippedFontStyleRestore = false;
				if (
					shouldRestoreThemePart(
						checkpoint,
						checkpointKeys.COLOR
					) &&
					checkpoint.color
				) {
					modifyGeneratedVariation(
						checkpoint.color.name,
						checkpoint.color.theme
					);
					stylesToRestore.color = checkpoint.color.name;
				}
				if (
					shouldRestoreThemePart( checkpoint, checkpointKeys.FONT ) &&
					checkpoint.font
				) {
					if (
						restoredThemeBeforeUpdate &&
						hasThemeBeforeUpdateTypographySnapshot( checkpoint )
					) {
						skippedFontStyleRestore = true;
					} else {
						stylesToRestore.font = checkpoint.font;
					}
				}
				if (
					shouldRestoreThemePart(
						checkpoint,
						checkpointKeys.BUTTON
					) &&
					checkpoint.button
				) {
					stylesToRestore.button = checkpoint.button;
				}
				if ( Object.keys( stylesToRestore ).length > 0 ) {
					setStyles( stylesToRestore );
				}
				if ( skippedFontStyleRestore ) {
					setCurrentFont( checkpoint.font );
				}

				// reset blocks
				if ( restoreBlocks && checkpoint.blocks ) {
					// reset the template parts
					await replaceTemplatePart(
						TemplatePartSlug.Header,
						checkpoint?.blocks?.headerBlocks
					);
					// await here since the client ids of the header hero blocks change
					await replaceTemplatePart(
						TemplatePartSlug.HeaderHero,
						checkpoint?.blocks?.headerHeroBlocks
					);
					await replaceTemplatePart(
						TemplatePartSlug.Footer,
						checkpoint?.blocks?.footerBlocks
					);

					// reset the content
					await replaceInnerBlocks(
						getSectionRootClientId(),
						checkpoint?.blocks?.contentBlocks
					);
				}

				// reset the site metadata
				if ( restoreSiteMetadata && checkpoint.siteMetadata ) {
					setSiteMetadata( checkpoint.siteMetadata );
				}

				// reset the site location
				// TODO: Remove setSiteLocation usage once checkpoint restoration is migrated
				if ( restoreSiteMetadata && checkpoint.siteLocation ) {
					setSiteLocation( checkpoint.siteLocation );
				}

				// reset the site title
				if ( restoreSiteTitle && checkpoint.siteTitle !== undefined ) {
					editEntityRecord( 'root', 'site', undefined, {
						title: checkpoint.siteTitle,
					} );
				}

				// reset the site logo
				if ( restoreSiteLogo && checkpoint.siteLogo ) {
					editEntityRecord( 'root', 'site', undefined, {
						site_logo: checkpoint.siteLogo,
					} );
				}

				// Restore direct navigation entity edits.
				if (
					restoreNavigationRecords &&
					checkpoint.navigationRecords
				) {
					await Promise.all(
						Object.entries( checkpoint.navigationRecords ).map(
							async ( [ navigationId, navigationRecord ] ) => {
								const blocks = Array.isArray(
									navigationRecord.blocks
								)
									? navigationRecord.blocks
									: parse(
											getNavigationContent(
												navigationRecord
											)
									  );
								const recordToRestore = {
									blocks,
									content: serialize( blocks ),
									...( navigationRecord.title
										? { title: navigationRecord.title }
										: {} ),
								};

								return editEntityRecord(
									'postType',
									'wp_navigation',
									navigationId,
									recordToRestore,
									{ undoIgnore: true }
								);
							}
						)
					);
				}

				// Handle page and navigation rename restoration
				if ( checkpoint.pageRename ) {
					const { pageId, oldTitle, newTitle } =
						checkpoint.pageRename;
					await renamePage( pageId, oldTitle, newTitle );
				}

				// Fire the checkpoint restored action after all restoration is complete
				try {
					doAction( 'big-sky.checkpoint-restored', {
						checkpointId: id,
						checkpoint,
					} );
				} catch ( error ) {
					// eslint-disable-next-line no-console
					console.error(
						'[Big Sky] Checkpoint restored hook failed:',
						error
					);
				}
			}
		},
		[
			getCheckpoint,
			getEditedEntityRecord,
			setStyles,
			modifyGeneratedVariation,
			replaceTemplatePart,
			replaceInnerBlocks,
			getSectionRootClientId,
			setSiteLocation,
			setSiteMetadata,
			setCurrentFont,
			editEntityRecord,
			deletePage,
			goBackPage,
			renamePage,
			saveEntityRecord,
			undo,
			globalStylesId,
			currentPostId,
			currentPostType,
			getRootBlocksState,
			getCurrentBlocksSignature,
		]
	);

	const swapCheckpoint = useCallback(
		async ( id ) => {
			const checkpoint = getCheckpoint( id );
			if ( ! checkpoint || ! canSwapCheckpoint( id ) ) {
				throw new Error(
					'Checkpoint swap was blocked because the editor content changed or the checkpoint is not a text edit.'
				);
			}

			const action = checkpoint.inlineSwapAction;
			const nextAction = action === 'undo' ? 'redo' : 'undo';
			const currentBlocks = cloneCheckpointBlocks( getRootBlocksState() );
			if ( ! currentBlocks ) {
				throw new Error(
					'Checkpoint swap was blocked because the editor content is unavailable.'
				);
			}
			const reciprocal = {
				...checkpoint,
				blocks: currentBlocks,
				blockSummary: getBlocksSummary( currentBlocks ),
				editorScope: {
					postId: currentPostId,
					postType: currentPostType,
				},
				toolCallId: id,
				toolId:
					nextAction === 'redo'
						? RESTORE_CHECKPOINT_TOOL_ID
						: APPLY_BLOCK_EDITS_TOOL_ID,
				requestIntentType: nextAction,
				createdByRequestIntentType: action,
				inlineSwapAction: nextAction,
			};

			await restoreCheckpoint( id );
			updateCheckpoint( id, {
				...reciprocal,
				inlineSwapExpectedBlocks: getCurrentBlocksSignature(),
			} );
		},
		[
			canSwapCheckpoint,
			currentPostId,
			currentPostType,
			getCheckpoint,
			getCurrentBlocksSignature,
			getRootBlocksState,
			restoreCheckpoint,
			updateCheckpoint,
		]
	);

	const clearCheckpoint = useCallback(
		( userMessageId ) => {
			removeCheckpoint( userMessageId );
		},
		[ removeCheckpoint ]
	);

	const hasCheckpoint = useCallback(
		( id ) => {
			return !! getCheckpoint( id );
		},
		[ getCheckpoint ]
	);

	return {
		getLastEditorState,
		setCheckpoint,
		addCheckpointKeys,
		removeCheckpointKeys,
		restoreCheckpoint,
		sealCheckpointForSwap,
		canSwapCheckpoint,
		swapCheckpoint,
		addNewPageToCheckpoint,
		addPageRenameToCheckpoint,
		addPageRemovalToCheckpoint,
		addNavigationToCheckpoint,
		getLatestUserMessageId,
		clearCheckpoint,
		hasCheckpoint,
	};
}
