/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import log from '@utils/log-debug.js';
import { getAssistantById } from '@ai/assistants';
import useCanvas from '@hooks/use-canvas';
import useLog from '@hooks/use-log';
import { scrollToBlock } from '@utils/block-dom';

/**
 * Types
 */
interface ClientIdMap {
	[ key: string ]: string;
}

interface RunAssistantArgs {
	assistantId: string;
	request: string;
	clientId?: string;
	userConfirmed?: boolean;
	followUpTasks?: boolean;
}

interface ToolParameters {
	additionalProperties?: boolean;
	[ key: string ]: unknown;
}

interface Tool {
	name: string;
	description?: string;
	parameters?: ToolParameters;
	strict?: boolean;
}

interface OpenAITool {
	type: 'function';
	function: Tool;
}

interface ToolCall {
	id: string;
	function: {
		name: string;
		arguments: string;
	};
}

interface ChatMessage {
	role: 'system' | 'user' | 'assistant';
	content: string | Array< { type: string; text: string } >;
}

interface ChatResponse {
	choices?: Array< {
		message?: {
			content?: string;
			tool_calls?: ToolCall[];
		};
	} >;
}

interface AssistantResult {
	result: string | unknown;
	returnToAgent: boolean;
	awaitingUserInput?: boolean;
	unfulfilled?: boolean;
	agentMessage?: string | unknown;
}

interface ToolCallResult {
	awaitingUserInput?: boolean;
	unfulfilled?: boolean;
	[ key: string ]: unknown;
}

interface Assistant {
	instructions: string | ( ( context: any ) => string );
	toolkits?: Array< {
		tools: Tool[] | ( ( context: any ) => Tool[] );
	} >;
}

interface AddedMessage {
	message?: {
		id: string;
	};
}

export default function useRunAssistant() {
	const { zoomIn } = useCanvas();

	const { runChatCompletion, setThinking, addMessage, addMessageToDelete } =
		useDispatch( aiStore ) as {
			runChatCompletion: (
				model: string,
				messages: ChatMessage[],
				tools: OpenAITool[]
			) => Promise< ChatResponse >;
			setThinking: ( thinking: boolean ) => void;
			addMessage: ( message: ChatMessage ) => Promise< AddedMessage >;
			addMessageToDelete: ( message: { id: string } ) => void;
		};
	const { logToolCall } = useLog();

	// Get clientIdMap from store (instead of it being injected via args)
	const clientIdMap = useSelect(
		( select ) =>
			select( aiStore ).getFullPageStructure()?.clientIdMap || {},
		[]
	) as ClientIdMap;

	const { chatModel, getContexts, getCallbacks } = useSelect(
		( select ) => ( {
			chatModel: select( aiStore ).getAdvancedChatModel(),
			getAssistant: select( aiStore ).getAssistant,
			getContexts: select( aiStore ).getContexts,
			getCallbacks: select( aiStore ).getCallbacks,
			getMessagesToDelete: select( aiStore ).getMessagesToDelete,
		} ),
		[]
	) as {
		chatModel: string;
		getContexts: () => Record< string, any >;
		getCallbacks: () => Record<
			string,
			Record< string, ( args: any ) => Promise< any > >
		>;
	};

	const getContext = ( assistantId: string ): any => {
		return getContexts()[ assistantId ];
	};

	const getSystemPrompt = ( assistantId: string ): string => {
		const assistant = getAssistantById( assistantId ) as Assistant;
		return typeof assistant.instructions === 'function'
			? assistant.instructions( getContext( assistantId ) )
			: assistant.instructions;
	};

	const getTools = ( assistantId: string ): OpenAITool[] => {
		const assistant = getAssistantById( assistantId ) as Assistant;
		const toolkit = assistant?.toolkits?.[ 0 ];
		if ( ! toolkit ) {
			throw new Error( 'Toolkit not found' );
		}
		const tools =
			typeof toolkit?.tools === 'function'
				? toolkit.tools( getContext( assistantId ) )
				: toolkit.tools;

		const openaiTools = tools.map( ( tool: Tool ): OpenAITool => {
			if ( tool.parameters && tool.strict !== undefined ) {
				tool.parameters.additionalProperties = ! tool.strict;
			}
			return {
				type: 'function',
				function: tool,
			};
		} );

		return openaiTools;
	};

	const runCallback = useCallback(
		async (
			assistantId: string,
			toolName: string,
			args: any,
			request: string
		): Promise< any > => {
			const callbacks = getCallbacks();

			if (
				callbacks[ assistantId ] &&
				callbacks[ assistantId ][ toolName ]
			) {
				return await callbacks[ assistantId ][ toolName ]( {
					...args,
					__original_request: request,
				} );
			}
			throw new Error( `Callback ${ toolName } not found` );
		},
		[ getCallbacks ]
	);

	const runAssistant = async (
		args: RunAssistantArgs
	): Promise< AssistantResult > => {
		// Use clientIdMap from hook closure
		if ( args?.clientId && clientIdMap[ args.clientId ] ) {
			args.clientId = clientIdMap[ args.clientId ];
		}

		const { assistantId, request, clientId, userConfirmed, followUpTasks } =
			args;

		setThinking( true );
		if ( clientId ) {
			await zoomIn();
			scrollToBlock( clientId, 'start', false, 50 );
		}

		const systemPrompt = getSystemPrompt( assistantId );

		const messages: ChatMessage[] = [
			{
				role: 'system',
				content: systemPrompt,
			},
			{
				role: 'user',
				content: request,
			},
		];
		if ( userConfirmed ) {
			messages.push( {
				role: 'system',
				content: 'User has confirmed',
			} );
		}

		const tools = getTools( assistantId );

		const response = await runChatCompletion( chatModel, messages, tools );

		// Handle tool calls first
		const toolCalls = response?.choices?.[ 0 ]?.message?.tool_calls;
		if ( ! toolCalls || toolCalls.length === 0 ) {
			// Check for a text response
			const messageContent = response?.choices?.[ 0 ]?.message?.content;
			if ( messageContent ) {
				setThinking( false );
				addMessage( {
					role: 'assistant',
					content: [
						{
							type: 'text',
							text: messageContent,
						},
					],
				} );

				return {
					result: messageContent,
					returnToAgent: false,
				};
			}

			// not sure if this will ever happen, but...
			log.error( `No text or tool call response from AI.` );
			return {
				result: __( 'No response from assistant', 'big-sky' ),
				returnToAgent: false,
			};
		}

		// Loop through tool calls and process each one
		for ( const toolCall of toolCalls ) {
			const toolCallArgs = toolCall.function.arguments;

			try {
				const parsedArgs = JSON.parse( toolCallArgs );

				// if the step has a client id, pass it to the tool callback
				if ( clientId ) {
					parsedArgs.clientId = clientId;
				}

				// pass along the followUpTasks
				parsedArgs.followUpTasks = followUpTasks;

				logToolCall( toolCall.function, toolCall.id );

				const result: ToolCallResult | string = await runCallback(
					assistantId,
					toolCall.function.name,
					parsedArgs,
					request
				);

				let returnToAgent = false;
				if ( result ) {
					// result is a string, assume this is a clarifying question from the assistant
					// or failed validation
					if ( typeof result === 'string' ) {
						const assistantMessage = await addMessage( {
							role: 'assistant',
							content: [
								{
									type: 'text',
									text: result,
								},
							],
						} );
						if ( ( result as any ).unfulfilled ) {
							addMessageToDelete( {
								id: assistantMessage?.message?.id ?? '',
							} );
						}
						return {
							result,
							returnToAgent: false,
						};
					}

					if (
						( result as ToolCallResult ).awaitingUserInput ||
						( result as ToolCallResult ).unfulfilled
					) {
						returnToAgent = false;
						// Reset thinking state when awaiting user input
						setThinking( false );
					}
				}

				// return the result
				return {
					result,
					returnToAgent,
					agentMessage: ( result as ToolCallResult ).agentMessage,
				};
			} catch ( e ) {
				log.error(
					`Error running callback for ${ toolCall.function.name }:`,
					e
				);
				// Return error result instead of undefined
				return {
					result: __(
						"Sorry, I've encountered an error. Please try again or let me know if you need help with something else.",
						'big-sky'
					),
					returnToAgent: false,
				};
			}
		}

		// Fallback return in case no tool calls are processed
		return {
			result: __( 'No response from assistant', 'big-sky' ),
			returnToAgent: false,
		};
	};

	return {
		runAssistant,
	};
}
