/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { useSelect } from '@wordpress/data';

/**
 * Internal dependencies
 */
import useCheckpoint from '@hooks/use-checkpoint';
import { store as aiStore } from '@store';
import { getToolCallIdFromConversationHistory } from '@utils/tool-call-history';

interface RestoreCheckpointArgs {
	checkpointId: string;
	summary: string;
	requestIntentType?: 'undo' | 'redo' | 'restore';
	messageId?: string;
}

interface RestoreCheckpointResult {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: Record< string, unknown >;
	};
	returnToAgent: boolean;
}

const RESTORE_CHECKPOINT_TOOL_ID = 'big_sky__restore_checkpoint';
const RESTORE_CHECKPOINT_TYPE_RESTORE = 'restore';

const getReciprocalRestoreIntentType = (
	requestIntentType: RestoreCheckpointArgs[ 'requestIntentType' ]
): RestoreCheckpointArgs[ 'requestIntentType' ] => {
	if ( requestIntentType === 'undo' ) {
		return 'redo';
	}
	if ( requestIntentType === 'redo' ) {
		return 'undo';
	}
	return requestIntentType;
};

interface CheckpointRecord {
	id?: string;
	toolId?: string;
	checkpointKeys?: string[];
	navigationRecords?: Record< string, unknown >;
	pageRename?: {
		pageId: string | number;
		oldTitle: string;
		newTitle: string;
	};
}

const getReciprocalCheckpointKeys = (
	checkpoint: CheckpointRecord
): string[] => {
	return Array.isArray( checkpoint?.checkpointKeys )
		? checkpoint.checkpointKeys
		: [];
};

/**
 * Hook that provides checkpoint restoration functionality for agents.
 */
export default function useRestoreCheckpointTool(): {
	restoreCheckpointById: (
		args: RestoreCheckpointArgs
	) => Promise< RestoreCheckpointResult >;
} {
	const {
		restoreCheckpoint,
		hasCheckpoint,
		setCheckpoint,
		clearCheckpoint,
		addNavigationToCheckpoint,
	} = useCheckpoint();
	const getCheckpoints = useSelect(
		( select ) => select( aiStore ).getCheckpoints,
		[]
	);

	const restoreCheckpointById = async ( {
		checkpointId,
		summary,
		requestIntentType = RESTORE_CHECKPOINT_TYPE_RESTORE,
		messageId,
	}: RestoreCheckpointArgs ): Promise< RestoreCheckpointResult > => {
		if ( ! checkpointId ) {
			return {
				result: {
					success: false,
					message: __(
						'I could not restore the checkpoint because no checkpoint ID was provided.',
						'big-sky'
					),
					error: 'Missing checkpointId.',
				},
				returnToAgent: true,
			};
		}

		if ( ! hasCheckpoint( checkpointId ) ) {
			return {
				result: {
					success: false,
					message: __(
						'I could not find a checkpoint for that ID.',
						'big-sky'
					),
					error: `Checkpoint not found: ${ checkpointId }`,
					details: {
						checkpointId,
					},
				},
				returnToAgent: true,
			};
		}

		const targetCheckpoint = ( getCheckpoints() || [] ).find(
			( checkpoint: CheckpointRecord ) => checkpoint.id === checkpointId
		) as CheckpointRecord | undefined;
		const reciprocalCheckpointKeys = getReciprocalCheckpointKeys(
			targetCheckpoint || {}
		);
		const restoreToolCallId = getToolCallIdFromConversationHistory(
			RESTORE_CHECKPOINT_TOOL_ID,
			messageId
		);
		const reciprocalRequestIntentType =
			getReciprocalRestoreIntentType( requestIntentType );
		if ( restoreToolCallId && ! hasCheckpoint( restoreToolCallId ) ) {
			const reciprocalPageRename = targetCheckpoint?.pageRename
				? {
						pageId: targetCheckpoint.pageRename.pageId,
						oldTitle: targetCheckpoint.pageRename.newTitle,
						newTitle: targetCheckpoint.pageRename.oldTitle,
				  }
				: undefined;
			setCheckpoint( restoreToolCallId, reciprocalCheckpointKeys, {
				toolCallId: restoreToolCallId,
				toolId: RESTORE_CHECKPOINT_TOOL_ID,
				messageId,
				summary,
				restoresCheckpointId: checkpointId,
				restoredCheckpointToolId: targetCheckpoint?.toolId,
				requestIntentType: reciprocalRequestIntentType,
				createdByRequestIntentType: requestIntentType,
				...( reciprocalPageRename && {
					pageRename: reciprocalPageRename,
				} ),
			} );

			Object.keys( targetCheckpoint?.navigationRecords || {} ).forEach(
				( navigationId ) => {
					addNavigationToCheckpoint(
						restoreToolCallId,
						navigationId
					);
				}
			);
		}

		try {
			await restoreCheckpoint( checkpointId );
		} catch ( error ) {
			return {
				result: {
					success: false,
					message: __(
						'I did not restore that checkpoint because it may replace or remove too much current content.',
						'big-sky'
					),
					error:
						error instanceof Error
							? error.message
							: String( error ),
					details: {
						checkpointId,
					},
				},
				returnToAgent: true,
			};
		}

		if ( restoreToolCallId ) {
			const checkpoints = getCheckpoints() || [];
			const previousRestoreCheckpointIds = checkpoints
				.filter(
					( checkpoint: {
						id?: string;
						toolId?: string;
						requestIntentType?: string;
					} ) =>
						checkpoint.id &&
						checkpoint.toolId === RESTORE_CHECKPOINT_TOOL_ID &&
						checkpoint.id !== restoreToolCallId &&
						( checkpoint.requestIntentType ===
							reciprocalRequestIntentType ||
							! checkpoint.requestIntentType )
				)
				.map( ( checkpoint: { id: string } ) => checkpoint.id );

			previousRestoreCheckpointIds.forEach( clearCheckpoint );
		}

		return {
			result: {
				success: true,
				message: summary,
				details: {
					checkpointId,
				},
			},
			returnToAgent: true,
		};
	};

	return {
		restoreCheckpointById,
	};
}
