/**
 * Update Personality Tool
 *
 * This tool updates the site personality to influence future design choices.
 */

export default function updatePersonality( { personalities } ) {
	return {
		name: 'update_personality',
		description:
			'Updates the site personality to influence future design choices for colors, fonts, and overall styling.',
		parameters: {
			type: 'object',
			properties: {
				personality: {
					type: 'string',
					description: 'The personality to set for the site',
					enum: personalities,
				},
				answer: {
					type: 'string',
					description: 'A brief confirmation message to the user',
				},
			},
			required: [ 'personality', 'answer' ],
		},
	};
}
