/**
 * WordPress dependencies
 */
import {
	__unstableEditorStyles as EditorStyles,
	__unstableIframe as Iframe,
} from '@wordpress/block-editor';
import {
	__experimentalHStack as HStack,
	__unstableMotion as motion,
	__experimentalVStack as VStack,
} from '@wordpress/components';
import { useResizeObserver, useThrottle } from '@wordpress/compose';
import { useLayoutEffect, useMemo, useState } from '@wordpress/element';
import { store as coreStore } from '@wordpress/core-data';
import { useSelect } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { getStyleValue as getStyle } from '@utils/global-styles';
import useStyles from '@hooks/use-styles';
import useSiteMetadata from '@hooks/use-site-metadata';
import useVariations from '@hooks/use-variations';
import { fontFamiliesToCSS } from '@utils/font-families-to-css';
import deepmerge from 'deepmerge';

const firstFrame = {
	start: {
		scale: 1,
		opacity: 1,
	},
};

const secondFrame = {
	start: {
		scale: 0,
		opacity: 0,
	},
};

const normalizedWidth = 200;
const normalizedHeight = 80;
const normalizedColorSwatchSize = 32;

// Throttle options for useThrottle. Must be defined outside of the component,
// so that the object reference is the same on each render.
const THROTTLE_OPTIONS = {
	leading: true,
	trailing: true,
};

const StylesPreview = ( { label, type, variation } ) => {
	const {
		globalStyles: currentGlobalStyles,
		fontFamilies: currentFontFamilies,
	} = useSelect( ( select ) => {
		const id = select( coreStore ).__experimentalGetCurrentGlobalStylesId();
		const styles = select( coreStore ).getEditedEntityRecord(
			'root',
			'globalStyles',
			id
		);
		return {
			globalStylesId: id,
			globalStyles: styles,
			fontFamilies: styles?.settings?.typography?.fontFamilies?.theme,
		};
	}, [] );

	// For typography previews: use ONLY the variation to prevent leaking active global styles.
	// For other types: merge variation with currentGlobalStyles to get custom colors.
	let globalStyles;
	if ( variation && type === 'font' ) {
		globalStyles = variation;
	} else if ( variation ) {
		globalStyles = deepmerge( currentGlobalStyles, variation );
	} else {
		globalStyles = currentGlobalStyles;
	}
	const fontFamilies =
		globalStyles?.settings?.typography?.fontFamilies?.theme ||
		currentFontFamilies;

	// Use getStyle to read values from global styles
	// Typography from globalStyles (which includes variation for font previews)
	const fontFamily =
		getStyle( globalStyles, 'typography.fontFamily' ) ?? 'serif';
	const fontWeight = getStyle( globalStyles, 'typography.fontWeight' );
	const fontStyle =
		getStyle( globalStyles, 'typography.fontStyle' ) ?? 'normal';
	const textTransform =
		getStyle( globalStyles, 'typography.textTransform' ) ?? 'none';
	// Colors from currentGlobalStyles to show custom colors
	const textColor = getStyle( currentGlobalStyles, 'color.text' ) ?? 'black';

	const h1FontFamily = getStyle(
		globalStyles,
		'typography.fontFamily',
		'h1'
	);
	const headingFontFamily = getStyle(
		globalStyles,
		'typography.fontFamily',
		'heading'
	);
	const headerFontFamily = h1FontFamily ?? headingFontFamily ?? fontFamily;

	const h1FontWeight = getStyle(
		globalStyles,
		'typography.fontWeight',
		'h1'
	);
	const headingFontWeight = getStyle(
		globalStyles,
		'typography.fontWeight',
		'heading'
	);
	const headerFontWeight = h1FontWeight ?? headingFontWeight ?? fontWeight;

	const h1FontStyle = getStyle( globalStyles, 'typography.fontStyle', 'h1' );
	const headingFontStyle = getStyle(
		globalStyles,
		'typography.fontStyle',
		'heading'
	);
	const headerFontStyle = h1FontStyle ?? headingFontStyle ?? fontStyle;

	const h1TextTransform = getStyle(
		globalStyles,
		'typography.textTransform',
		'h1'
	);
	const headingTextTransform = getStyle(
		globalStyles,
		'typography.textTransform',
		'heading'
	);
	const headerTextTransform =
		h1TextTransform ?? headingTextTransform ?? textTransform;

	const h1Color = getStyle( currentGlobalStyles, 'color.text', 'h1' );
	const headingColor = getStyle(
		currentGlobalStyles,
		'color.text',
		'heading'
	);
	const headerColor = h1Color ?? headingColor ?? textColor;
	const backgroundColor = currentGlobalStyles?.styles?.color?.background;

	// All button styles from globalStyles (variation merged with currentGlobalStyles)
	// This includes padding, border, and background (transparent for outline styles, or custom color)
	const buttonPadding = getStyle( globalStyles, 'spacing.padding', 'button' );
	const buttonBorder = getStyle( globalStyles, 'border', 'button' );
	const buttonBackground = getStyle(
		globalStyles,
		'color.background',
		'button'
	);

	// Convert padding object to CSS-compatible format
	const getPaddingStyles = ( padding ) => {
		if ( ! padding ) return {};

		if ( typeof padding === 'string' ) {
			return { padding };
		}

		if ( typeof padding === 'object' && padding.top !== undefined ) {
			return {
				paddingTop: padding.top,
				paddingRight: padding.right,
				paddingBottom: padding.bottom,
				paddingLeft: padding.left,
			};
		}

		return { padding };
	};

	// Convert border object to CSS-compatible format
	const getBorderStyles = ( border ) => {
		if ( ! border ) return {};

		if ( typeof border === 'string' ) {
			return { border };
		}

		if ( typeof border === 'object' ) {
			const borderStyles = {};

			// Handle border width, style, color
			if ( border.width !== undefined ) {
				borderStyles.borderWidth = border.width;
			}
			if ( border.style !== undefined ) {
				borderStyles.borderStyle = border.style;
			}
			if ( border.color !== undefined ) {
				borderStyles.borderColor = border.color.replace(
					' !important',
					''
				);
			}

			// Handle border radius
			if ( border.radius !== undefined ) {
				borderStyles.borderRadius = border.radius;
			}

			// If we have width but no style, default to solid
			if ( border.width && border.width !== '0' && ! border.style ) {
				borderStyles.borderStyle = 'solid';
			}

			return borderStyles;
		}

		return { border };
	};

	const [ containerResizeListener, { width } ] = useResizeObserver();
	const [ throttledWidth, setThrottledWidthState ] = useState( width );
	const [ ratioState, setRatioState ] = useState();

	const setThrottledWidth = useThrottle(
		setThrottledWidthState,
		250,
		THROTTLE_OPTIONS
	);

	const { currentColor } = useSiteMetadata().getSiteMetadata();
	const { getColorVariationByTitle } = useVariations();
	const colorVariation = getColorVariationByTitle( currentColor );

	/**
	 * Helper function to resolve color values from editor state or fallback to persisted state
	 * Handles both WordPress block format (var:preset|color|slug) and CSS variable format (var(--wp--preset--color--slug))
	 * @param {string} editorColor   - Color value from current editor state
	 * @param {string} fallbackColor - Color value from persisted colorVariation
	 * @param {string} defaultValue  - Default color to exclude from return
	 * @return {string|undefined} Resolved color value
	 */
	const resolveColor = (
		editorColor,
		fallbackColor,
		defaultValue = null
	) => {
		// First check editor state (currentGlobalStyles) for unsaved custom colors
		if ( editorColor ) {
			// Handle WordPress block format: var:preset|color|theme-2
			if ( editorColor.includes( 'var:preset|color|' ) ) {
				const slug = editorColor.split( '|' )[ 2 ];
				const resolvedColor =
					currentGlobalStyles?.settings?.color?.palette?.theme?.find(
						( color ) => color.slug === slug
					)?.color;
				if ( resolvedColor ) {
					return resolvedColor;
				}
			}
			// Handle CSS variable format: var(--wp--preset--color--theme-2)
			else if ( editorColor.includes( 'var(--wp--preset' ) ) {
				const colorNumber = editorColor
					.split( '--' )[ 4 ]
					?.replace( ')', '' );
				const resolvedColor =
					currentGlobalStyles?.settings?.color?.palette?.theme?.find(
						( color ) => color.slug === colorNumber
					)?.color;
				if ( resolvedColor ) {
					return resolvedColor;
				}
			} else if ( ! defaultValue || editorColor !== defaultValue ) {
				// It's a direct hex value (custom color)
				return editorColor;
			}
		}

		// Fall back to colorVariation (persisted state)
		if ( ! fallbackColor ) {
			return undefined;
		}

		// Handle WordPress block format in fallback
		if ( fallbackColor.includes( 'var:preset|color|' ) ) {
			const slug = fallbackColor.split( '|' )[ 2 ];
			return colorVariation?.settings?.color?.palette?.theme?.find(
				( color ) => color.slug === slug
			)?.color;
		}

		// Return raw value if it's not a preset variable
		if ( ! fallbackColor.includes( 'var(--wp--preset' ) ) {
			return fallbackColor;
		}

		// Resolve CSS variable from colorVariation palette
		const colorNumber = fallbackColor
			.split( '--' )[ 4 ]
			?.replace( ')', '' );
		return colorVariation?.settings?.color?.palette?.theme?.find(
			( color ) => color.slug === colorNumber
		)?.color;
	};

	const activeBackgroundColor = () => {
		return resolveColor(
			backgroundColor,
			colorVariation?.styles?.color?.background,
			'white'
		);
	};

	const activeTextColor = () => {
		return resolveColor(
			textColor,
			colorVariation?.styles?.color?.text,
			'black'
		);
	};

	const getVariationBackgroundColor = () => {
		// If a variation is provided (color preview), use its background
		// Otherwise use the current background (font/button previews)
		if ( variation ) {
			const varBg = variation.styles?.color?.background;
			// Resolve the variation's background color
			if ( varBg ) {
				// Handle WordPress block format: var:preset|color|theme-2
				if ( varBg.includes( 'var:preset|color|' ) ) {
					const slug = varBg.split( '|' )[ 2 ];
					const resolvedColor =
						variation.settings?.color?.palette?.theme?.find(
							( color ) => color.slug === slug
						)?.color;
					return resolvedColor || varBg || '#ffffff';
				}
				// Handle CSS variable format: var(--wp--preset--color--theme-2)
				else if ( varBg.includes( 'var(--wp--preset--color' ) ) {
					const colorSlug = varBg
						.split( '--' )[ 4 ]
						?.replace( ')', '' );
					const resolvedColor =
						variation.settings?.color?.palette?.theme?.find(
							( color ) => color.slug === colorSlug
						)?.color;
					return resolvedColor || varBg || '#ffffff';
				}
				// Direct color value
				return varBg;
			}
		}

		// No variation provided, use current background
		return activeBackgroundColor() || '#ffffff';
	};

	const getPreviewButtonBackgroundColor = () => {
		// Resolve CSS variables to actual colors
		// buttonBackground comes from globalStyles (merged variation + currentGlobalStyles)
		return resolveColor(
			buttonBackground,
			colorVariation?.styles?.elements?.button?.color?.background,
			'#1E1E1E'
		);
	};

	const buttonStyles = {
		...getPaddingStyles( buttonPadding ),
		...getBorderStyles( buttonBorder ),
		background: getPreviewButtonBackgroundColor(),
	};

	// Must use useLayoutEffect to avoid a flash of the iframe at the wrong
	// size before the width is set.
	useLayoutEffect( () => {
		if ( width ) {
			setThrottledWidth( width );
		}
	}, [ width, setThrottledWidth ] );

	// Must use useLayoutEffect to avoid a flash of the iframe at the wrong
	// size before the width is set.
	useLayoutEffect( () => {
		const newRatio = throttledWidth ? throttledWidth / normalizedWidth : 1;
		const ratioDiff = newRatio - ( ratioState || 0 );

		// Only update the ratio state if the difference is big enough
		// or if the ratio state is not yet set. This is to avoid an
		// endless loop of updates at particular viewport heights when the
		// presence of a scrollbar causes the width to change slightly.
		const isRatioDiffBigEnough = Math.abs( ratioDiff ) > 0.1;

		if ( isRatioDiffBigEnough || ! ratioState ) {
			setRatioState( newRatio );
		}
	}, [ throttledWidth, ratioState ] );

	// Set a fallbackRatio to use before the throttled ratio has been set.
	const fallbackRatio = width ? width / normalizedWidth : 1;
	// Use the throttled ratio if it has been calculated, otherwise
	// use the fallback ratio. The throttled ratio is used to avoid
	// an endless loop of updates at particular viewport heights.
	// See: https://github.com/WordPress/gutenberg/issues/55112
	const ratio = ratioState ? ratioState : fallbackRatio;

	const { paletteColors, getThemeColors } = useStyles();

	const getColorsToShow = () => {
		// Use variation colors if provided, otherwise use current theme colors
		const colorsToShow =
			variation?.settings?.color?.palette?.theme || getThemeColors();
		// filter out the background color
		return colorsToShow
			.filter( ( color ) => color.color !== backgroundColor )
			.slice( 0, 4 );
	};

	// Reset leaked styles from WP common.css and remove main content layout padding and border.
	// If the type is 'font', add the font families to the styles.
	const editorStyles = useMemo( () => {
		return [
			...( type === 'font'
				? [
						{
							css: fontFamiliesToCSS( fontFamilies ),
							isGlobalStyles: true,
						},
				  ]
				: [] ),
			{
				css: 'html{overflow:hidden}body{min-width: 0;padding: 0;border: none;}',
				isGlobalStyles: true,
			},
		];
	}, [ fontFamilies, type ] );

	return (
		<>
			<div style={ { position: 'relative' } }>
				{ containerResizeListener }
			</div>
			<Iframe
				className="edit-site-global-styles-preview__iframe"
				style={ {
					width: '100%',
					height: normalizedHeight * ratio,
				} }
				tabIndex={ -1 }
			>
				<EditorStyles styles={ editorStyles } />
				<motion.div
					style={ {
						height: normalizedHeight * ratio,
						width: '100%',
						background: getVariationBackgroundColor(),
						cursor: 'pointer',
					} }
					initial="start"
				>
					<motion.div
						variants={ firstFrame }
						style={ {
							height: '100%',
							overflow: 'hidden',
						} }
					>
						<HStack
							spacing={ 10 * ratio }
							justify="center"
							style={ {
								height: '100%',
								overflow: 'hidden',
							} }
						>
							{ type === 'font' && (
								<div
									style={ {
										color: activeTextColor() || '#000000',
										whiteSpace: 'nowrap',
										paddingLeft: '5px',
										lineHeight: 1,
										padding: '0.2em',
									} }
								>
									<span
										style={ {
											fontFamily: headerFontFamily,
											fontSize: 50 * ratio,
											fontWeight: headerFontWeight,
											fontStyle: headerFontStyle,
											// Keep preview glyphs stable (Aa), regardless of any variation textTransform.
											textTransform: 'none',
										} }
									>
										A
									</span>
									<span
										style={ {
											fontFamily,
											fontSize: 40 * ratio,
											fontWeight,
											fontStyle,
											// Keep preview glyphs stable (Aa), regardless of any variation textTransform.
											textTransform: 'none',
										} }
									>
										a
									</span>
								</div>
							) }
							{ type === 'color' && (
								<HStack
									spacing={ 0 }
									alignment="center"
									style={ { margin: '0 0 0 10px' } }
									className="big-sky__color-swatch"
								>
									{ getColorsToShow().map(
										( { slug, color }, index ) => (
											<div
												key={ ` ${ slug }_${ index }` }
												style={ {
													height:
														normalizedColorSwatchSize *
														ratio,
													width:
														normalizedColorSwatchSize *
														ratio,
													background: color,
													borderRadius: '100%',
													margin: '0 0 0 -10px',
													border: `2px solid ${ getVariationBackgroundColor() }`,
													boxSizing: 'content-box',
												} }
											/>
										)
									) }
								</HStack>
							) }

							{ type === 'button' && (
								<motion.div
									style={ {
										color: activeTextColor() || '#000000',
										whiteSpace: 'nowrap',
										paddingLeft: '5px',
										lineHeight: 1,
										padding: '0.2em',
									} }
									animate={ { scale: 1, opacity: 1 } }
									initial={ { scale: 0.1, opacity: 0 } }
									transition={ {
										delay: 0.3,
										type: 'tween',
									} }
								>
									<div style={ { zoom: 0.8 } }>
										<button style={ buttonStyles }>
											{ ' ' }
										</button>
									</div>
								</motion.div>
							) }
						</HStack>
					</motion.div>
					<motion.div
						style={ {
							height: '100%',
							width: '100%',
							position: 'absolute',
							top: 0,
							overflow: 'hidden',
							filter: 'blur(60px)',
							opacity: 0.1,
						} }
					>
						<HStack
							spacing={ 0 }
							justify="flex-start"
							style={ {
								height: '100%',
								overflow: 'hidden',
							} }
						>
							{ paletteColors
								.slice( 0, 4 )
								.map( ( { color }, index ) => (
									<div
										key={ index }
										style={ {
											height: '100%',
											background: color,
											flexGrow: 1,
										} }
									/>
								) ) }
						</HStack>
					</motion.div>
					<motion.div
						variants={ secondFrame }
						style={ {
							height: '100%',
							width: '100%',
							overflow: 'hidden',
							position: 'absolute',
							top: 0,
						} }
					>
						<VStack
							spacing={ 3 * ratio }
							justify="center"
							style={ {
								height: '100%',
								overflow: 'hidden',
								padding: 10 * ratio,
								boxSizing: 'border-box',
							} }
						>
							{ label && (
								<div
									style={ {
										fontSize: 40 * ratio,
										fontFamily: headerFontFamily,
										color:
											type === 'color'
												? headerColor
												: '#1e1e1e',
										fontWeight: headerFontWeight,
										fontStyle: headerFontStyle,
										textTransform: headerTextTransform,
										lineHeight: '1em',
										textAlign: 'center',
									} }
								>
									{ label }
								</div>
							) }
						</VStack>
					</motion.div>
				</motion.div>
			</Iframe>
		</>
	);
};

export default StylesPreview;
