/**
 * External dependencies
 */
import classNames from 'classnames';

/**
 * WordPress dependencies
 */
import {
	store as blockEditorStore,
	BlockPreview,
} from '@wordpress/block-editor';
import { useDispatch, useSelect } from '@wordpress/data';
import {
	memo,
	useCallback,
	useEffect,
	useMemo,
	useRef,
	useState,
} from '@wordpress/element';

/**
 * Internal dependencies
 */
import './style.scss';
import usePatterns from '@hooks/use-patterns';
import useTemplateParts from '@hooks/use-template-parts';
import useVariations from '@hooks/use-variations';
import { animationTiming } from '@utils/constants';
import setDelay from '@utils/set-delay';
import ThinkingMessage from '../thinking-message/index.js';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import { recordTracksEvent } from '@utils/tracks';
import {
	isTemplatePartPatternSlug,
	TemplatePartPatternSlug,
	TemplatePartSlug,
} from '@utils/template-parts';
import { fontFamiliesToCSS } from '@utils/font-families-to-css';

const MAX_SHOWN_PATTERNS = 4;

// By default the block will collapse into a "hamburger" menu on smaller screens.
// This forces the block to display as a full width menu no matter
// the viewportWidth of the preview.
const unsetNavigationBlockMobileLayout = ( blocks ) => {
	return blocks.map( ( block ) => {
		// If this is a navigation block, set overlayMenu to never
		if ( block.name === 'core/navigation' ) {
			return {
				...block,
				attributes: {
					...block.attributes,
					overlayMenu: 'never',
				},
			};
		}

		// Recursively process inner blocks if they exist
		if ( block.innerBlocks?.length ) {
			return {
				...block,
				innerBlocks: unsetNavigationBlockMobileLayout(
					block.innerBlocks
				),
			};
		}

		return block;
	} );
};

const ItemPreview = ( {
	item,
	index,
	additionalStyles,
	clientId = null,
	onRendered,
	onAfterClick = () => {},
	isFullLayout = false,
	isSelected = false,
} ) => {
	const [ isResolved, setIsResolved ] = useState( false );
	const { getBlock, getSelectedBlockClientId } =
		useSelect( blockEditorStore );

	// Track the selection state to prevent unnecessary re-selection
	const prevIsSelectedRef = useRef( false );
	const { selectBlock } = useDispatch( blockEditorStore );

	const { insertPatterns } = usePatterns();
	const { replaceTemplatePart } = useTemplateParts();
	const { getFontVariations } = useVariations();

	// Generate CSS from font families
	const fontFamiliesCSS = useMemo( () => {
		const fontVariations = getFontVariations();
		if ( ! fontVariations || ! Array.isArray( fontVariations ) ) {
			return '';
		}

		// Extract all font families from all variations
		const allFontFamilies = fontVariations.flatMap( ( variation ) => {
			return variation?.settings?.typography?.fontFamilies || [];
		} );

		if ( allFontFamilies.length === 0 ) {
			return '';
		}

		return fontFamiliesToCSS( allFontFamilies );
	}, [ getFontVariations ] );

	// Combine additional styles with font families CSS
	const combinedAdditionalStyles = useMemo( () => {
		const styles = [ ...( additionalStyles || [] ) ];

		if ( fontFamiliesCSS ) {
			styles.push( {
				css: fontFamiliesCSS,
				__unstableType: 'presets',
			} );
		}

		return styles;
	}, [ additionalStyles, fontFamiliesCSS ] );

	const fullLayoutItemSelect = useCallback( async () => {
		// filter out template part patterns
		const contentPatterns = item.patterns.filter(
			( pattern ) => ! isTemplatePartPatternSlug( pattern.category )
		);

		// replace the header template part with the header pattern
		const headerPattern = item.patterns.find(
			( pattern ) => pattern.category === TemplatePartPatternSlug.Header
		);
		if ( headerPattern ) {
			await replaceTemplatePart(
				TemplatePartSlug.Header,
				headerPattern.blocks
			);
		}

		// replace the hero template part with the hero pattern
		const heroPattern = item.patterns.find(
			( pattern ) =>
				pattern.category === TemplatePartPatternSlug.HeaderHero
		);
		if ( heroPattern ) {
			await replaceTemplatePart(
				TemplatePartSlug.HeaderHero,
				heroPattern.blocks
			);
		}

		// replace the footer template part with the footer pattern
		const footerPattern = item.patterns.find(
			( pattern ) => pattern.category === TemplatePartPatternSlug.Footer
		);
		if ( footerPattern ) {
			await replaceTemplatePart(
				TemplatePartSlug.Footer,
				footerPattern.blocks
			);
		}

		// This is a full page layout picker, so we need to update the selected item with all patterns on canvas.
		insertPatterns( contentPatterns, null, 'replace', false );

		const { canvasiFrameDocument } = getCanvasIframeElements();
		const el = canvasiFrameDocument.querySelector(
			`.wp-block:first-child`
		);

		await setDelay( animationTiming.scrollWaitTime );
		el.scrollIntoView( {
			behavior: 'instant',
			block: 'start',
		} );
	}, [ insertPatterns, item.patterns, replaceTemplatePart ] );

	const singleSectionItemSelect = useCallback( async () => {
		const replaceClientId = clientId ?? getSelectedBlockClientId();

		// This is a single section picker, so we only need to update the pattern in specified block.
		if ( ! replaceClientId ) {
			return;
		}

		// Ensure item and patterns exist and are valid
		if (
			! item?.patterns ||
			! Array.isArray( item.patterns ) ||
			item.patterns.length === 0
		) {
			return;
		}

		const firstPattern = item.patterns[ 0 ];
		if (
			! firstPattern?.blocks ||
			! Array.isArray( firstPattern.blocks ) ||
			firstPattern.blocks.length === 0
		) {
			return;
		}

		// Check if this pattern is already active in the canvas
		const isPatternAlreadyActive = () => {
			// Use native Gutenberg selector to check if block exists
			const rootClientId = firstPattern.blocks[ 0 ]?.clientId;
			const existingBlock = getBlock( rootClientId );
			return existingBlock !== null;
		};

		// Prevent action if this pattern is already active in the canvas
		if ( isPatternAlreadyActive() ) {
			return;
		}

		// Get the root client ID for the pattern
		const rootClientId = firstPattern.blocks[ 0 ]?.clientId;
		if ( ! rootClientId ) {
			return;
		}

		if (
			firstPattern.category &&
			[
				TemplatePartPatternSlug.Header,
				TemplatePartPatternSlug.Footer,
			].includes( firstPattern.category )
		) {
			await replaceTemplatePart(
				firstPattern.category,
				firstPattern.blocks
			);
		} else {
			insertPatterns( item.patterns, replaceClientId, 'replace' );
		}
		selectBlock( rootClientId );
		onAfterClick( rootClientId, index );
	}, [
		clientId,
		getSelectedBlockClientId,
		item.patterns,
		selectBlock,
		onAfterClick,
		index,
		getBlock,
		replaceTemplatePart,
		insertPatterns,
	] );

	useEffect( () => {
		async function checkIsResolved() {
			if ( ! item.resolvers ) {
				setIsResolved( true );
				onRendered();
				return;
			}

			await Promise.all(
				item.resolvers.map( async ( resolver ) => resolver.resolver )
			);
			setIsResolved( true );
			onRendered();
		}
		if ( ! isResolved ) {
			checkIsResolved();
		}
	}, [ item, isResolved, onRendered ] );

	const shownPatterns = useMemo( () => {
		if ( ! isResolved || ! Array.isArray( item?.patterns ) ) {
			return [];
		}

		// Make a deep copy of the patterns using JSON parse/stringify
		const patterns = JSON.parse( JSON.stringify( item.patterns ) );

		// Get the header pattern first
		const headerPattern = patterns.find(
			( pattern ) => pattern.category === TemplatePartPatternSlug.Header
		);

		// Get the hero pattern
		const heroPattern = patterns.find(
			( pattern ) =>
				pattern.category === TemplatePartPatternSlug.HeaderHero
		);

		// If we have both hero and header patterns, replace the header template part in hero's inner blocks
		if ( heroPattern && headerPattern ) {
			const findAndReplaceHeaderTemplatePart = ( blocks ) => {
				return blocks.map( ( block ) => {
					if (
						block.name === 'core/template-part' &&
						block.attributes.slug === TemplatePartSlug.Header
					) {
						// Replace the entire template part with the header pattern blocks
						return headerPattern.blocks[ 0 ];
					}
					if ( block.innerBlocks ) {
						return {
							...block,
							innerBlocks: findAndReplaceHeaderTemplatePart(
								block.innerBlocks
							),
						};
					}
					return block;
				} );
			};

			// Replace the header template part in hero pattern
			heroPattern.blocks = findAndReplaceHeaderTemplatePart(
				heroPattern.blocks
			);
		}

		return (
			patterns
				.filter(
					( pattern ) =>
						pattern &&
						Array.isArray( pattern.blocks ) &&
						pattern.blocks.length > 0
				)
				// filter out header pattern if a hero exists
				.filter( ( pattern ) => {
					if ( pattern.category === TemplatePartPatternSlug.Header ) {
						return ! patterns.some(
							( p ) =>
								p.category ===
								TemplatePartPatternSlug.HeaderHero
						);
					}
					return true;
				} )
				.map( ( pattern ) => ( {
					...pattern,
					blocks: unsetNavigationBlockMobileLayout( pattern.blocks ),
				} ) )
				.map( ( pattern ) => pattern.blocks[ 0 ] )
				.slice( 0, MAX_SHOWN_PATTERNS )
		);
	}, [ item?.patterns, isResolved ] );

	const onItemSelect = useCallback( () => {
		recordTracksEvent( 'patterns_preview_click', {
			type: isFullLayout ? 'full-layout' : 'single-pattern',
		} );
		if ( isFullLayout ) {
			fullLayoutItemSelect();
		} else {
			singleSectionItemSelect();
		}
	}, [ isFullLayout, fullLayoutItemSelect, singleSectionItemSelect ] );

	// Effect to handle selection from parent - must be before any returns
	useEffect( () => {
		// Only proceed if selection state changed from false to true
		if ( isSelected && isResolved && ! prevIsSelectedRef.current ) {
			// Update the ref to track the current selection state
			prevIsSelectedRef.current = true;

			// Trigger the actual selection logic without adding selected class
			if ( isFullLayout ) {
				fullLayoutItemSelect();
			} else {
				singleSectionItemSelect();
			}
		} else if ( ! isSelected ) {
			// Reset when selection is lost
			prevIsSelectedRef.current = false;
		}
	}, [
		isSelected,
		index,
		isFullLayout,
		fullLayoutItemSelect,
		singleSectionItemSelect,
		isResolved,
	] );

	if ( ! isResolved ) {
		return (
			<div className="big-sky__item-loading big-sky__item-preview">
				<ThinkingMessage />
			</div>
		);
	}

	return (
		<div
			className={ classNames( 'big-sky__item-preview' ) }
			onClick={ onItemSelect }
			onKeyDown={ ( e ) => {
				if ( e.key === 'Enter' || e.key === ' ' ) {
					e.preventDefault();
					onItemSelect();
				}
			} }
			role="button"
			tabIndex={ 0 }
		>
			<BlockPreview
				blocks={ shownPatterns }
				viewportWidth={ 1400 }
				additionalStyles={ combinedAdditionalStyles }
			/>
		</div>
	);
};

export default memo( ItemPreview );
