/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { dispatch } from '@wordpress/data';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

interface OpenHelpCenterInput {
	message?: string;
	summary?: string;
}

interface HelpCenterDispatch {
	setNewMessagingChat?: ( args: {
		initialMessage: string;
		siteUrl?: string;
		siteId?: string;
		userFieldFlowName?: string;
		externalChatProvider?: string;
		externalChatId?: string;
	} ) => void;
	setShowHelpCenter?: (
		show: boolean,
		options?: {
			hasPremiumSupport?: boolean;
			hideBackButton?: boolean;
			contextTerm?: string;
		}
	) => void;
	setNavigateToRoute?: ( route: string ) => void;
}

interface BigSkyWindow extends Window {
	__agentsManagerActions?: {
		getSessionId?: () => string;
	};
	JP_CONNECTION_INITIAL_STATE?: {
		userConnectionData?: {
			currentUser?: {
				blogId?: string | number;
			};
		};
	};
	Jetpack_Editor_Initial_State?: {
		wpcomBlogId?: string | number;
		siteFragment?: string;
	};
}

const DEFAULT_HELP_MESSAGE = 'The user asked to talk to a human about Big Sky.';

// Names Agents Manager as the chat provider so Odie can tie this request to its session.
const EXTERNAL_CHAT_PROVIDER = 'agents-manager';

const getBigSkyWindow = (): BigSkyWindow => window as BigSkyWindow;

// The "Get help" button runs inside the Agents Manager chat, so its session ID is
// available on the global actions. Returns '' when the global is not present.
function getAgentsManagerSessionId(): string {
	return getBigSkyWindow().__agentsManagerActions?.getSessionId?.() || '';
}

function getSiteId(): string {
	const bigSkyWindow = getBigSkyWindow();

	return String(
		bigSkyWindow.JP_CONNECTION_INITIAL_STATE?.userConnectionData
			?.currentUser?.blogId ||
			bigSkyWindow.Jetpack_Editor_Initial_State?.wpcomBlogId ||
			''
	);
}

function getSiteUrl(): string {
	return String(
		getBigSkyWindow().Jetpack_Editor_Initial_State?.siteFragment ||
			window.location.hostname ||
			''
	);
}

function getSupportMessage( message?: string ): string {
	return message || DEFAULT_HELP_MESSAGE;
}

function getHumanSupportRoute( input?: OpenHelpCenterInput ): string {
	const params = new URLSearchParams();
	const siteId = getSiteId();
	const siteUrl = getSiteUrl();
	const sessionId = getAgentsManagerSessionId();

	params.set( 'provider', 'zendesk' );
	params.set( 'userFieldMessage', getSupportMessage( input?.message ) );
	params.set( 'userFieldFlowName', 'big-sky-human-support' );
	params.set( 'externalChatProvider', EXTERNAL_CHAT_PROVIDER );

	if ( siteId ) {
		params.set( 'siteId', siteId );
	}

	if ( siteUrl ) {
		params.set( 'siteUrl', siteUrl );
	}

	if ( sessionId ) {
		params.set( 'externalChatId', sessionId );
	}

	return `/odie?${ params.toString() }`;
}

function clickHumanSupportButton(): boolean {
	const buttons = Array.from(
		document.querySelectorAll< HTMLButtonElement >(
			'.help-center button, .odie__transfer-chat button'
		)
	);
	const button = buttons.find( ( candidate ) => {
		const text = candidate.textContent?.trim().toLowerCase() || '';
		return (
			! candidate.disabled &&
			( text === 'get support' ||
				text.includes( 'connect me with someone' ) ||
				text.includes( 'take me to that chat' ) ||
				text.includes( 'go back to that conversation' ) )
		);
	} );

	if ( ! button ) {
		return false;
	}

	button.click();
	return true;
}

function setNativeInputValue(
	element: HTMLInputElement | HTMLTextAreaElement,
	value: string
): void {
	const prototype = Object.getPrototypeOf( element );
	const descriptor = Object.getOwnPropertyDescriptor( prototype, 'value' );

	if ( descriptor?.set ) {
		descriptor.set.call( element, value );
	} else {
		element.value = value;
	}
}

function sendInitialMessageToSupportAssistant(
	input?: OpenHelpCenterInput
): boolean {
	const chatInput = document.querySelector<
		HTMLInputElement | HTMLTextAreaElement
	>(
		'.help-center textarea, .help-center input[type="text"], textarea[placeholder*="Ask"], input[placeholder*="Ask"]'
	);

	if ( ! chatInput ) {
		return false;
	}

	const initialMessage = getSupportMessage( input?.message );
	setNativeInputValue( chatInput, initialMessage );
	chatInput.dispatchEvent( new Event( 'input', { bubbles: true } ) );
	chatInput.dispatchEvent( new Event( 'change', { bubbles: true } ) );
	chatInput.focus();

	window.setTimeout( () => {
		const submitButton = document.querySelector< HTMLButtonElement >(
			'.help-center button[class*="ChatInput-module_button"], .help-center button[aria-label*="Send"], .help-center button[type="submit"]'
		);

		if ( submitButton && ! submitButton.disabled ) {
			submitButton.click();
		}
	}, 100 );

	return true;
}

export function openHelpCenterChat( input?: OpenHelpCenterInput ): boolean {
	// eslint-disable-next-line @wordpress/data-no-store-string-literals
	const helpCenterDispatch = dispatch(
		'automattic/help-center'
	) as HelpCenterDispatch;

	if ( ! helpCenterDispatch?.setShowHelpCenter ) {
		return false;
	}

	// Mark this flow as premium before navigating. Help Center uses this to decide
	// whether the user can be forwarded from Odie to Zendesk Messaging.
	helpCenterDispatch.setShowHelpCenter( true, {
		hasPremiumSupport: true,
		hideBackButton: false,
		contextTerm: '',
	} );

	if ( helpCenterDispatch?.setNewMessagingChat ) {
		const sessionId = getAgentsManagerSessionId();

		helpCenterDispatch.setNewMessagingChat( {
			initialMessage: getSupportMessage( input?.message ),
			siteUrl: getSiteUrl(),
			siteId: getSiteId(),
			userFieldFlowName: 'big-sky-human-support',
			externalChatProvider: EXTERNAL_CHAT_PROVIDER,
			...( sessionId && { externalChatId: sessionId } ),
		} );
	} else if ( helpCenterDispatch?.setNavigateToRoute ) {
		// The `provider=zendesk` route is what the Help Center/Odie UI watches for
		// to create a Zendesk Messaging conversation with human support.
		const route = getHumanSupportRoute( input );
		helpCenterDispatch.setNavigateToRoute( route );
	} else {
		return false;
	}

	window.setTimeout( () => {
		sendInitialMessageToSupportAssistant( input );
	}, 1500 );

	window.setTimeout( () => {
		clickHumanSupportButton();
	}, 3000 );

	return true;
}

/**
 * Open Help Center chat ability.
 *
 * Opens WordPress.com Help Center chat so the user can contact a human.
 */
export const openHelpCenterAbility: Ability = {
	name: 'big-sky/open-help-center',
	label: __( 'Show Help Center chat button', 'big-sky' ),
	category: 'big-sky',
	description:
		'Show the user a button they can click to open WordPress.com Help Center chat when they ask to talk to a human, contact support, or get help from a person. This ability does not open Help Center automatically.',
	input_schema: {
		type: 'object',
		properties: {
			message: {
				type: 'string',
				description:
					'Initial message to send or prefill in the Support Assistant. Compose this message as if it was written by the user, using natural language and no technical jargon. This message MUST include a concise summary of the current conversation backscroll, what the user is trying to do, what has already been attempted, relevant site/editor context, and that the user wants to talk to a human support agent.',
			},
			summary: {
				type: 'string',
				description:
					"A short, friendly confirmation in the agent's own voice telling the user to click the button to open Help Center and talk to a human. Do NOT say that Help Center is opening, has opened, or is being opened automatically. This is separate from the Support Assistant message and should not include the full backscroll summary.",
			},
		},
		additionalProperties: false,
	},
	output_schema: {
		type: 'object',
		properties: {
			result: {
				type: 'object',
				properties: {
					success: {
						type: 'boolean',
					},
					url: {
						type: 'string',
					},
					message: {
						type: 'string',
						description:
							'Human-readable confirmation or error message for the agent.',
					},
				},
				required: [ 'success', 'url', 'message' ],
			},
			returnToAgent: {
				type: 'boolean',
			},
		},
		required: [ 'result', 'returnToAgent' ],
	},
	callback: async ( input: OpenHelpCenterInput ) => {
		const message =
			input?.summary ||
			'Click the button below to open Help Center and talk to a human.';

		return {
			result: {
				success: true,
				url: '',
				message,
			},
			returnToAgent: true,
			agentMessage: JSON.stringify( {
				tool_id: 'big_sky__show_component',
				data: {
					type: 'open-help-center-button',
					props: {
						message: input?.message,
						label: __( 'Get help', 'big-sky' ),
					},
					summary: message,
					isCurrent: true,
				},
			} ),
		};
	},
};
