/**
 * External dependencies
 */
import classnames from 'classnames';

/**
 * WordPress dependencies
 */
import { __unstableMotion as motion } from '@wordpress/components';
import { useCallback, useEffect, useRef, useState } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { recordTracksEvent } from '@utils/tracks';
import './style.scss';

const ActionCarousel = ( {
	actions,
	animationVariants = {},
	showSpotlight = false,
} ) => {
	const sliderRef = useRef();
	const [ globalMousePosition, setGlobalMousePosition ] = useState( {
		x: 0,
		y: 0,
	} );
	const [ buttonRects, setButtonRects ] = useState( {} );
	let isDown = false;
	let startX;
	let scrollLeft;

	// Update all button positions when mouse moves or scroll happens
	const updateAllButtonRects = useCallback( () => {
		actions.forEach( ( action ) => {
			const element = document.querySelector(
				`[data-action-key="${ action.key }"]`
			);
			if ( element ) {
				const rect = element.getBoundingClientRect();
				setButtonRects( ( prev ) => ( {
					...prev,
					[ action.key ]: rect,
				} ) );
			}
		} );
	}, [ actions ] );

	useEffect( () => {
		const handleGlobalMouseMove = ( e ) => {
			setGlobalMousePosition( { x: e.clientX, y: e.clientY } );
			updateAllButtonRects();
		};

		const handleScroll = () => {
			updateAllButtonRects();
		};

		window.addEventListener( 'mousemove', handleGlobalMouseMove );
		window.addEventListener( 'scroll', handleScroll, true );
		return () => {
			window.removeEventListener( 'mousemove', handleGlobalMouseMove );
			window.removeEventListener( 'scroll', handleScroll, true );
		};
	}, [ actions, updateAllButtonRects ] );

	const calculateSpotlight = ( rect ) => {
		if ( ! rect ) return 'none';

		const distance = Math.sqrt(
			Math.pow(
				globalMousePosition.x - ( rect.left + rect.width / 2 ),
				2
			) +
				Math.pow(
					globalMousePosition.y - ( rect.top + rect.height / 2 ),
					2
				)
		);

		const maxDistance = 300;
		if ( distance > maxDistance ) return 'none';

		const opacity = Math.max( 0, 0.5 * ( 1 - distance / maxDistance ) );
		const x = globalMousePosition.x - rect.left;
		const y = globalMousePosition.y - rect.top;

		return `radial-gradient(circle at ${ x }px ${ y }px,
			rgba(255,255,255,${ opacity * 0.6 }) 0%,
			rgba(255,255,255,${ opacity * 0.4 }) 20%,
			rgba(255,255,255,0) 80%)`;
	};

	const handlePointerDown = ( e ) => {
		isDown = true;
		sliderRef.current.classList.add( 'active' );
		startX = e.pageX - sliderRef.current.offsetLeft;
		scrollLeft = sliderRef.current.scrollLeft;
	};

	const handlePointerLeave = () => {
		isDown = false;
		sliderRef.current.classList.remove( 'active' );
	};

	const handlePointerUp = () => {
		isDown = false;
		sliderRef.current.classList.remove( 'active' );
	};

	const handlePointerMove = ( e ) => {
		if ( ! isDown ) return;
		e.preventDefault();
		const x = e.pageX - sliderRef.current.offsetLeft;
		const walk = ( x - startX ) * 2;
		sliderRef.current.scrollLeft = scrollLeft - walk;
		updateAllButtonRects();
	};

	return (
		<div
			data-testid="chat-actions"
			className={ classnames( 'big-sky__chat-actions' ) }
		>
			<div
				className={ classnames( 'big-sky__chat-actions__carousel', {
					draggable: actions.length > 1,
				} ) }
				ref={ sliderRef }
				role="region"
				tabIndex={ 0 }
				{ ...( actions.length > 1 && {
					onPointerDown: handlePointerDown,
					onPointerLeave: handlePointerLeave,
					onPointerUp: handlePointerUp,
					onPointerMove: handlePointerMove,
				} ) }
			>
				{ actions.map( ( action, index ) => (
					<motion.button
						initial={ animationVariants.initial || {} }
						animate={ animationVariants.animate || {} }
						exit={ animationVariants.exit || {} }
						transition={ {
							...( animationVariants.transition || {} ),
							delay:
								index *
								( animationVariants.transition?.delay || 0 ),
						} }
						key={ action.key }
						data-action-key={ action.key }
						style={ {
							...( showSpotlight && {
								backgroundImage: calculateSpotlight(
									buttonRects[ action.key ]
								),
							} ),
							position: 'relative',
							overflow: 'hidden',
						} }
						onClick={ ( e ) => {
							if ( action.action_type === 'suggested' ) {
								recordTracksEvent( 'chat_suggestion_click', {
									action_key: action.key,
								} );
							} else {
								recordTracksEvent( 'chat_action_click', {
									action_key: action.key,
								} );
								// disable the button after an action is clicked
								e.target.closest(
									'.big-sky__chat-actions__carousel__item'
								).disabled = true;
							}
							action.onClick();
						} }
						className={ classnames(
							'big-sky__chat-actions__carousel__item',
							{
								'confirmation-action':
									action.type === 'confirmation',
								'confirmation-action-destructive':
									action.type === 'confirmationDestructive',
							}
						) }
						title={ `${ action.actionName } ${ action.description }` }
					>
						<span>{ action.actionName }</span>
						{ action.description && <p>{ action.description }</p> }
					</motion.button>
				) ) }
			</div>
		</div>
	);
};

export default ActionCarousel;
