/**
 * WordPress dependencies
 */
import { useDispatch } from '@wordpress/data';
import { useEffect } from '@wordpress/element';

/**
 * Internal dependencies
 */
import useCreateToolCallback from '@ai/assistants/shared/use-create-tool-callback.js';
import useSiteToolFunctions from '@ai/assistants/shared/start-over/use-tool-functions.js';
import { store as aiStore } from '@store';
import { __ } from '@wordpress/i18n';
import { ChatSuggestions } from '@ai/assistants/shared/make-suggestions/index.js';
import useCurrentScreen from '@hooks/use-current-screen';
import { localToolRunningMessage } from '@utils/constants';

import { ASSISTANTS } from '../constants.js';

const useSiteAdminToolkit = () => {
	const { createToolCallback } = useCreateToolCallback();
	const { registerCallbacks, addMessage } = useDispatch( aiStore );
	const { startOver, startOverActions } = useSiteToolFunctions();
	const { deleteMarkedMessages, addMessageToDelete } = useDispatch( aiStore );
	const { isSiteEditor } = useCurrentScreen();

	const callbacks = {
		start_over: createToolCallback( {
			name: 'start_over',
			action: async () => {
				const args = {
					actions: startOverActions,
				};
				if ( isSiteEditor ) {
					addMessage( {
						role: 'assistant',
						content: [
							{
								type: 'text',
								text: __(
									'All customizations and pages on your site will be permanently reset. Are you sure you want to start over?',
									'big-sky'
								),
							},
						],
					} );
					const startOverMessage = await addMessage( {
						role: 'assistant',
						content: [
							{
								type: 'component',
								component: ChatSuggestions,
								componentProps: {
									args,
									respond: async ( _args ) => {
										startOver( _args );
										deleteMarkedMessages();
									},
								},
							},
						],
					} );

					addMessageToDelete( {
						id: startOverMessage?.message?.id,
					} );

					// Return here to wait for user confirmation

					return {
						awaitingUserInput: true,
						unfulfilled: true,
						agentMessage: localToolRunningMessage,
					};
				}
				addMessage( {
					role: 'assistant',
					content: [
						{
							type: 'text',
							text: __(
								`You need to be in the site editor to start over. Please switch to the [Site Editor](/wp-admin/site-editor.php) and try again.`,
								'big-sky'
							),
						},
					],
				} );
			},
			closeChatWhenDone: () => false,
		} ),
	};

	useEffect( () => {
		registerCallbacks( ASSISTANTS.SITE_ADMIN, callbacks );
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ registerCallbacks ] );

	return callbacks;
};

export default useSiteAdminToolkit;
