/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Set styles ability callback type
 */
export type SetStylesCallback = ( args: {
	color?: string;
	font?: string;
	button?: string;
	updateBlocks?: boolean;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
} >;

/**
 * Set styles ability
 *
 * Apply color palette, font pairing, and button style variations to the WordPress site.
 * Accepts variation titles (e.g., "Professional", "Montserrat + Open Sans") and applies
 * the complete styling including colors, typography, button styles, and all associated
 * theme variations.
 *
 * @param callback - The set styles callback function from the hook
 * @return The set styles ability definition
 */
export const setStylesAbility = ( callback: SetStylesCallback ): Ability => ( {
	name: 'big-sky/set-styles',
	label: __( 'Set Styles', 'big-sky' ),
	category: 'big-sky',
	description:
		'Apply color palette, font pairing, and button style variations to the WordPress site. Accepts variation titles (e.g., "Professional", "Montserrat + Open Sans") and applies the complete styling including colors, typography, button styles, and all associated theme variations.',
	input_schema: {
		type: 'object',
		properties: {
			color: {
				type: 'string',
				description:
					'The title of the color palette variation to apply (e.g., "Professional", "Vibrant", "Minimal"). This will update the site color scheme including background colors, text colors, button colors, and section variations.',
			},
			font: {
				type: 'string',
				description:
					'The title of the font pairing variation to apply (e.g., "Montserrat + Open Sans", "Playfair Display + Source Sans Pro"). This will update typography for headings, body text, and buttons across the entire site.',
			},
			button: {
				type: 'string',
				description:
					'The title of the button style variation to apply (e.g., "Rounded", "Sharp", "Pill"). This will update button border radius, spacing, and other button-specific styling.',
			},
			updateBlocks: {
				type: 'boolean',
				description:
					'Whether to update existing blocks with the new style variations. Default is false. When true, will apply color and typography changes to all existing blocks on the page.',
				default: false,
			},
		},
		additionalProperties: false,
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
