/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Internal dependencies
 */
import type { FilePart } from '@utils/canvas-capture';

/**
 * Update theme ability callback type
 */
export type UpdateThemeCallback = ( args: {
	settings?: Record< string, any > | null;
	styles?: Record< string, any > | null;
	summary?: string;
	followUpTasks?: boolean;
} ) => Promise< {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
	// A sibling of `result`, not part of it: the agent client lifts this onto
	// the tool-result part rather than into the text the model reads.
	__file_parts?: FilePart[];
} >;

/**
 * Update theme ability
 *
 * Updates WordPress theme settings and styles using theme.json format.
 *
 * @param callback - The update theme callback function from the hook
 * @return The update theme ability definition
 */
