/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Add pages ability callback type
 */
export type AddPagesCallback = ( args: {
	pages: Array< {
		name: string;
		slug: string;
		path?: string;
		layouts?: Array< {
			patterns?: Array< {
				blocks?: any[];
			} >;
		} >;
	} >;
	navigationMenuId?: number | string;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
} >;

/**
 * Add pages ability
 *
 * Creates multiple WordPress pages with generated content from patterns and layouts.
 * Page titles are provided by the backend, and page content is composed from layout blocks.
 * Also updates site navigation.
 *
 * @param callback - The add pages callback function from the hook
 * @return The add pages ability definition
 */
export const addPagesAbility = ( callback: AddPagesCallback ): Ability => ( {
	name: 'big-sky/add-pages',
	label: __( 'Add Pages', 'big-sky' ),
	category: 'big-sky',
	description:
		'Creates multiple WordPress pages with generated content from patterns and layouts. Page titles are provided by the backend, and page content is composed from layout blocks. Also updates site navigation.',
	input_schema: {
		type: 'object',
		properties: {
			pages: {
				type: 'array',
				description:
					'Array of page objects to create. Each page will be created with content generated from its patterns and layouts.',
				items: {
					type: 'object',
					properties: {
						name: {
							type: 'string',
							description:
								'The page title (e.g., "About Us", "Services", "Contact")',
						},
						slug: {
							type: 'string',
							description:
								'The URL slug for the page (e.g., "about-us", "services", "contact")',
						},
						path: {
							type: 'string',
							description:
								'Optional path/URL for the page. If provided, only a navigation link will be added instead of creating a new page (e.g., "/product-category/services/")',
						},
						layouts: {
							type: 'array',
							description:
								'Array of layout objects. The first layout will be used for page content.',
							items: {
								type: 'object',
								properties: {
									patterns: {
										type: 'array',
										description:
											'Array of pattern objects containing blocks to compose the page layout',
										items: {
											type: 'object',
											properties: {
												blocks: {
													type: 'array',
													description:
														'WordPress block objects to include in the page',
													items: {
														type: 'object',
														description:
															'WordPress block object',
													},
												},
											},
										},
									},
								},
							},
						},
					},
					required: [ 'name', 'slug' ],
				},
			},
			navigationMenuId: {
				type: [ 'number', 'string' ],
				description:
					'Optional ID of the wp_navigation menu to update. If not provided, will use the default navigation menu.',
			},
		},
		required: [ 'pages' ],
		additionalProperties: false,
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
