import { getCustomAction } from '@store/custom-actions';
// eslint-disable-next-line import/no-unresolved
import { getAgentManager } from '@automattic/agenttic-client';

const AGENT_KEYS_TO_CHECK = [ 'dolly', 'wp-orchestrator' ];

interface ToolCallMatch {
	toolCallId: string;
	messageId?: string;
}

export const getToolCallIdFromConversationHistory = (
	toolId: string,
	messageId?: string
): string | null => {
	const manager =
		getCustomAction( 'getAgentManager' )?.() || getAgentManager();
	const matches: ToolCallMatch[] = [];

	for ( const agentKey of AGENT_KEYS_TO_CHECK ) {
		if ( ! manager?.hasAgent?.( agentKey ) ) {
			continue;
		}

		const history = manager?.getConversationHistory?.( agentKey ) || [];

		for ( const message of history ) {
			for ( const part of message.parts || [] ) {
				const data = part?.data;

				if (
					data?.toolId !== toolId ||
					! data.toolCallId ||
					! data.arguments
				) {
					continue;
				}

				matches.push( {
					toolCallId: data.toolCallId,
					messageId: message.messageId,
				} );
			}
		}
	}

	const matchedByMessageId = messageId
		? matches.find( ( match ) => match.messageId === messageId )
		: null;

	return (
		matchedByMessageId?.toolCallId ||
		matches[ matches.length - 1 ]?.toolCallId ||
		null
	);
};
