/**
 * Types
 */
interface BlockAttributes {
	className?: string;
	url?: string;
	alt?: string;
	id?: number;
	[ key: string ]: unknown;
}

interface BlockData {
	name: string;
	clientId?: string;
	attributes?: BlockAttributes;
	innerBlocks?: BlockData[];
}

interface BlockUpdate extends BlockData {
	clientId: string;
}

interface BlockInsert {
	parentClientId?: string;
	index?: number;
	block: BlockData;
}

type BlockDelete = string;

interface EditResults {
	updates?: BlockUpdate[];
	inserts?: BlockInsert[];
	deletes?: BlockDelete[];
	summary?: string;
	customCSS?: string;
}

type ApplyBlockEditsChangeType = 'text-content' | 'other';

interface ApplyBlockEditsArgs {
	updates?: BlockUpdate[];
	inserts?: BlockInsert[];
	deletes?: BlockDelete[];
	summary?: string;
	followUpTasks?: boolean;
	reverseMap?: ClientIdMap;
	messageId: string;
	toolCallId?: string;
	suppressAssistantMessage?: boolean;
	resetBlockProcessingStates?: boolean;
	customCSS?: string;
	visualCheckPending?: boolean;
}

interface ApplyBlockEditsResultData {
	success: boolean;
	message: string;
	outcome?: 'updated' | 'no-changes';
	changeType?: ApplyBlockEditsChangeType;
	error?: string;
	details?: unknown;
}

interface BlockType {
	name: string;
	[ key: string ]: unknown;
}

interface Block {
	clientId: string;
	name: string;
	attributes?: BlockAttributes;
	innerBlocks?: Block[];
}

const ROOT_BLOCK_STATE_KEYS = [
	'headerBlocks',
	'headerHeroBlocks',
	'footerBlocks',
	'contentBlocks',
] as const;

type RootBlocksState = Partial<
	Record< ( typeof ROOT_BLOCK_STATE_KEYS )[ number ], Block[] >
>;

interface BlockDifference {
	from: unknown;
	to: unknown;
}

interface ModifiedBlock {
	clientId: string;
	name: string;
	changes: Record< string, BlockDifference | Record< string, unknown > >;
}

interface BlockStateComparison {
	added: Array< {
		clientId: string;
		name: string;
		attributes?: BlockAttributes;
		innerBlocks: number;
	} >;
	removed: Array< {
		clientId: string;
		name: string;
		attributes?: BlockAttributes;
		innerBlocks: number;
	} >;
	modified: ModifiedBlock[];
}

interface ValidationDetailItem {
	[ key: string ]: unknown;
}

