const GLOBAL_STYLES_UNAVAILABLE_ERROR =
	'Custom CSS could not be updated because global styles are unavailable.';

/**
 * The tool-result message the client renders this apply from.
 *
 * @param {string}  toolCallId         The tool call being answered.
 * @param {Object}  result             The apply's own result.
 * @param {boolean} followUpTasks      Whether more work follows.
 * @param {boolean} visualCheckPending Whether the server may hold its
 *                                     acknowledgement back for a look at the
 *                                     capture that rode along with this
 *                                     result. Omitted rather than sent false,
 *                                     so a payload with no check pending keeps
 *                                     exactly its previous shape.
 * @return {string} The serialized message.
 */
const createApplyBlockEditsAgentMessage = (
	toolCallId: string,
	result: ApplyBlockEditsResultData,
	followUpTasks: boolean,
	visualCheckPending = false
): string =>
	JSON.stringify( {
		tool_id: APPLY_BLOCK_EDITS_TOOL_ID,
		tool_call_id: toolCallId,
		data: {
			result,
			followUpTasks,
			...( visualCheckPending ? { visualCheckPending: true } : {} ),
		},
	} );

const getApplyBlockEditsChangeType = (
	editResults: EditResults
): ApplyBlockEditsChangeType => {
	if (
		! editResults.updates?.length ||
		editResults.inserts?.length ||
		editResults.deletes?.length ||
		typeof editResults.customCSS === 'string'
	) {
		return 'other';
	}

	return editResults.updates.every( ( update ) => {
		const attributeKeys = Object.keys( update.attributes || {} );

		return (
			attributeKeys.length === 1 &&
			[ 'content', 'text', 'label' ].includes( attributeKeys[ 0 ] ) &&
			( update.innerBlocks === undefined ||
				( Array.isArray( update.innerBlocks ) &&
					update.innerBlocks.length === 0 ) )
		);
	} )
		? 'text-content'
		: 'other';
};

