/**
 * Validates the edit results structure
 *
 * @param {EditResults} results         The edit results to validate
 * @param {string[]}    availableBlocks The available blocks
 * @throws {Error} If the results are invalid
 */
const validateEditResults = (
	results: EditResults,
	availableBlocks: string[]
): void => {
	if (
		results.updates !== undefined &&
		results.updates !== null &&
		! Array.isArray( results.updates )
	) {
		throw new Error( 'Updates must be an array' );
	}

	if (
		results.inserts !== undefined &&
		results.inserts !== null &&
		! Array.isArray( results.inserts )
	) {
		throw new Error( 'Insertions must be an array' );
	}

	if (
		results.deletes !== undefined &&
		results.deletes !== null &&
		! Array.isArray( results.deletes )
	) {
		throw new Error( 'Deletions must be an array of clientIds' );
	}

	if (
		! results.updates &&
		! results.inserts &&
		! results.deletes &&
		! results.summary &&
		typeof results.customCSS !== 'string'
	) {
		throw new Error(
			'Response must contain updates, insertions, deletions, custom CSS, or a summary message'
		);
	}

	/**
	 * Recursively validates that all blocks have valid names
	 *
	 * @param {BlockData} block The block to validate
	 * @throws {Error} If the block name is invalid
	 */
	const validateBlockName = ( block: BlockData ): void => {
		if ( ! block.name && ! block.clientId ) {
			throw new Error( 'Block must have a name property' );
		}

		if ( ! availableBlocks.includes( block.name ) && ! block.clientId ) {
			throw new Error( `Block type "${ block.name }" is not available` );
		}

		// Recursively validate inner blocks
		if ( block.innerBlocks ) {
			for ( const innerBlock of block.innerBlocks ) {
				validateBlockName( innerBlock );
			}
		}
	};

	// filter out null entries from updates, inserts, and deletes
	// unsure why the model is returning null entries in the first place, check BSKY-950
	results.updates = results?.updates?.filter( Boolean ) || [];
	results.inserts = results?.inserts?.filter( Boolean ) || [];
	results.deletes = results?.deletes?.filter( Boolean ) || [];

	// Transform deletes from objects to strings if needed
	// Handles cases where the model returns deletes like this:
	// {
	// 	"deletes": [
	// 		{ "clientId": "block-123" }
	// 	]
	// }
	if ( results.deletes && Array.isArray( results.deletes ) ) {
		results.deletes = results.deletes
			.map( ( item ) =>
				typeof item === 'string' ? item : ( item as any )?.clientId
			)
			.filter( Boolean ) as string[];
	}

	// Validate updates
	if ( results.updates ) {
		for ( const update of results.updates ) {
			if ( ! update.clientId || ! update.name ) {
				throw new Error( 'Updates must contain clientId and name' );
			}
			validateBlockName( update );
		}
	}

	// Validate insertions
	if ( results.inserts ) {
		for ( const insert of results.inserts ) {
			if ( ! insert.block?.name ) {
				throw new Error(
					'Insertions must contain block data with a name'
				);
			}
			validateBlockName( insert.block );
		}
	}

	// Validate deletions
	if ( results.deletes ) {
		for ( const clientId of results.deletes ) {
			if ( typeof clientId !== 'string' ) {
				throw new Error( 'Each deletion must be a clientId string' );
			}
		}
	}
};

const flattenBlocksFromRootState = ( state: any ): Block[] => {
	const blocksByClientId = new Map< string, Block >();
	const addBlock = ( block: Block ) => {
		if ( block?.clientId && ! blocksByClientId.has( block.clientId ) ) {
			blocksByClientId.set( block.clientId, block );
		}

		block?.innerBlocks?.forEach( addBlock );
	};
	const sections = [
		state?.headerBlocks,
		state?.headerHeroBlocks,
		state?.footerBlocks,
		state?.contentBlocks,
	];

	sections.forEach( ( section ) => {
		if ( ! Array.isArray( section ) ) {
			return;
		}

		section.forEach( addBlock );
	} );

	return Array.from( blocksByClientId.values() );
};

const MAX_VALIDATION_DETAIL_ITEMS = 10;
const MAX_VALIDATION_DETAIL_STRING_LENGTH = 300;

interface CapturedValidationTarget {
	resolvedClientId?: string;
	beforeBlock?: Block;
}

const truncateValidationString = ( value: string ) =>
	value.length > MAX_VALIDATION_DETAIL_STRING_LENGTH
		? `${ value.slice( 0, MAX_VALIDATION_DETAIL_STRING_LENGTH ) }…`
		: value;

const normalizeValidationValue = ( value: unknown ): unknown => {
	if ( value === undefined ) {
		return null;
	}

	if ( typeof value === 'string' ) {
		return truncateValidationString( value );
	}

	return value;
};

const getNestedValue = ( source: any, path: string[] ): unknown =>
	path.reduce(
		( value, key ) =>
			value && typeof value === 'object' ? value[ key ] : undefined,
		source
	);

const collectAttributePaths = (
	attributes: unknown,
	path: string[] = []
): Array< { path: string[]; requested: unknown } > => {
	if (
		attributes &&
		typeof attributes === 'object' &&
		! Array.isArray( attributes )
	) {
		return Object.entries( attributes ).flatMap( ( [ key, value ] ) =>
			collectAttributePaths( value, [ ...path, key ] )
		);
	}

	return [ { path, requested: attributes } ];
};

const normalizeValidationValueForComparison = ( value: unknown ): unknown =>
	value === undefined ? null : value;

const validationValuesEqual = ( valueA: unknown, valueB: unknown ) =>
	JSON.stringify( normalizeValidationValueForComparison( valueA ) ) ===
	JSON.stringify( normalizeValidationValueForComparison( valueB ) );

/**
 * Compares two block states and returns the differences
 *
 * @param {Block[]} lastState    The previous state of blocks
 * @param {Block[]} currentState The current state of blocks
 * @return {BlockStateComparison} Object containing detailed differences
 */
const compareBlockStates = (
	lastState: any,
	currentState: any
): BlockStateComparison => {
	// Helper function to find differences between two objects
	const findDifferences = (
		obj1: any,
		obj2: any,
		path = ''
	): Record< string, BlockDifference | Record< string, unknown > > => {
		const differences: Record<
			string,
			BlockDifference | Record< string, unknown >
		> = {};

		// Get all unique keys from both objects
		const allKeys = new Set( [
			...Object.keys( obj1 ),
			...Object.keys( obj2 ),
		] );

		for ( const key of Array.from( allKeys ) ) {
			const currentPath = path ? `${ path }.${ key }` : key;

			// If key exists in both objects
			if ( key in obj1 && key in obj2 ) {
				// If both values are objects (and not null), recursively compare them
				if (
					typeof obj1[ key ] === 'object' &&
					obj1[ key ] !== null &&
					typeof obj2[ key ] === 'object' &&
					obj2[ key ] !== null
				) {
					const nestedDifferences = findDifferences(
						obj1[ key ],
						obj2[ key ],
						currentPath
					);
					if ( Object.keys( nestedDifferences ).length > 0 ) {
						differences[ key ] = nestedDifferences;
					}
				}
				// If values are different, store both values
				else if (
					JSON.stringify( obj1[ key ] ) !==
					JSON.stringify( obj2[ key ] )
				) {
					differences[ key ] = {
						from: obj1[ key ],
						to: obj2[ key ],
					};
				}
			}
			// If key only exists in first object
			else if ( key in obj1 ) {
				differences[ key ] = {
					from: obj1[ key ],
					to: undefined,
				};
			}
			// If key only exists in second object
			else if ( key in obj2 ) {
				differences[ key ] = {
					from: undefined,
					to: obj2[ key ],
				};
			}
		}

		return differences;
	};

	const lastBlocks = flattenBlocksFromRootState( lastState );
	const currentBlocks = flattenBlocksFromRootState( currentState );

	// Find added and removed blocks
	const added = currentBlocks.filter(
		( block ) =>
			! lastBlocks.some(
				( lastBlock ) => lastBlock.clientId === block.clientId
			)
	);

	const removed = lastBlocks.filter(
		( block ) =>
			! currentBlocks.some(
				( currentBlock ) => currentBlock.clientId === block.clientId
			)
	);

	// Find modified blocks and their specific changes
	const modified: ModifiedBlock[] = [];
	currentBlocks.forEach( ( currentBlock ) => {
		const lastBlock = lastBlocks.find(
			( block ) => block.clientId === currentBlock.clientId
		);

		if ( lastBlock ) {
			const differences = findDifferences( lastBlock, currentBlock );
			if ( Object.keys( differences ).length > 0 ) {
				modified.push( {
					clientId: currentBlock.clientId,
					name: currentBlock.name,
					changes: differences,
				} );
			}
		}
	} );

	const summarizeBlock = ( block: Block ) => ( {
		clientId: block.clientId,
		name: block.name,
		attributes: block.attributes,
		innerBlocks: block.innerBlocks?.length || 0,
	} );

	const dedupeByClientId = < T extends { clientId: string } >(
		items: T[]
	): T[] =>
		Array.from(
			new Map( items.map( ( item ) => [ item.clientId, item ] ) ).values()
		);

	return {
		added: dedupeByClientId( added.map( summarizeBlock ) ),
		removed: dedupeByClientId( removed.map( summarizeBlock ) ),
		modified: dedupeByClientId( modified ),
	};
};

const getAppliedOperations = (
	differences: BlockStateComparison,
	lastState: RootBlocksState | undefined,
	currentState: RootBlocksState | undefined
) => {
	const addedCount = differences.added.length;
	const removedCount = differences.removed.length;
	let modifiedCount = differences.modified.length;

	if (
		lastState &&
		currentState &&
		addedCount === 0 &&
		removedCount === 0 &&
		modifiedCount === 0
	) {
		// Root sibling order is not part of the individual block objects compared above.
		// Supply a non-zero floor only when no other applied operation was counted.
		const getClientIds = ( blocks: Block[] | undefined ) =>
			Array.isArray( blocks )
				? blocks.map( ( block ) => block.clientId )
				: [];
		const hasRootOrderChange = ROOT_BLOCK_STATE_KEYS.some( ( key ) => {
			const lastClientIds = getClientIds( lastState[ key ] );
			const currentClientIds = getClientIds( currentState[ key ] );

			return (
				lastClientIds.length !== currentClientIds.length ||
				lastClientIds.some(
					( clientId, index ) =>
						clientId !== currentClientIds[ index ]
				)
			);
		} );

		if ( hasRootOrderChange ) {
			modifiedCount = 1;
		}
	}

	return { addedCount, removedCount, modifiedCount };
};

const getUnresolvedTargets = (
	editResults: EditResults,
	capturedTargets: Map< string, CapturedValidationTarget >,
	recoveredTargetIds: Set< string >
): ValidationDetailItem[] => {
	const unresolved: ValidationDetailItem[] = [];
	const checkTarget = ( requestedClientId: string, operation: string ) => {
		// An unmapped-parent reorder recovery applied this update target even
		// though it never mapped, so reporting it as unresolved would
		// contradict the success result and invite a pointless retry. Deletes
		// of the same id are not recovered and keep their entry.
		if (
			operation === 'update' &&
			recoveredTargetIds.has( requestedClientId )
		) {
			return;
		}
		const target = capturedTargets.get( requestedClientId );
		const resolvedClientId = target?.resolvedClientId;
		if ( ! resolvedClientId ) {
			unresolved.push( {
				operation,
				requestedClientId,
				reason: 'not-mapped',
			} );
			return;
		}

		if ( ! target?.beforeBlock ) {
			unresolved.push( {
				operation,
				requestedClientId,
				resolvedClientId,
				reason: 'not-found',
			} );
		}
	};

	editResults.updates
		?.slice( 0, MAX_VALIDATION_DETAIL_ITEMS )
		.forEach( ( update ) => checkTarget( update.clientId, 'update' ) );
	editResults.deletes
		?.slice( 0, MAX_VALIDATION_DETAIL_ITEMS )
		.forEach( ( clientId ) => checkTarget( clientId, 'delete' ) );

	return unresolved.slice( 0, MAX_VALIDATION_DETAIL_ITEMS );
};

const getDeleteStatus = (
	resolvedClientId: string | undefined,
	afterBlock: Block | undefined
) => {
	if ( ! resolvedClientId ) {
		return 'unresolved';
	}

	return afterBlock ? 'still-present' : 'removed';
};

const getDeleteResults = (
	editResults: EditResults,
	reverseMap: ClientIdMap,
	previousBlockByClientId: Map< string, Block >,
	currentBlockByClientId: Map< string, Block >
): ValidationDetailItem[] =>
	( editResults.deletes || [] )
		.slice( 0, MAX_VALIDATION_DETAIL_ITEMS )
		.map( ( requestedClientId ) => {
			const resolvedClientId = reverseMap[ requestedClientId ];
			const beforeBlock = resolvedClientId
				? previousBlockByClientId.get( resolvedClientId )
				: undefined;
			const afterBlock = resolvedClientId
				? currentBlockByClientId.get( resolvedClientId )
				: undefined;

			return {
				requestedClientId,
				resolvedClientId,
				blockName: beforeBlock?.name || afterBlock?.name,
				status: getDeleteStatus( resolvedClientId, afterBlock ),
			};
		} );

const getAttributeStatus = ( {
	resolvedClientId,
	afterBlock,
	requestedSatisfied,
	before,
	after,
}: {
	resolvedClientId: string | undefined;
	afterBlock: Block | undefined;
	requestedSatisfied: boolean;
	before: unknown;
	after: unknown;
} ) => {
	if ( ! resolvedClientId ) {
		return 'unresolved';
	}

	if ( ! afterBlock ) {
		return 'missing-after-apply';
	}

	if ( ! requestedSatisfied ) {
		return validationValuesEqual( before, after )
			? 'unchanged'
			: 'mismatch';
	}

	return validationValuesEqual( before, after )
		? 'already-satisfied'
		: 'changed';
};

const getAttributeResults = (
	editResults: EditResults,
	reverseMap: ClientIdMap,
	previousBlockByClientId: Map< string, Block >,
	currentBlockByClientId: Map< string, Block >
): ValidationDetailItem[] => {
	const results: ValidationDetailItem[] = [];

	editResults.updates?.forEach( ( update ) => {
		const resolvedClientId = reverseMap[ update.clientId ];
		const beforeBlock = resolvedClientId
			? previousBlockByClientId.get( resolvedClientId )
			: undefined;
		const afterBlock = resolvedClientId
			? currentBlockByClientId.get( resolvedClientId )
			: undefined;

		collectAttributePaths( update.attributes || {} ).forEach(
			( attributeResult ) => {
				if ( results.length >= MAX_VALIDATION_DETAIL_ITEMS ) {
					return;
				}

				const before = getNestedValue(
					beforeBlock?.attributes || {},
					attributeResult.path
				);
				const after = getNestedValue(
					afterBlock?.attributes || {},
					attributeResult.path
				);
				const requested = attributeResult.requested;
				const requestedSatisfied = validationValuesEqual(
					requested,
					after
				);

				results.push( {
					blockName: update.name,
					requestedClientId: update.clientId,
					resolvedClientId,
					path: attributeResult.path.join( '.' ),
					requested: normalizeValidationValue( requested ),
					before: normalizeValidationValue( before ),
					after: normalizeValidationValue( after ),
					status: getAttributeStatus( {
						resolvedClientId,
						afterBlock,
						requestedSatisfied,
						before,
						after,
					} ),
				} );
			}
		);
	} );

	return results;
};

const getUnsupportedAttributes = (
	editResults: EditResults,
	blockTypes: BlockType[] | undefined
): ValidationDetailItem[] => {
	const blockTypeByName = new Map(
		( blockTypes || [] ).map( ( blockType ) => [
			blockType.name,
			blockType,
		] )
	);
	const unsupported: ValidationDetailItem[] = [];

	editResults.updates?.forEach( ( update ) => {
		const blockType = blockTypeByName.get( update.name );
		const schemaAttributes = ( blockType as any )?.attributes;
		if ( ! schemaAttributes || ! update.attributes ) {
			return;
		}

		Object.keys( update.attributes ).forEach( ( attribute ) => {
			if (
				unsupported.length < MAX_VALIDATION_DETAIL_ITEMS &&
				! Object.prototype.hasOwnProperty.call(
					schemaAttributes,
					attribute
				)
			) {
				unsupported.push( {
					blockName: update.name,
					requestedClientId: update.clientId,
					path: attribute,
					reason: 'not-registered-attribute',
				} );
			}
		} );
	} );

	return unsupported;
};

const getContentTextSnapshot = (
	editResults: EditResults,
	currentBlockByClientId: Map< string, Block >
): string | undefined => {
	const hasContentEdit = editResults.updates?.some(
		( update ) => update.attributes?.content !== undefined
	);
	const hasInsert = Boolean( editResults.inserts?.length );
	if ( ! hasContentEdit && ! hasInsert ) {
		return undefined;
	}

	const text = Array.from( currentBlockByClientId.values() )
		.map( ( block ) => block.attributes?.content )
		.filter( ( content ): content is string => typeof content === 'string' )
		.join( ' ' )
		.replace( /<[^>]*>/g, ' ' )
		.replace( /\s+/g, ' ' )
		.trim();

	return text ? truncateValidationString( text ) : undefined;
};

/**
 * The editor clientIds this apply targeted, as a crop hint for a canvas capture.
 *
 * Updates only. A delete leaves nothing to photograph, and an insert has no
 * requested clientId to resolve — the id it lands on is only known after the
 * insert runs, which this does not have access to. An empty list is a normal
 * result and means "capture the viewport".
 *
 * `updates` is unvalidated caller input here: the capture runs after the edit
 * action on every path, including the one that rejects a non-array `updates`.
 *
 * @param {EditResults} editResults The requested edits.
 * @param {ClientIdMap} reverseMap  Mapping of compressed to original IDs.
 * @return {string[]} The resolved clientIds.
 */
const getEditedClientIds = (
	editResults: Pick< EditResults, 'updates' >,
	reverseMap: ClientIdMap
): string[] =>
	Array.from(
		new Set(
			( Array.isArray( editResults.updates ) ? editResults.updates : [] )
				.map( ( update ) => reverseMap[ update.clientId ] )
				.filter( Boolean )
		)
	);

/**
 * Hook that provides block editing functionality.
 */
export default function useApplyBlockEditsTool(): {
	applyBlockEdits: ( args: ApplyBlockEditsArgs ) => Promise< {
		result: ApplyBlockEditsResultData;
		returnToAgent: boolean;
		agentMessage?: string;
		__file_parts?: FilePart[];
	} >;
} {
	// Get clientIdMap from store (instead of it being injected via args)
	const clientIdMap = useSelect(
		( select ) =>
			select( aiStore ).getFullPageStructure()?.clientIdMap || {},
		[]
	) as ClientIdMap;

	// Get available blocks
	const blockTypes = useSelect(
		( select ) => ( select( blocksStore ) as any ).getBlockTypes(),
		[]
	) as BlockType[] | undefined;

	const availableBlocks = useMemo(
		() =>
			Array.isArray( blockTypes )
				? blockTypes.map( ( block ) => block.name )
				: [],
		[ blockTypes ]
	);

	const {
		getBlock,
		getBlocks,
		getBlockParents,
		getBlockRootClientId,
		getGlobalStylesId,
		getEditedEntityRecord,
	} = useSelect(
		( select ) => ( {
			getBlock: ( select( blockEditorStore ) as any ).getBlock,
			getBlocks: ( select( blockEditorStore ) as any ).getBlocks,
			getBlockParents: ( select( blockEditorStore ) as any )
				.getBlockParents,
			getBlockRootClientId: ( select( blockEditorStore ) as any )
				.getBlockRootClientId,
			getGlobalStylesId: () =>
				(
					select( coreStore ) as any
				 ).__experimentalGetCurrentGlobalStylesId(),
			getEditedEntityRecord: ( select( coreStore ) as any )
				.getEditedEntityRecord,
		} ),
		[]
	) as {
		getBlock: ( clientId: string ) => Block | null;
		getBlocks: ( rootClientId?: string | null ) => Block[];
		getBlockParents: ( clientId: string ) => string[];
		getBlockRootClientId: ( clientId: string ) => string | undefined;
		getGlobalStylesId: () => string;
		getEditedEntityRecord: (
			kind: string,
			name: string,
			recordId: string
		) => any;
	};

	const {
		setBlockIsProcessing,
		getRootBlocksState,
		getSectionRootClientId,
		resetAllBlockIsProcessing,
	} = useBlocks();
	const { deleteMarkedMessages, addAssistantMessage, addCachedImage } =
		useDispatch( aiStore ) as {
			deleteMarkedMessages: () => void;
			assistantSay: (
				message: string
			) => Promise< { message: { id: string } } >;
			addAssistantMessage: ( assistant: string, message: string ) => void;
			changeCheckpointId: ( oldId: string, newId: string ) => void;
			addCachedImage: ( args: {
				cacheKey: string;
				imageData: CachedImage;
			} ) => void;
		};

	const {
		replaceBlock,
		replaceInnerBlocks,
		insertBlock,
		removeBlock,
		updateBlockAttributes,
	} = useDispatch( blockEditorStore );
	const { editEntityRecord } = useDispatch( coreStore );
	const {
		getLastEditorState,
		setCheckpoint,
		removeCheckpointKeys,
		hasCheckpoint,
		clearCheckpoint,
		sealCheckpointForSwap,
	} = useCheckpoint();

	const aiPromises: Promise< void >[] = [];

	const isNavigationBlockEdit = (
		editResults: EditResults,
		reverseMap: ClientIdMap
	): boolean => {
		const isNavigationBlock = ( block?: Block | BlockData | null ) =>
			block?.name === 'core/navigation' ||
			block?.name === 'core/navigation-link';
		const resolveClientId = ( clientId?: string ) =>
			clientId ? reverseMap[ clientId ] || clientId : undefined;
		const hasNavigationAncestor = ( clientId?: string ) => {
			const originalClientId = resolveClientId( clientId );

			if ( ! originalClientId ) {
				return false;
			}

			const block = getBlock( originalClientId );
			if ( isNavigationBlock( block ) ) {
				return true;
			}

			return ( getBlockParents( originalClientId ) || [] ).some(
				( parentClientId ) =>
					isNavigationBlock( getBlock( parentClientId ) )
			);
		};

		return Boolean(
			editResults.updates?.some(
				( update ) =>
					isNavigationBlock( update ) ||
					hasNavigationAncestor( update.clientId )
			) ||
				editResults.inserts?.some(
					( insert ) =>
						isNavigationBlock( insert.block ) ||
						hasNavigationAncestor( insert.parentClientId )
				) ||
				editResults.deletes?.some( hasNavigationAncestor )
		);
	};

	const isRecord = ( value: unknown ): value is Record< string, unknown > =>
		typeof value === 'object' && value !== null && ! Array.isArray( value );

	const requestedValueAlreadyMatches = (
		currentValue: unknown,
		requestedValue: unknown
	): boolean => {
		if ( requestedValue === undefined ) {
			return true;
		}

		// In block edits, `null` is a delete signal. If the current value is
		// already absent/null, the requested final state is already satisfied.
		if ( requestedValue === null ) {
			return currentValue === undefined || currentValue === null;
		}

		if ( Array.isArray( requestedValue ) ) {
			return (
				JSON.stringify( currentValue ) ===
				JSON.stringify( requestedValue )
			);
		}

		if ( isRecord( requestedValue ) ) {
			if ( ! isRecord( currentValue ) ) {
				return false;
			}

			return Object.entries( requestedValue ).every( ( [ key, value ] ) =>
				requestedValueAlreadyMatches( currentValue[ key ], value )
			);
		}

		return (
			JSON.stringify( currentValue ) === JSON.stringify( requestedValue )
		);
	};

	const requestedInnerBlocksAlreadyMatch = (
		currentInnerBlocks: Block[] | undefined,
		requestedInnerBlocks: BlockData[],
		reverseMap: ClientIdMap
	): boolean => {
		// An empty list is a preserve-children placeholder, as in applyEdits.
		if ( requestedInnerBlocks.length === 0 ) {
			return true;
		}

		if ( ! Array.isArray( currentInnerBlocks ) ) {
			return false;
		}

		if ( currentInnerBlocks.length !== requestedInnerBlocks.length ) {
			return false;
		}

		return requestedInnerBlocks.every( ( requestedBlock, index ) => {
			const currentBlock = currentInnerBlocks[ index ];
			const requestedClientId = requestedBlock.clientId
				? reverseMap[ requestedBlock.clientId ] ||
				  requestedBlock.clientId
				: undefined;

			if (
				requestedClientId &&
				currentBlock.clientId !== requestedClientId
			) {
				return false;
			}

			if (
				requestedBlock.name &&
				currentBlock.name !== requestedBlock.name
			) {
				return false;
			}

			if (
				isRecord( requestedBlock.attributes ) &&
				! requestedValueAlreadyMatches(
					currentBlock.attributes || {},
					requestedBlock.attributes
				)
			) {
				return false;
			}

			if ( Array.isArray( requestedBlock.innerBlocks ) ) {
				return requestedInnerBlocksAlreadyMatch(
					getBlocks( currentBlock.clientId ),
					requestedBlock.innerBlocks,
					reverseMap
				);
			}

			return true;
		} );
	};

	const areUpdateEditsAlreadySatisfied = (
		editResults: EditResults,
		reverseMap: ClientIdMap
	): boolean => {
		if (
			! editResults.updates?.length ||
			editResults.inserts?.length ||
			editResults.deletes?.length
		) {
			return false;
		}

		return editResults.updates.every( ( update ) => {
			const originalClientId = reverseMap[ update.clientId ];
			const targetBlock = originalClientId
				? getBlock( originalClientId )
				: null;

			if ( ! targetBlock ) {
				return false;
			}

			if ( update.name && targetBlock.name !== update.name ) {
				return false;
			}

			if (
				isRecord( update.attributes ) &&
				! requestedValueAlreadyMatches(
					targetBlock.attributes || {},
					update.attributes
				)
			) {
				return false;
			}

			if ( Array.isArray( update.innerBlocks ) ) {
				return requestedInnerBlocksAlreadyMatch(
					getBlocks( originalClientId ),
					update.innerBlocks,
					reverseMap
				);
			}

			return true;
		} );
	};

	/**
	 * Deep merge utility that recursively merges objects while preserving nested properties
	 *
	 * @param {any} target The target object to merge into
	 * @param {any} source The source object to merge from
	 * @return {any} The deeply merged result
	 */
	const deepMerge = ( target: any, source: any ): any => {
		// Handle undefined case - keep target
		if ( source === undefined ) {
			return target;
		}
		// Handle null case - explicitly set to null (don't preserve target)
		if ( source === null ) {
			return null;
		}
		if ( target === null || target === undefined ) {
			return source;
		}

		// If source is not an object, replace target entirely
		if ( typeof source !== 'object' || Array.isArray( source ) ) {
			return source;
		}

		// If target is not an object, replace with source
		if ( typeof target !== 'object' || Array.isArray( target ) ) {
			return source;
		}

		// Both are objects - merge recursively
		const result = { ...target };

		for ( const key in source ) {
			if ( source.hasOwnProperty( key ) ) {
				const mergedValue = deepMerge( target[ key ], source[ key ] );
				// Only include the property if the merged value is not null
				if ( mergedValue !== null ) {
					result[ key ] = mergedValue;
				} else {
					// Remove the property entirely if the merged value is null
					delete result[ key ];
				}
			}
		}

		return result;
	};

	const deepMergeForAttributeUpdate = ( target: any, source: any ): any => {
		if ( source === undefined ) {
			return target;
		}

		// For updateBlockAttributes, omitted keys are preserved by Gutenberg.
		// Use undefined as the explicit unset value for null delete signals.
		if ( source === null ) {
			return undefined;
		}

		if ( target === null || target === undefined ) {
			return source;
		}

		if ( typeof source !== 'object' || Array.isArray( source ) ) {
			return source;
		}

		if ( typeof target !== 'object' || Array.isArray( target ) ) {
			return source;
		}

		const result = { ...target };
		for ( const key in source ) {
			if ( source.hasOwnProperty( key ) ) {
				result[ key ] = deepMergeForAttributeUpdate(
					target[ key ],
					source[ key ]
				);
			}
		}

		return result;
	};

	const getAttributesForUpdateBlockAttributes = (
		originalAttributes: BlockAttributes | undefined,
		requestedAttributes: BlockAttributes | undefined
	) => {
		if (
			Array.isArray( requestedAttributes ) ||
			( isRecord( requestedAttributes ) &&
				Object.keys( requestedAttributes ).length === 0 )
		) {
			return originalAttributes || {};
		}

		return deepMergeForAttributeUpdate(
			originalAttributes || {},
			requestedAttributes || {}
		);
	};

	/**
	 * Recursively merges block data, preserving existing properties that are not overridden by new data
	 *
	 * @param {Block}       originalBlock The original block to preserve properties from
	 * @param {BlockData}   newBlockData  The new block data to apply
	 * @param {ClientIdMap} reverseMap    Mapping of compressed to original IDs
	 * @return {BlockData} Merged block data with preserved properties
	 */
	const mergeBlocksRecursively = (
		originalBlock: Block | null,
		newBlockData: BlockData,
		reverseMap: ClientIdMap
	): BlockData => {
		// If there's no original block, just use the new data
		if ( ! originalBlock ) {
			return newBlockData;
		}

		// Guard against empty arrays or objects in attributes
		// If newBlockData.attributes is [] or {}, preserve original attributes
		const shouldPreserveAttributes =
			Array.isArray( newBlockData.attributes ) ||
			( typeof newBlockData.attributes === 'object' &&
				newBlockData.attributes !== null &&
				Object.keys( newBlockData.attributes ).length === 0 );

		// Start with a merged block that preserves all properties
		const mergedBlock: BlockData = {
			...originalBlock,
			...newBlockData,
			// Deep merge attributes to preserve nested properties
			// If attributes are empty array/object, keep original attributes
			attributes: shouldPreserveAttributes
				? originalBlock.attributes || {}
				: deepMerge(
						originalBlock.attributes || {},
						newBlockData.attributes || {}
				  ),
		};

		// Cache image for image and cover blocks
		const imageBlocks = [
			{ name: 'core/image', cacheKey: imageCacheKeys.IMAGES },
			{ name: 'core/cover', cacheKey: imageCacheKeys.BACKGROUND_IMAGES },
		];
		for ( const { name, cacheKey } of imageBlocks ) {
			if ( mergedBlock.name === name && mergedBlock.attributes?.url ) {
				addCachedImage( {
					cacheKey,
					imageData: {
						url: mergedBlock.attributes.url,
						id: mergedBlock.attributes.id,
						alt: mergedBlock.attributes.alt,
					},
				} );
			}
		}

		// Empty lists preserve children, just like omitted innerBlocks and
		// attribute-only updates in applyEdits, including at nested levels.
		if ( newBlockData.innerBlocks?.length ) {
			mergedBlock.innerBlocks = newBlockData.innerBlocks.map(
				( newInnerBlock ) => {
					const originalClientId = newInnerBlock.clientId
						? reverseMap[ newInnerBlock.clientId ]
						: undefined;
					// Find the corresponding original inner block by clientId
					const originalInnerBlock = originalBlock.innerBlocks?.find(
						( block ) => block.clientId === originalClientId
					);

					// Recursively merge this inner block
					return mergeBlocksRecursively(
						originalInnerBlock || null,
						newInnerBlock,
						reverseMap
					);
				}
			);
		} else {
			// If no new inner blocks specified, preserve the original ones
			mergedBlock.innerBlocks = originalBlock.innerBlocks || [];
		}

		return mergedBlock;
	};

	/**
	 * Creates a block and its inner blocks recursively
	 *
	 * @param {BlockData} blockData Block data including name, attributes, and innerBlocks
	 * @return {Promise<any>} A valid block with all inner blocks properly created
	 */
	const createBlockRecursively = async (
		blockData: BlockData
	): Promise< any > => {
		// Create inner blocks first if they exist
		const processedInnerBlocks = blockData.innerBlocks?.length
			? await Promise.all(
					blockData.innerBlocks.map( createBlockRecursively )
			  )
			: [];

		return createBlock(
			blockData.name,
			blockData.attributes || {},
			processedInnerBlocks
		);
	};

	/**
	 * Reads a block's current children from the store.
	 *
	 * Always use this instead of `getBlock( clientId ).innerBlocks` when
	 * rebuilding a child list. Blocks that control their own inner blocks —
	 * `core/post-content` and `core/template-part` — keep their children in a
	 * separate `controlled||<clientId>` entry of the block tree, and their own
	 * tree node is left with an empty `innerBlocks` array for good. `getBlocks`
	 * is the selector that resolves that indirection (BSKY-1992).
	 *
	 * @param {string|null|undefined} clientId The parent clientId
	 * @return {Block[]} The parent's children, empty when unavailable
	 */
	const getChildBlocks = ( clientId: string | null | undefined ): Block[] => {
		if ( ! clientId ) {
			return [];
		}

		return getBlocks( clientId ) || [];
	};

	/**
	 * Deletes blocks based on their clientIds
	 *
	 * @param {string[]}    clientIds  Array of compressed clientIds to delete
	 * @param {ClientIdMap} reverseMap Mapping of compressed to original IDs
	 */
	const deleteBlocks = async (
		clientIds: string[],
		reverseMap: ClientIdMap
	): Promise< void > => {
		if ( ! clientIds?.length ) {
			return;
		}

		for ( const clientId of clientIds ) {
			const originalClientId = reverseMap[ clientId ];

			if ( ! originalClientId ) {
				console.error(
					`[Edit Blockd] Could not map compressed clientId for deletion: ${ clientId }`
				);
				continue;
			}

			const targetBlock = getBlock( originalClientId );

			if ( ! targetBlock ) {
				console.error(
					`[Edit Blocks] Block not found for deletion with clientId: ${ originalClientId }`
				);
				continue;
			}

			// Delete the block
			removeBlock( originalClientId );
			await setDelay( 0 );

			// Restricted pattern/content-only block lists can reject
			// `removeBlock` as a silent no-op. If the block still exists,
			// remove it by replacing the immediate parent's children without
			// the target block.
			if ( getBlock( originalClientId ) ) {
				const parentClientId = getBlockRootClientId( originalClientId );
				const siblings = getChildBlocks( parentClientId );
				const remainingSiblings = siblings.filter(
					( block ) => block.clientId !== originalClientId
				);

				if ( ! parentClientId || ! siblings.length ) {
					// Without a readable parent block list there is nothing safe
					// to rebuild from: replacing children with a list built from
					// an empty read would delete the target's siblings too.
					log.error(
						'[Edit Blocks] Skipping delete fallback: could not read the parent block list',
						{ clientId: originalClientId, parentClientId }
					);
				} else if ( remainingSiblings.length !== siblings.length ) {
					replaceInnerBlocks( parentClientId, remainingSiblings );
					await setDelay( 0 );
				}
			}
		}
	};

	/**
	 * Recursively clears processing state for blocks
	 *
	 * @param {Block[]} blocks The blocks to clear processing state for
	 */
	// eslint-disable-next-line @typescript-eslint/no-unused-vars
	const clearProcessingBlocks = ( blocks: Block[] ): void => {
		blocks.forEach( ( block ) => {
			// Check if this block is in processing state
			if (
				block.attributes?.className?.includes(
					'big-sky__is-processing'
				)
			) {
				setBlockIsProcessing( block, false );
			}

			// Recursively check inner blocks
			if ( block.innerBlocks?.length && block.innerBlocks.length > 0 ) {
				clearProcessingBlocks( block.innerBlocks );
			}
		} );
	};

	/**
	 * Updates cover block overlay color based on background image
	 *
	 * @param {string} clientId - The block client ID
	 * @param {string} url      - The image URL
	 */
	const updateCoverBlockOverlay = async (
		clientId: string,
		url: string | undefined
	) => {
		if ( url ) {
			try {
				const mediaColor = await getMediaColor( url );
				updateBlockAttributes( clientId, {
					overlayColor: undefined,
					customOverlayColor: mediaColor,
					isUserOverlayColor: false,
				} );
			} catch ( error: any ) {
				log.error( 'Error updating cover block overlay color:', error );
			}
		}
	};

	/**
	 * Reorders the block list containing an update's children when the update's
	 * parent clientId cannot be mapped. The block-editing agent addresses
	 * top-level reorders to a "core/post-content" parent, but the post editor
	 * has no such block — content blocks are the tree roots — so that parent
	 * resolves to nothing. The listed children must share one parent list,
	 * cover it completely (replaceInnerBlocks drops any block left out), and
	 * not repeat a child (a repeat would insert one block twice under a single
	 * clientId). Attributes on the unmappable parent are deliberately dropped:
	 * there is no real block to carry them, so only the reorder applies.
	 *
	 * @param {BlockUpdate} update     The update whose parent could not be mapped
	 * @param {ClientIdMap} reverseMap Mapping of compressed to original IDs
	 * @return {boolean} True when the reorder was applied, false to keep the
	 *                   caller's normal unmapped-clientId error.
	 */
	const applyReorderForUnmappedParent = (
		update: BlockUpdate,
		reverseMap: ClientIdMap
	): boolean => {
		const innerBlockUpdates = update.innerBlocks || [];
		if ( ! innerBlockUpdates.length ) {
			return false;
		}

		const reorderedBlocks: Block[] = [];
		for ( const innerBlock of innerBlockUpdates ) {
			const innerClientId = innerBlock.clientId
				? reverseMap[ innerBlock.clientId ]
				: undefined;
			const existingBlock = innerClientId
				? getBlock( innerClientId )
				: null;
			if ( ! existingBlock ) {
				return false;
			}
			reorderedBlocks.push( existingBlock );
		}

		const listClientIds = new Set(
			reorderedBlocks.map(
				( block ) => getBlockRootClientId( block.clientId ) ?? ''
			)
		);
		if ( listClientIds.size !== 1 ) {
			return false;
		}
		const [ listClientId ] = listClientIds;

		// The root list id is '', so getChildBlocks (which returns [] for a
		// falsy id) cannot be used here.
		const currentList = getBlocks( listClientId );
		const reorderedIds = new Set(
			reorderedBlocks.map( ( block ) => block.clientId )
		);
		if (
			reorderedBlocks.length !== reorderedIds.size ||
			currentList.length !== reorderedIds.size ||
			! currentList.every( ( block ) =>
				reorderedIds.has( block.clientId )
			)
		) {
			return false;
		}

		replaceInnerBlocks( listClientId, reorderedBlocks );
		return true;
	};

	/**
	 * Plans reorders throughout a requested subtree, independent of block type
	 * or nesting depth. Move existing blocks rather than replacing their parent:
	 * `replaceBlock` is rejected for structural blocks in content-only editing.
	 *
	 * The complete-list check matters because `replaceInnerBlocks` removes any
	 * current child omitted from the replacement. Validate the whole subtree
	 * before dispatching anything. Changes other than ordering return null so
	 * the normal update path can apply them instead of silently discarding them.
	 *
	 * @param {Block}       currentBlock The existing subtree root.
	 * @param {BlockData}   requested    The requested subtree, including references.
	 * @param {ClientIdMap} reverseMap   Mapping of compressed to original IDs.
	 * @return {Object[]|null} Child orders, deepest first, or null for other edits.
	 */
	const getReorderOperations = (
		currentBlock: Block,
		requested: BlockData,
		reverseMap: ClientIdMap
	): Array< { parentClientId: string; childClientIds: string[] } > | null => {
		if (
			( requested.name && requested.name !== currentBlock.name ) ||
			// Like mergeBlocksRecursively, empty arrays and null attributes
			// mean preserve the existing attributes, not replace them.
			( isRecord( requested.attributes ) &&
				! requestedValueAlreadyMatches(
					currentBlock.attributes || {},
					requested.attributes
				) )
		) {
			return null;
		}

		if (
			! Array.isArray( requested.innerBlocks ) ||
			requested.innerBlocks.length === 0
		) {
			return [];
		}

		const currentChildren = getChildBlocks( currentBlock.clientId );
		if ( currentChildren.length !== requested.innerBlocks.length ) {
			return null;
		}
		const currentChildrenById = new Map(
			currentChildren.map( ( block ) => [ block.clientId, block ] )
		);
		const requestedIds = new Set< string >();
		const operations: Array< {
			parentClientId: string;
			childClientIds: string[];
		} > = [];

		for ( const requestedChild of requested.innerBlocks ) {
			if ( ! requestedChild.clientId ) {
				return null;
			}

			const resolvedClientId =
				reverseMap[ requestedChild.clientId ] ||
				requestedChild.clientId;
			const existingChild = currentChildrenById.get( resolvedClientId );

			if ( ! existingChild || requestedIds.has( resolvedClientId ) ) {
				return null;
			}

			const childOperations = getReorderOperations(
				existingChild,
				requestedChild,
				reverseMap
			);
			if ( childOperations === null ) {
				return null;
			}
			operations.push( ...childOperations );
			requestedIds.add( resolvedClientId );
		}

		const childClientIds = [ ...requestedIds ];
		if (
			currentChildren.some(
				( child, index ) => child.clientId !== childClientIds[ index ]
			)
		) {
			operations.push( {
				parentClientId: currentBlock.clientId,
				childClientIds,
			} );
		}
		return operations;
	};

	/**
	 * Applies the edit results to the block
	 *
	 * @param {EditResults} editResults The edit results to apply
	 * @param {ClientIdMap} reverseMap  Mapping of compressed to original IDs
	 * @return {Promise<Set<string>>} Requested clientIds that were applied via
	 *                                the unmapped-parent reorder recovery, so
	 *                                they are not reported as unresolved.
	 */
	const applyEdits = async (
		editResults: EditResults,
		reverseMap: ClientIdMap
	): Promise< Set< string > > => {
		const recoveredTargetIds = new Set< string >();
		// Handle insertions first to avoid clientId conflicts
		// If we do updates first, clientIds of blocks change and inserts may fail
		if ( editResults.inserts?.length ) {
			for ( const insert of editResults.inserts ) {
				const { parentClientId, index = 0, block } = insert;
				// If no parentClientId is provided, use the section root (e.g., core/post-content)
				// If getSectionRootClientId() returns null (empty post), insertBlock will insert at root level
				const originalParentClientId = parentClientId
					? reverseMap[ parentClientId ]
					: getSectionRootClientId();

				// Only throw if a specific parentClientId was provided but couldn't be mapped
				if ( parentClientId && ! originalParentClientId ) {
					throw new Error(
						`[Edit Pattern] Could not map compressed parent clientId: ${ parentClientId }`
					);
				}

				// Verify parent block exists (only if we have a parent)
				if ( originalParentClientId ) {
					const parentBlock = getBlock( originalParentClientId );

					if ( ! parentBlock ) {
						throw new Error(
							`[Edit Pattern] Parent block not found with clientId: ${ originalParentClientId }`
						);
					}
				}

				// Snapshot the parent's children before inserting so the
				// fallback below can verify it is rebuilding a complete list.
				const childrenBeforeInsert = getChildBlocks(
					originalParentClientId
				);

				// Create a valid block with proper validation
				const validBlock = await createBlockRecursively( block );
				// TODO: Find a better way to ensure innerBlocks are included reliably without this delay - registry.batch maybe?
				await setDelay( 200 );
				// insertBlock accepts null/undefined as rootClientId (inserts at root level for empty posts)
				insertBlock( validBlock, index, originalParentClientId );
				await setDelay( 0 );

				// Some restricted pattern/content-only block lists reject
				// `insertBlock` as a silent no-op even when the target parent
				// exists: `insertBlocks` drops any block that
				// `canInsertBlockType` rejects, which covers content-only
				// editing modes and section roots that only accept content
				// blocks. If that happens, fall back to replacing the parent's
				// inner blocks with the new block spliced into the requested
				// position. This stages the same structural change for block
				// lists where `replaceInnerBlocks` is permitted but inserter
				// permissions deny direct insertion.
				if (
					originalParentClientId &&
					! getBlock( validBlock.clientId )
				) {
					const currentChildren = getChildBlocks(
						originalParentClientId
					);

					if (
						! currentChildren.length &&
						childrenBeforeInsert.length
					) {
						// The parent's children have become unreadable, so
						// splicing into this list would replace all of them
						// with just the new block (BSKY-1992). Bail out rather
						// than delete the page content.
						log.error(
							'[Edit Blocks] Skipping insert fallback: the parent block list read back empty',
							{
								parentClientId: originalParentClientId,
								childrenBefore: childrenBeforeInsert.length,
							}
						);
					} else {
						const nextInnerBlocks = [ ...currentChildren ];
						nextInnerBlocks.splice( index, 0, validBlock );
						replaceInnerBlocks(
							originalParentClientId,
							nextInnerBlocks
						);
						await setDelay( 0 );
					}
				}

				// Clear processing state after insert
				// Use the block's clientId (WordPress may assign a new one, but we'll try the original first)
				const insertedBlock = getBlock( validBlock.clientId );
				if ( insertedBlock ) {
					setBlockIsProcessing( insertedBlock, false );
				}
			}
		}

		// Handle updates
		if ( editResults.updates?.length ) {
			// Do inner updates first. If we do outer updates first,
			// the clientIds of the inner blocks change.
			const clientIdDepth = new Map< string, number >();
			for ( const update of editResults.updates ) {
				const { clientId } = update;
				const originalClientId = reverseMap[ clientId ];
				const depth = getBlockParents( originalClientId )?.length ?? 0;
				clientIdDepth.set( clientId, depth );
			}
			const updates = [ ...editResults.updates ].sort(
				( a, b ) =>
					( clientIdDepth.get( b.clientId ) ?? 0 ) -
					( clientIdDepth.get( a.clientId ) ?? 0 )
			);
			for ( const update of updates ) {
				const { clientId, ...blockData } = update;
				const originalClientId = reverseMap[ clientId ];

				if ( ! originalClientId ) {
					// The agent's contract addresses top-level reorders to the
					// "core/post-content" parent, which the post editor does not
					// have — recover by reordering the list holding the children.
					if (
						clientId === POST_CONTENT_BLOCK_NAME &&
						applyReorderForUnmappedParent( update, reverseMap )
					) {
						recoveredTargetIds.add( clientId );
						continue;
					}
					throw new Error(
						`[Edit Blocks] Could not map compressed clientId: ${ clientId }`
					);
				}

				const targetBlock = getBlock( originalClientId );

				if ( ! targetBlock ) {
					throw new Error(
						`[Edit BLocks] Block not found with clientId: ${ originalClientId }`
					);
				}

				// Recursively merge block data to preserve properties at all levels
				const mergedBlockData = mergeBlocksRecursively(
					targetBlock,
					blockData,
					reverseMap
				);

				// Check if this is just an attribute update (no structural changes)
				const innerBlockUpdates = blockData.innerBlocks || [];
				const hasInnerBlockChanges = innerBlockUpdates.length > 0;
				const reorderOperations = hasInnerBlockChanges
					? getReorderOperations( targetBlock, blockData, reverseMap )
					: null;

				if ( reorderOperations ) {
					for ( const {
						parentClientId,
						childClientIds,
					} of reorderOperations ) {
						// Read after each deeper reorder so replacing an ancestor's
						// list cannot restore stale descendant ordering.
						replaceInnerBlocks(
							parentClientId,
							childClientIds.map( ( id ) => getBlock( id ) )
						);
					}
					const updatedBlock = getBlock( originalClientId );
					if ( updatedBlock ) {
						setBlockIsProcessing( updatedBlock, false );
					}
				} else if (
					REPLACE_INNER_BLOCKS_STRUCTURAL_PARENTS.has(
						targetBlock.name
					) &&
					hasInnerBlockChanges
				) {
					const reorderedBlocks = innerBlockUpdates.map(
						( innerBlock ) => {
							const innerClientId = innerBlock.clientId
								? reverseMap[ innerBlock.clientId ]
								: undefined;
							const existingBlock = innerClientId
								? getBlock( innerClientId )
								: null;

							if ( ! existingBlock ) {
								throw new Error(
									`[Edit Blocks] Could not find post content child block for reordering: ${ innerBlock.clientId }`
								);
							}

							return existingBlock;
						}
					);

					replaceInnerBlocks( originalClientId, reorderedBlocks );
					const updatedBlock = getBlock( originalClientId );
					if ( updatedBlock ) {
						setBlockIsProcessing( updatedBlock, false );
					}
				} else if ( ! hasInnerBlockChanges ) {
					// For attribute-only updates, use updateBlockAttributes.
					// This preserves the block instance and properly triggers re-renders.
					// Null values are delete signals; pass them as undefined because
					// omitting the key would make Gutenberg preserve the existing value.
					const attributesForUpdateBlockAttributes =
						getAttributesForUpdateBlockAttributes(
							targetBlock.attributes,
							blockData.attributes
						);

					updateBlockAttributes(
						originalClientId,
						attributesForUpdateBlockAttributes
					);

					// For cover blocks with image URL updates, automatically set overlay color
					if ( targetBlock.name === 'core/cover' ) {
						await updateCoverBlockOverlay(
							originalClientId,
							blockData.attributes?.url
						);
					}

					// Clear processing state after update
					const updatedBlock = getBlock( originalClientId );
					if ( updatedBlock ) {
						setBlockIsProcessing( updatedBlock, false );
					}
				} else {
					// For structural changes, we need to replace the entire block
					const validBlock =
						await createBlockRecursively( mergedBlockData );
					replaceBlock( originalClientId, validBlock );
					// Need to update the reverseMap with the new clientId
					reverseMap[ clientId ] = validBlock.clientId;

					// For cover blocks with image URL updates, automatically set overlay color
					if ( validBlock.name === 'core/cover' ) {
						await updateCoverBlockOverlay(
							validBlock.clientId,
							validBlock.attributes?.url
						);
					}

					// Clear processing state after replace
					// Use the new block's clientId in case it changed
					const replacedBlock = getBlock( validBlock.clientId );
					if ( replacedBlock ) {
						setBlockIsProcessing( replacedBlock, false );
					}
				}
			}
		}

		// Handle deletions
		if ( editResults.deletes?.length ) {
			await deleteBlocks( editResults.deletes, reverseMap );
		}

		// Wait for all AI promises to resolve, animations to finish
		await Promise.all( aiPromises );

		deleteMarkedMessages();

		return recoveredTargetIds;
	};

	/**
	 * Applies edits to an existing block.
	 *
	 * @param {ApplyBlockEditsArgs} args The arguments for the tool.
	 * @return {Promise<Object>} The edit results.
	 */
	const applyBlockEdits = async (
		args: ApplyBlockEditsArgs
	): Promise< {
		result: ApplyBlockEditsResultData;
		returnToAgent: boolean;
		agentMessage?: string;
		__file_parts?: FilePart[];
	} > => {
		let { reverseMap } = args;
		const {
			updates,
			inserts,
			deletes,
			summary,
			followUpTasks = false,
			messageId,
			toolCallId: suppliedToolCallId,
			suppressAssistantMessage,
			resetBlockProcessingStates = true,
			customCSS,
			visualCheckPending = false,
		} = args;
		// Use clientIdMap from hook closure as reverseMap
		if ( ! reverseMap ) {
			reverseMap = clientIdMap;
		}

		const toolCallId =
			suppliedToolCallId ||
			getToolCallIdFromConversationHistory(
				APPLY_BLOCK_EDITS_TOOL_ID,
				messageId
			);
		const getAgentMessage = (
			result: ApplyBlockEditsResultData,
			visualCheck = false
		) => {
			if ( suppliedToolCallId && toolCallId ) {
				return createApplyBlockEditsAgentMessage(
					toolCallId,
					result,
					followUpTasks,
					visualCheck
				);
			}

			return result.success ? localToolRunningMessage : undefined;
		};
		const getAgentMessageProperty = (
			result: ApplyBlockEditsResultData,
			visualCheck = false
		) => {
			const agentMessage = getAgentMessage( result, visualCheck );
			return agentMessage ? { agentMessage } : {};
		};

		const applyEditsAction = async () => {
			let checkpointCreated = false;
			let checkpointAlreadyExists = false;
			const editResults: EditResults = {
				updates,
				inserts,
				deletes,
				summary,
				customCSS,
			};

			try {
				// Normalize collection values before shape-dependent navigation detection.
				validateEditResults( editResults, availableBlocks );
				const hasNavigationEdit = isNavigationBlockEdit(
					editResults,
					reverseMap
				);
				const changeType = getApplyBlockEditsChangeType( editResults );
				const capturedTargets = new Map<
					string,
					CapturedValidationTarget
				>();
				const requestedTargetIds = [
					...( editResults.updates || [] ).map(
						( update ) => update.clientId
					),
					...( editResults.deletes || [] ),
				];
				requestedTargetIds.forEach( ( requestedClientId ) => {
					const resolvedClientId = reverseMap[ requestedClientId ];
					const beforeBlock = resolvedClientId
						? getBlock( resolvedClientId )
						: null;
					capturedTargets.set( requestedClientId, {
						resolvedClientId,
						...( beforeBlock
							? {
									beforeBlock: {
										clientId: beforeBlock.clientId,
										name: beforeBlock.name,
										attributes: beforeBlock.attributes
											? JSON.parse(
													JSON.stringify(
														beforeBlock.attributes
													)
											  )
											: undefined,
									},
							  }
							: {} ),
					} );
				} );
				const updateEditsAlreadySatisfied =
					areUpdateEditsAlreadySatisfied( editResults, reverseMap );
				const hasRequestedBlockEdits = Boolean(
					editResults.updates?.length ||
						editResults.inserts?.length ||
						editResults.deletes?.length
				);
				const hasCustomCSS = typeof customCSS === 'string';
				if ( ! hasRequestedBlockEdits && ! hasCustomCSS ) {
					const result: ApplyBlockEditsResultData = {
						success: true,
						message:
							summary ||
							__(
								'The requested changes were already applied.',
								'big-sky'
							),
						outcome: 'no-changes',
					};
					return {
						result,
						returnToAgent: true,
						...getAgentMessageProperty( result ),
					};
				}
				const globalStylesId = hasCustomCSS
					? getGlobalStylesId()
					: undefined;
				const globalStyles = globalStylesId
					? getEditedEntityRecord(
							'root',
							'globalStyles',
							globalStylesId
					  )
					: undefined;

				if ( hasCustomCSS && ( ! globalStylesId || ! globalStyles ) ) {
					throw new Error( GLOBAL_STYLES_UNAVAILABLE_ERROR );
				}

				const requestedCheckpointKeys = [];
				if ( hasRequestedBlockEdits && ! updateEditsAlreadySatisfied ) {
					requestedCheckpointKeys.push( checkpointKeys.BLOCKS );
				}

				const cssUpdateNeeded =
					hasCustomCSS &&
					( getStyle( globalStyles, 'css', null, false ) || '' ) !==
						customCSS;
				if ( cssUpdateNeeded ) {
					requestedCheckpointKeys.push( checkpointKeys.CUSTOM_CSS );
				}

				if ( toolCallId ) {
					checkpointAlreadyExists = hasCheckpoint( toolCallId );
				}
				if (
					toolCallId &&
					requestedCheckpointKeys.length > 0 &&
					! checkpointAlreadyExists
				) {
					setCheckpoint( toolCallId, requestedCheckpointKeys, {
						toolCallId,
						toolId: APPLY_BLOCK_EDITS_TOOL_ID,
						messageId,
						summary,
						changeType,
					} );
					checkpointCreated = true;
				}

				// Apply the edits
				const recoveredTargetIds = await applyEdits(
					editResults,
					reverseMap
				);

				// Replace custom CSS if provided.
				const freshGlobalStyles = globalStylesId
					? getEditedEntityRecord(
							'root',
							'globalStyles',
							globalStylesId
					  )
					: undefined;
				if ( hasCustomCSS && ! freshGlobalStyles ) {
					throw new Error( GLOBAL_STYLES_UNAVAILABLE_ERROR );
				}
				if ( cssUpdateNeeded && globalStylesId ) {
					const updatedGlobalStyles = setStyle(
						freshGlobalStyles,
						'css',
						customCSS
					);
					editEntityRecord(
						'root',
						'globalStyles',
						globalStylesId,
						updatedGlobalStyles
					);
				}

				// check to see if any edits were actually made by comparing the current blocks with the checkpoint
				const lastEditorState = getLastEditorState();
				const lastEditorStateBlocks = lastEditorState?.blocks || [];
				const currentEditorState: EditorState = {
					blocks: getRootBlocksState(),
				};
				const blockUpdateDetected =
					hasRequestedBlockEdits &&
					! updateEditsAlreadySatisfied &&
					( hasNavigationEdit ||
						JSON.stringify( lastEditorStateBlocks ) !==
							JSON.stringify( currentEditorState.blocks ) );

				if (
					! cssUpdateNeeded &&
					! hasNavigationEdit &&
					( updateEditsAlreadySatisfied ||
						JSON.stringify( lastEditorStateBlocks ) ===
							JSON.stringify( currentEditorState.blocks ) )
				) {
					if (
						updateEditsAlreadySatisfied ||
						( hasCustomCSS && ! hasRequestedBlockEdits )
					) {
						if ( toolCallId && checkpointCreated ) {
							clearCheckpoint( toolCallId );
						}
						const result: ApplyBlockEditsResultData = {
							success: true,
							message:
								summary ||
								__(
									'The requested changes were already applied.',
									'big-sky'
								),
							outcome: 'no-changes',
						};
						return {
							result,
							returnToAgent: true,
							...getAgentMessageProperty( result ),
						};
					}

					const noChangesMessage = __(
						"I was not able to make the changes you requested. Either I don't have the capability to do so or I didn't understand your request. You can ask me to try again or ask me to do something else.",
						'big-sky'
					);
					if ( toolCallId && checkpointCreated ) {
						clearCheckpoint( toolCallId );
					}
					const result: ApplyBlockEditsResultData = {
						success: false,
						message: noChangesMessage,
						error: 'No block or CSS changes were detected after applying edits.',
					};
					return {
						result,
						returnToAgent: true,
						...getAgentMessageProperty( result ),
					};
				}

				const differences = compareBlockStates(
					lastEditorStateBlocks,
					currentEditorState.blocks
				);
				const previousBlockByClientId = new Map(
					flattenBlocksFromRootState( lastEditorStateBlocks ).map(
						( block ) => [ block.clientId, block ]
					)
				);
				const currentBlockByClientId = new Map(
					flattenBlocksFromRootState( currentEditorState.blocks ).map(
						( block ) => [ block.clientId, block ]
					)
				);
				capturedTargets.forEach( ( target, requestedClientId ) => {
					const resolvedClientId =
						reverseMap[ requestedClientId ] ||
						target.resolvedClientId;
					if ( ! resolvedClientId ) {
						return;
					}

					if (
						target.beforeBlock &&
						! previousBlockByClientId.has( resolvedClientId )
					) {
						previousBlockByClientId.set(
							resolvedClientId,
							target.beforeBlock
						);
					}

					if ( ! currentBlockByClientId.has( resolvedClientId ) ) {
						const afterBlock = getBlock( resolvedClientId );
						if ( afterBlock ) {
							currentBlockByClientId.set(
								resolvedClientId,
								afterBlock
							);
						}
					}
				} );
				const contentTextSnapshot = getContentTextSnapshot(
					editResults,
					currentBlockByClientId
				);
				const unresolvedTargets = getUnresolvedTargets(
					editResults,
					capturedTargets,
					recoveredTargetIds
				);
				const deleteResults = getDeleteResults(
					editResults,
					reverseMap,
					previousBlockByClientId,
					currentBlockByClientId
				);
				const attributeResults = getAttributeResults(
					editResults,
					reverseMap,
					previousBlockByClientId,
					currentBlockByClientId
				);
				const unsupportedAttributes = getUnsupportedAttributes(
					editResults,
					blockTypes
				);
				log.info( 'Detailed changes:', differences );

				const summaryText =
					summary || __( 'I have completed the edits.', 'big-sky' );
				const details = {
					appliedOperations: getAppliedOperations(
						differences,
						lastEditorState?.blocks,
						currentEditorState.blocks
					),
					...( unresolvedTargets.length
						? { unresolvedTargets }
						: {} ),
					...( deleteResults.length ? { deleteResults } : {} ),
					...( attributeResults.length ? { attributeResults } : {} ),
					...( unsupportedAttributes.length
						? { unsupportedAttributes }
						: {} ),
					...( contentTextSnapshot ? { contentTextSnapshot } : {} ),
				};
				const result: ApplyBlockEditsResultData = {
					success: true,
					message: summaryText,
					outcome: 'updated',
					changeType,
					details,
				};

				// If a checkpoint was created but no block updates were detected,
				// remove the checkpoint to avoid leaving an unnecessary checkpoint in place.
				if (
					toolCallId &&
					checkpointCreated &&
					! blockUpdateDetected &&
					hasRequestedBlockEdits
				) {
					removeCheckpointKeys( toolCallId, [
						checkpointKeys.BLOCKS,
					] );
				}
				if ( toolCallId && changeType === 'text-content' ) {
					sealCheckpointForSwap( toolCallId );
				}

				// Return a compact post-apply validation summary so the agent can
				// distinguish "applied" from "verified" without receiving full block JSON.
				return {
					result,
					returnToAgent: true,
					...getAgentMessageProperty( result ),
				};
			} catch ( error ) {
				const errorMessage = __(
					'Something went wrong. Please try again.',
					'big-sky'
				);
				deleteMarkedMessages();
				const errorDetails =
					error instanceof Error ? error.message : String( error );
				if ( ! suppressAssistantMessage ) {
					addAssistantMessage( ASSISTANTS.BLOCKS, errorMessage );
				}
				log.error( '[Apply Block Edits] Error:', error );
				// Keep the pre-edit checkpoint so a retry or partial failure can
				// still restore the state from before this tool call.
				const result: ApplyBlockEditsResultData = {
					success: false,
					message: errorMessage,
					error: errorDetails,
				};
				return {
					result,
					returnToAgent: true,
					...getAgentMessageProperty( result ),
				};
			} finally {
				if ( resetBlockProcessingStates ) {
					resetAllBlockIsProcessing();
				}
			}
		};

		const outcome = await applyEditsAction();

		// Capture after `applyEditsAction`, never inside it. Every one of its
		// return paths wants the image, and the two that want it most are the
		// ones that report no change: an edit whose requested values were
		// already present, and an edit that reports failure. Those are exactly
		// the cases where the block tree cannot say whether the user's problem
		// is fixed, so an early return that skipped the capture would go blind
		// where it matters. Capturing here also runs after the `finally` that
		// clears processing states, so the image is free of the transient
		// `big-sky__is-processing` styling.
		const fileParts = await captureCanvasFileParts( {
			clientIds: getEditedClientIds( { updates }, reverseMap ),
		} );

		// Omit the key when there is no image, rather than sending an empty
		// array: results that carry no files keep exactly their current shape.
		if ( ! fileParts ) {
			return outcome;
		}

		// `visualCheckPending` says the server *may* hold its acknowledgement
		// back to look at the capture — it cannot know whether one exists,
		// because the capture is taken here, after the result it belongs to has
		// already been built. So the halves are ANDed at the one point where
		// both are in scope, and the flag ships only if an image did too.
		//
		// A refused or blank capture must leave it off. The client swaps the
		// summary for a checking state on the strength of this flag, and with no
		// image there is nothing for the server to look at: the summary would be
		// withheld for a reply that never comes.
		const agentMessageProperty = visualCheckPending
			? getAgentMessageProperty( outcome.result, true )
			: {};

		return { ...outcome, ...agentMessageProperty, __file_parts: fileParts };
	};

	return {
		applyBlockEdits,
	};
}
