	deleteMarkedMessages() {
		return async ( { dispatch, select } ) => {
			const getMessagesToDelete = select.getMessagesToDelete;
			const messagesToDelete = getMessagesToDelete();

			// Calypso custom action: Call custom `deleteMarkedMessages` if registered
			if ( messagesToDelete.length ) {
				getCustomAction( 'deleteMarkedMessages' )?.( messagesToDelete );
			}

			messagesToDelete
				.filter( ( message ) => message.id )
				.forEach( ( message ) => {
					dispatch.deleteMessage( message.id );
				} );
			dispatch.clearMessagesToDelete();
		};
	},
	addThinkingMessage( assistantId, message = __( 'Thinking', 'big-sky' ) ) {
		return async ( { dispatch } ) => {
			await dispatch.deleteMarkedMessages();
			const thinkingMessage = await dispatch.assistantSay(
				<ThinkingMessage message={ message } />
			);
			dispatch.addMessageToDelete( {
				id: thinkingMessage?.message?.id,
			} );
			return thinkingMessage?.message;
		};
	},
	disableAllPreviousComponentMessages() {
		return ( { select, dispatch } ) => {
			const messages = select.getMessages();

			// Add disabled flag only to messages that contain a picker component
			messages.forEach( ( message ) => {
				if ( hasPickerComponent( message ) ) {
					dispatch.updateMessage( message.id, { disabled: true } );
				}
			} );
		};
	},
