/**
 * Surface-agnostic progressive page-design renderer.
 *
 * This module owns the incremental block-preview state machine and the
 * throttle/flush/retry orchestration that streams page-design markup into a
 * Gutenberg editor canvas. It is deliberately decoupled from any one editor
 * surface: every read/write of the actual editor goes through the `EditorHost`
 * adapter, so ESE (and, later, the standard Gutenberg editors) can supply their
 * own sub-registry, undo strategy, checkpoint store, and global-styles wiring.
 *
 * The DOM preview helpers (scroll-follow + preview-styles injection) query the
 * generic `iframe[name="editor-canvas"]` and `document`, so they stay internal
 * and are called directly rather than routed through the host.
 */
import { useCallback, useEffect, useRef } from '@wordpress/element';
import {
	createBlock,
	getBlockType,
	parse,
	serialize,
	validateBlock,
} from '@wordpress/blocks';
import {
	extractSection,
	setStreamPageDesignHandler,
	STREAM_PAGE_DESIGN_TOOL_ID,
	type StreamPageDesignHandler,
	type StreamPageDesignUpdate,
	stripStyleTags,
} from './index';

// Re-exported so importers/tests of this pure helper from a re-exporting module
// keep working after the move to the shared core.
export { extractSection };

// TEMP (page designs → theme styling only): Currently custom CSS is toggled off until
// we work out a robust way to merge with existing CSS.

const APPLY_GENERATED_CSS: boolean = false;

// A block as the editor (and this renderer) sees it: a clientId, name, optional
// attributes, and recursive inner blocks.
export interface EditorBlock {
	clientId: string;
	name: string;
	attributes?: Record< string, unknown >;
	innerBlocks?: EditorBlock[];
}

export interface CreatedBlock extends EditorBlock {
	innerBlocks?: CreatedBlock[];
}

/**
 * The host adapter through which the renderer touches the editor surface. All
 * surface-specific decisions (which registry, how undo levels are built, where
 * checkpoints live, how global styles are wired) live behind these methods.
 */
export interface EditorHost {
	/** Read the current editor block tree (or the inner blocks of a root). */
	getBlocks: ( rootClientId?: string ) => EditorBlock[];
	/**
	 * The clientId to stage top-level page blocks into (ESE: core/post-content),
	 * or null when the canvas/target is not ready yet. The renderer treats a
	 * non-null return as "the canvas is ready".
	 */
	resolveTargetRoot: () => string | null;
	/**
	 * Replace the inner blocks of `rootClientId` with `blocks`, in the surface's
	 * own streaming/untracked undo mode. Called once per delta as preview blocks
	 * are appended/finalized.
	 */
	stageBlocks: (
		rootClientId: string | null,
		blocks: CreatedBlock[],
		updateSelection?: boolean
	) => void;
	/**
	 * Snapshot the page exactly once per stream, before the first stage, so the
	 * whole redesign can be reverted by the surface's checkpoint/restore system.
	 */
	captureCheckpoint: (
		toolCallId: string,
		meta: { toolId: string; summary: string }
	) => void;
	/**
	 * Fold the whole streamed redesign (blocks + optional CSS) into a single
	 * native undo level on the final flush.
	 */
	commitFinalDesign: (
		toolCallId: string,
		rootClientId: string | null,
		finalCss: string | null
	) => void;
	/** Apply streaming preview CSS (untracked) during the live stream. */
	applyCustomCss: ( css: string ) => Promise< void >;
}

// How often to re-render the editor from the accumulated markup while it is
// still streaming. Coalescing rapid deltas keeps the main thread free (so the
// editor canvas can mount) and avoids re-rendering the whole post content on
// every few-character delta. The final update always flushes immediately.
const FLUSH_INTERVAL_MS = 150;
// The editor canvas (and its post-content block) mounts asynchronously, so a
// flush can land before there is anywhere to stage into. Retry across roughly
// this many flush intervals before giving up, so buffered markup is not lost
// when the handler registers (or replays) ahead of the post-content block.
const MAX_FLUSH_RETRIES = 20;
const NESTED_CONTAINER_SCROLL_INTERVAL = 3;
const PREVIEW_CLASS_NAME = 'is-easy-site-editor-stream-preview';
const PREVIEW_STYLES_ID = 'easy-site-editor-stream-preview-styles';

interface ParsedBlockComment {
	blockName: string;
	attributes: Record< string, unknown >;
	isSelfClosing: boolean;
}

interface ExtractedBlockMarkup {
	blockMarkup: string;
	remaining: string;
}

interface PreviewState {
	childBlocks: CreatedBlock[];
	clientId: string;
	currentChildPreview: PreviewState | null;
	didQueueContainerScroll: boolean;
	isContainerCandidate: boolean;
	lastInnerMarkup: string;
	markup: string;
	nestedContainerScrollCount: number;
	pendingInnerBuffer: string;
	scrolledAfterFirstContent: boolean;
}

interface ToolCallRenderState {
	currentPreview: PreviewState | null;
	didReplaceInitialContent: boolean;
	lastPageContent: string;
	pendingPageBuffer: string;
	topLevelBlocks: CreatedBlock[];
}

export function isRecord( value: unknown ): value is Record< string, unknown > {
	return !! value && typeof value === 'object' && ! Array.isArray( value );
}

// Recursively drop malformed blocks (falsy, or missing clientId/name) at any
// depth before serializing the checkpoint/live block trees to entity `content`,
// so a hole in the tree can't make `serialize` throw. Exported so a host's
// commit-undo step can reuse the exact same sanitization the renderer uses.
export function sanitizeBlockTree( blocks: CreatedBlock[] ): CreatedBlock[] {
	if ( ! Array.isArray( blocks ) ) {
		return [];
	}

	return blocks
		.filter(
			( block ): block is CreatedBlock =>
				!! block && !! block.clientId && !! block.name
		)
		.map( ( block ) =>
			block.innerBlocks?.length
				? {
						...block,
						innerBlocks: sanitizeBlockTree( block.innerBlocks ),
				  }
				: block
		);
}

export function withSuppressedValidationLogs< T >( callback: () => T ): T {
	const originalWarn = window.console.warn;
	const originalError = window.console.error;
	const shouldSuppress = ( args: unknown[] ) =>
		args.some(
			( arg ) =>
				typeof arg === 'string' &&
				( arg.includes( 'Block validation:' ) ||
					arg.includes( 'Block validation failed for' ) )
		);

	window.console.warn = ( ...args: unknown[] ) => {
		if ( shouldSuppress( args ) ) {
			return;
		}

		originalWarn.apply( window.console, args );
	};

	window.console.error = ( ...args: unknown[] ) => {
		if ( shouldSuppress( args ) ) {
			return;
		}

		originalError.apply( window.console, args );
	};

	try {
		return callback();
	} finally {
		window.console.warn = originalWarn;
		window.console.error = originalError;
	}
}

export function parseAttributes(
	attrString: string | undefined
): Record< string, string > {
	const attrs: Record< string, string > = {};

	if ( ! attrString ) {
		return attrs;
	}

	const doubleQuotePattern = /(\S+)="([^"]*)"/g;
	const singleQuotePattern = /(\S+)='([^']*)'/g;
	let match;

	while ( ( match = doubleQuotePattern.exec( attrString ) ) !== null ) {
		attrs[ match[ 1 ] ] = match[ 2 ];
	}

	while ( ( match = singleQuotePattern.exec( attrString ) ) !== null ) {
		if ( ! ( match[ 1 ] in attrs ) ) {
			attrs[ match[ 1 ] ] = match[ 2 ];
		}
	}

	return attrs;
}

export function mergeAttributes(
	outerAttrs: string,
	innerAttrs: string
): Record< string, string > {
	const outer = parseAttributes( outerAttrs );
	const inner = parseAttributes( innerAttrs );
	const merged = { ...outer };

	Object.entries( inner ).forEach( ( [ key, value ] ) => {
		if ( key === 'class' ) {
			const outerClasses = ( outer.class || '' )
				.split( /\s+/ )
				.filter( Boolean );
			const innerClasses = value.split( /\s+/ ).filter( Boolean );
			merged.class = [
				...new Set( [ ...outerClasses, ...innerClasses ] ),
			].join( ' ' );
			return;
		}

		if ( key === 'style' ) {
			const outerStyles = ( outer.style || '' )
				.split( ';' )
				.filter( Boolean );
			const innerStyles = value.split( ';' ).filter( Boolean );
			const styleMap: Record< string, string > = {};

			[ ...outerStyles, ...innerStyles ].forEach( ( style ) => {
				const colonIndex = style.indexOf( ':' );

				if ( colonIndex <= 0 ) {
					return;
				}

				const property = style.substring( 0, colonIndex ).trim();
				const styleValue = style.substring( colonIndex + 1 ).trim();
				styleMap[ property ] = styleValue;
			} );

			merged.style = Object.entries( styleMap )
				.map(
					( [ property, styleValue ] ) =>
						`${ property }:${ styleValue }`
				)
				.join( ';' );
			return;
		}

		if ( ! ( key in outer ) ) {
			merged[ key ] = value;
		}
	} );

	return merged;
}

function serializeAttributes( attrs: Record< string, string > ): string {
	const parts = Object.entries( attrs ).map(
		( [ key, value ] ) => `${ key }="${ value }"`
	);
	return parts.length ? ` ${ parts.join( ' ' ) }` : '';
}

export function fixNestedParagraphs( htmlContent: string ): string {
	if ( ! htmlContent.includes( '<!-- wp:paragraph' ) ) {
		return htmlContent;
	}

	const wpParagraphBlockPattern =
		/(<!-- wp:paragraph[^>]*-->)([\s\S]*?)(<!-- \/wp:paragraph -->)/g;
	const nestedPPattern =
		/<p(\s[^>]*)?>(\s*)<p(\s[^>]*)?>([^]*?)<\/p>(\s*)<\/p>/gi;

	return htmlContent.replace(
		wpParagraphBlockPattern,
		( _fullMatch, openComment, blockContent, closeComment ) => {
			let fixedContent = blockContent;
			let previousContent;

			do {
				previousContent = fixedContent;
				fixedContent = fixedContent.replace(
					nestedPPattern,
					(
						_match: string,
						outerAttrs = '',
						_ws1: string,
						innerAttrs = '',
						innerContent: string
					) => {
						const mergedAttrs = mergeAttributes(
							outerAttrs,
							innerAttrs
						);
						return `<p${ serializeAttributes(
							mergedAttrs
						) }>${ innerContent }</p>`;
					}
				);
			} while ( fixedContent !== previousContent );

			return `${ openComment }${ fixedContent }${ closeComment }`;
		}
	);
}

function isBlockValid( block: CreatedBlock ): boolean {
	const blockType = getBlockType( block.name );

	if ( ! blockType ) {
		return false;
	}

	const validation = withSuppressedValidationLogs( () =>
		validateBlock( block, blockType )
	);

	return Array.isArray( validation ) ? validation[ 0 ] : validation.isValid;
}

function repairBlock( block: CreatedBlock ): {
	block: CreatedBlock;
	wasFixed: boolean;
} {
	if ( ! block?.name ) {
		return { block, wasFixed: false };
	}

	let anyInnerFixed = false;
	const repairedInnerBlocks = ( block.innerBlocks || [] ).map(
		( innerBlock ) => {
			const result = repairBlock( innerBlock );
			if ( result.wasFixed ) {
				anyInnerFixed = true;
			}
			return result.block;
		}
	);

	const candidate = {
		...block,
		innerBlocks: repairedInnerBlocks,
	};

	if ( isBlockValid( candidate ) && ! anyInnerFixed ) {
		return { block: candidate, wasFixed: false };
	}

	const fixedBlock = createBlock(
		candidate.name,
		candidate.attributes,
		repairedInnerBlocks.length > 0 ? repairedInnerBlocks : undefined
	) as CreatedBlock;

	return { block: fixedBlock, wasFixed: true };
}

function repairBlocksFromMarkup( completedMarkup: string ): CreatedBlock[] {
	const preFixedMarkup = fixNestedParagraphs( completedMarkup );
	const parsedBlocks = withSuppressedValidationLogs( () =>
		parse( preFixedMarkup )
	) as CreatedBlock[];

	if ( ! parsedBlocks.length ) {
		return [];
	}

	const repairedBlocks = parsedBlocks.map(
		( block ) => repairBlock( block ).block
	);
	const normalizedMarkup = withSuppressedValidationLogs( () =>
		serialize( repairedBlocks )
	);
	const postFixedMarkup = fixNestedParagraphs( normalizedMarkup );

	return withSuppressedValidationLogs( () =>
		parse( postFixedMarkup )
	) as CreatedBlock[];
}

export function parseBlockComment(
	comment: string
): ParsedBlockComment | null {
	const innerComment = comment
		.replace( /^<!--\s*/, '' )
		.replace( /\s*-->$/, '' )
		.trim();

	if (
		! innerComment.startsWith( 'wp:' ) ||
		innerComment.startsWith( '/wp:' )
	) {
		return null;
	}

	const match = innerComment.match(
		/^wp:([^\s]+)(?:\s+([\s\S]*?))?\s*(\/)?$/
	);

	if ( ! match ) {
		return null;
	}

	let attributes: Record< string, unknown > = {};
	const rawAttributes = ( match[ 2 ] || '' ).trim();

	if ( rawAttributes ) {
		try {
			attributes = JSON.parse( rawAttributes );
		} catch {
			attributes = {};
		}
	}

	const rawBlockName = match[ 1 ];
	const blockName = rawBlockName.includes( '/' )
		? rawBlockName
		: `core/${ rawBlockName }`;

	return {
		blockName,
		attributes,
		isSelfClosing: Boolean( match[ 3 ] ),
	};
}

// Blocks whose serialized body is raw, opaque markup that has no child block
// delimiters. Their content can legitimately contain literal "<!--", "-->" and
// "wp:"/"\/wp:" delimiter-looking text (e.g. a core/html block demonstrating
// block markup). The structural scanner must treat their body as opaque and
// jump straight to the matching close delimiter, otherwise delimiter-looking
// text in the content desynchronizes depth tracking and can stall the stream.
const RAW_CONTENT_BLOCK_NAMES = [
	'core/html',
	'core/freeform',
	'core/code',
	'core/preformatted',
];

function isRawContentBlockName( blockName: string ): boolean {
	return RAW_CONTENT_BLOCK_NAMES.includes( blockName );
}

// Given a buffer position at a '{', return the index just past the matching
// '}', skipping over braces and "-->" sequences that appear inside JSON string
// values. Returns -1 when the object has not finished streaming yet.
function skipJsonObject( buffer: string, start: number ): number {
	let depth = 0;
	let inString = false;
	let escaped = false;

	for ( let index = start; index < buffer.length; index++ ) {
		const char = buffer[ index ];

		if ( inString ) {
			if ( escaped ) {
				escaped = false;
			} else if ( char === '\\' ) {
				escaped = true;
			} else if ( char === '"' ) {
				inString = false;
			}
			continue;
		}

		if ( char === '"' ) {
			inString = true;
		} else if ( char === '{' ) {
			depth += 1;
		} else if ( char === '}' ) {
			depth -= 1;
			if ( depth === 0 ) {
				return index + 1;
			}
		}
	}

	return -1;
}

interface ParsedBlockDelimiter {
	kind: 'open' | 'close' | 'self-closing' | 'other';
	rawName: string | null;
	blockName: string | null;
	end: number;
}

// Reads the block delimiter (or plain HTML comment) that begins at `start`,
// where buffer[start..] starts with '<!--'. The opening-delimiter attribute
// JSON is parsed brace-aware so a "-->" inside an attribute value is not
// mistaken for the end of the comment. Returns null when the delimiter has not
// finished streaming (the caller should wait for more markup).
function readBlockDelimiter(
	buffer: string,
	start: number
): ParsedBlockDelimiter | null {
	let index = start + '<!--'.length;

	while ( index < buffer.length && /\s/.test( buffer[ index ] ) ) {
		index += 1;
	}

	const isClosing = buffer.startsWith( '/wp:', index );
	const isOpening = ! isClosing && buffer.startsWith( 'wp:', index );

	if ( ! isClosing && ! isOpening ) {
		const end = buffer.indexOf( '-->', index );
		return end === -1
			? null
			: { kind: 'other', rawName: null, blockName: null, end: end + 3 };
	}

	index += isClosing ? '/wp:'.length : 'wp:'.length;

	const nameMatch = /^[a-zA-Z][a-zA-Z0-9-]*(?:\/[a-zA-Z][a-zA-Z0-9-]*)?/.exec(
		buffer.slice( index, index + 200 )
	);

	if ( ! nameMatch ) {
		return null;
	}

	const rawName = nameMatch[ 0 ];
	const blockName = rawName.includes( '/' ) ? rawName : `core/${ rawName }`;
	index += rawName.length;

	if ( isClosing ) {
		const end = buffer.indexOf( '-->', index );
		return end === -1
			? null
			: { kind: 'close', rawName, blockName, end: end + 3 };
	}

	while ( index < buffer.length && /\s/.test( buffer[ index ] ) ) {
		index += 1;
	}

	if ( buffer[ index ] === '{' ) {
		const jsonEnd = skipJsonObject( buffer, index );
		if ( jsonEnd === -1 ) {
			return null;
		}
		index = jsonEnd;
	}

	while ( index < buffer.length && /\s/.test( buffer[ index ] ) ) {
		index += 1;
	}

	let selfClosing = false;
	if ( buffer[ index ] === '/' ) {
		selfClosing = true;
		index += 1;
		while ( index < buffer.length && /\s/.test( buffer[ index ] ) ) {
			index += 1;
		}
	}

	if ( ! buffer.startsWith( '-->', index ) ) {
		return null;
	}

	return {
		kind: selfClosing ? 'self-closing' : 'open',
		rawName,
		blockName,
		end: index + '-->'.length,
	};
}

// Finds the index just past the matching close delimiter for a raw-content
// block whose body must be treated as opaque. Returns -1 when the close has not
// streamed yet.
function findRawContentBlockCloseEnd(
	buffer: string,
	fromIndex: number,
	rawName: string
): number {
	const closePattern = new RegExp( `<!--\\s*/wp:${ rawName }\\s*-->`, 'g' );
	closePattern.lastIndex = fromIndex;
	const match = closePattern.exec( buffer );
	return match ? match.index + match[ 0 ].length : -1;
}

export function extractCompleteTopLevelBlock(
	markupBuffer: string
): ExtractedBlockMarkup | null {
	const trimmedLeadingBuffer = markupBuffer.replace( /^\s+/, '' );

	if ( ! trimmedLeadingBuffer ) {
		return null;
	}

	const openingBlockMatch = /<!--\s*wp:/i.exec( trimmedLeadingBuffer );

	if ( ! openingBlockMatch ) {
		return null;
	}

	// While a container block is still open, its raw wrapper HTML can stream
	// before its first child block delimiter. Treat that wrapper as temporary
	// scaffolding and never parse it as a standalone freeform/classic block.
	const blockBuffer = trimmedLeadingBuffer.slice( openingBlockMatch.index );

	let position = 0;
	let depth = 0;
	let foundOpeningBlock = false;

	while ( position < blockBuffer.length ) {
		const commentStart = blockBuffer.indexOf( '<!--', position );

		if ( commentStart === -1 ) {
			return null;
		}

		const delimiter = readBlockDelimiter( blockBuffer, commentStart );

		if ( ! delimiter ) {
			return null;
		}

		if (
			( delimiter.kind === 'open' ||
				delimiter.kind === 'self-closing' ) &&
			delimiter.blockName &&
			isRawContentBlockName( delimiter.blockName ) &&
			delimiter.rawName &&
			delimiter.kind === 'open'
		) {
			// Raw-content block: skip its opaque body straight to the matching
			// close so delimiter-looking text inside the content is ignored.
			const closeEnd = findRawContentBlockCloseEnd(
				blockBuffer,
				delimiter.end,
				delimiter.rawName
			);

			if ( closeEnd === -1 ) {
				return null;
			}

			if ( depth === 0 ) {
				return {
					blockMarkup: blockBuffer.slice( 0, closeEnd ),
					remaining: blockBuffer.slice( closeEnd ),
				};
			}

			foundOpeningBlock = true;
			position = closeEnd;
			continue;
		}

		if ( delimiter.kind === 'self-closing' ) {
			foundOpeningBlock = true;

			if ( depth === 0 ) {
				return {
					blockMarkup: blockBuffer.slice( 0, delimiter.end ),
					remaining: blockBuffer.slice( delimiter.end ),
				};
			}
		} else if ( delimiter.kind === 'open' ) {
			foundOpeningBlock = true;
			depth += 1;
		} else if ( delimiter.kind === 'close' && depth > 0 ) {
			depth -= 1;

			if ( depth === 0 && foundOpeningBlock ) {
				return {
					blockMarkup: blockBuffer.slice( 0, delimiter.end ),
					remaining: blockBuffer.slice( delimiter.end ),
				};
			}
		}

		position = delimiter.end;
	}

	return null;
}

function getPreviewInnerMarkup( previewMarkup: string ): string {
	const trimmedMarkup = previewMarkup.replace( /^\s+/, '' );
	const openingCommentEnd = trimmedMarkup.indexOf( '-->' );

	if ( openingCommentEnd === -1 ) {
		return '';
	}

	return trimmedMarkup.slice( openingCommentEnd + 3 );
}

function findNextOpeningBlockComment(
	markupBuffer: string
): { index: number; end: number; comment: string } | null {
	const openingCommentPattern = /<!--\s*wp:[\s\S]*?-->/g;
	const match = openingCommentPattern.exec( markupBuffer );

	if ( ! match ) {
		return null;
	}

	return {
		index: match.index,
		end: match.index + match[ 0 ].length,
		comment: match[ 0 ],
	};
}

function getDeepestLastClientId( blocks: CreatedBlock[] ): string | null {
	const lastBlock = blocks[ blocks.length - 1 ];

	if ( ! lastBlock ) {
		return null;
	}

	if ( lastBlock.innerBlocks?.length ) {
		return getDeepestLastClientId( lastBlock.innerBlocks );
	}

	return lastBlock.clientId;
}

function getLastContainerClientId( blocks: CreatedBlock[] ): string | null {
	for ( let index = blocks.length - 1; index >= 0; index-- ) {
		const block = blocks[ index ];
		const childContainerClientId = getLastContainerClientId(
			block.innerBlocks || []
		);

		if ( childContainerClientId ) {
			return childContainerClientId;
		}

		if ( block.innerBlocks?.length ) {
			return block.clientId;
		}
	}

	return null;
}

function isLikelyContainerBlockName( blockName: string ): boolean {
	return [
		'core/buttons',
		'core/column',
		'core/columns',
		'core/cover',
		'core/details',
		'core/group',
		'core/media-text',
		'core/navigation',
		'core/query',
		'core/query-no-results',
		'core/query-pagination',
		'core/query-pagination-numbers',
		'core/query-title',
		'core/social-links',
		'core/stack',
		'wpcom/site-section',
	].includes( blockName );
}

function getThrottledNestedContainerScrollTarget(
	rootPreviewState: PreviewState,
	clientId: string | null
): string | null {
	if ( ! clientId ) {
		return null;
	}

	rootPreviewState.nestedContainerScrollCount += 1;

	if (
		rootPreviewState.nestedContainerScrollCount %
			NESTED_CONTAINER_SCROLL_INTERVAL !==
		0
	) {
		return null;
	}

	return clientId;
}

function getPreviewContainerScrollTarget(
	rootPreviewState: PreviewState,
	previewState: PreviewState
): string | null {
	if (
		previewState.didQueueContainerScroll ||
		( ! previewState.isContainerCandidate &&
			previewState.childBlocks.length === 0 )
	) {
		return null;
	}

	previewState.didQueueContainerScroll = true;

	return getThrottledNestedContainerScrollTarget(
		rootPreviewState,
		previewState.clientId
	);
}

function addPreviewClass(
	attributes: Record< string, unknown >
): Record< string, unknown > {
	return {
		...attributes,
		className: [
			typeof attributes.className === 'string'
				? attributes.className
				: '',
			PREVIEW_CLASS_NAME,
		]
			.filter( Boolean )
			.join( ' ' ),
	};
}

function createPreviewState(
	clientId: string,
	markup: string,
	isContainerCandidate = false
): PreviewState {
	return {
		childBlocks: [],
		clientId,
		currentChildPreview: null,
		didQueueContainerScroll: false,
		isContainerCandidate,
		lastInnerMarkup: '',
		markup,
		nestedContainerScrollCount: 0,
		pendingInnerBuffer: '',
		scrolledAfterFirstContent: false,
	};
}

function createPreviewBlockFromOpenMarkup(
	markupBuffer: string
): { block: CreatedBlock; markup: string } | null {
	const openingComment = findNextOpeningBlockComment( markupBuffer );

	if ( ! openingComment ) {
		return null;
	}

	const parsedComment = parseBlockComment( openingComment.comment );

	if ( ! parsedComment || parsedComment.isSelfClosing ) {
		return null;
	}

	const trimmedMarkup = markupBuffer.slice( openingComment.index );

	try {
		return {
			block: createBlock(
				parsedComment.blockName,
				addPreviewClass( parsedComment.attributes ),
				[]
			) as CreatedBlock,
			markup: trimmedMarkup,
		};
	} catch {
		return null;
	}
}

function getScrollParent( node: HTMLElement ): HTMLElement | null {
	let parent = node.parentElement;

	while ( parent ) {
		const style =
			parent.ownerDocument.defaultView?.getComputedStyle( parent );
		const overflowY = style?.overflowY || '';
		const canScroll =
			parent.scrollHeight > parent.clientHeight &&
			/(auto|scroll)/.test( overflowY );

		if ( canScroll ) {
			return parent;
		}

		parent = parent.parentElement;
	}

	return null;
}

function scrollBlockBottomByCoordinates( node: HTMLElement ): void {
	const ownerDocument = node.ownerDocument;
	const ownerWindow = ownerDocument.defaultView;
	const scrollParent = getScrollParent( node );
	const nodeRect = node.getBoundingClientRect();

	if ( scrollParent ) {
		const parentRect = scrollParent.getBoundingClientRect();
		const targetScrollTop =
			scrollParent.scrollTop + nodeRect.bottom - parentRect.bottom + 24;

		scrollParent.scrollTo( {
			top: Math.max( 0, targetScrollTop ),
			behavior: 'smooth',
		} );
		return;
	}

	const scrollingElement =
		ownerDocument.scrollingElement || ownerDocument.documentElement;
	const viewportHeight =
		ownerWindow?.innerHeight || scrollingElement.clientHeight;
	const targetScrollTop =
		scrollingElement.scrollTop + nodeRect.bottom - viewportHeight + 24;

	ownerWindow?.scrollTo( {
		top: Math.max( 0, targetScrollTop ),
		behavior: 'smooth',
	} );
}

// Scrolls the bottom of the most recently streamed container into view inside
// the editor canvas. `scrollIntoView` can fire before the container has enough
// height to extend the scroll area, so use measured coordinates and keep
// tracking the same block while React/BlockCanvas renders streamed children.
// Tracks the in-flight scroll-follow animation frame so a newer scroll target
// supersedes the previous one instead of stacking another 8-frame chain on top
// of it every flush.
let activeScrollRafId: number | null = null;

function scrollToBlockBottom( clientId: string ): void {
	const attempt = ( retriesLeft: number ): void => {
		activeScrollRafId = null;

		const iframe = document.querySelector< HTMLIFrameElement >(
			'iframe[name="editor-canvas"]'
		);
		const node = iframe?.contentDocument?.querySelector< HTMLElement >(
			`[data-block="${ clientId }"]`
		);

		if ( node ) {
			try {
				scrollBlockBottomByCoordinates( node );
			} catch {
				// Best-effort; ignore unexpected scroll/iframe access errors.
			}
		}

		// Keep tracking the same block while React/BlockCanvas renders streamed
		// children, whether or not the node has appeared yet.
		if ( retriesLeft > 0 ) {
			activeScrollRafId = requestAnimationFrame( () =>
				attempt( retriesLeft - 1 )
			);
		}
	};

	// Cancel any in-flight follow chain so only the latest target is tracked.
	if ( activeScrollRafId !== null ) {
		cancelAnimationFrame( activeScrollRafId );
	}
	activeScrollRafId = requestAnimationFrame( () => attempt( 8 ) );
}

// The preview-only styles injected during streaming. Exported so it can be unit
// tested. The pulse animation is disabled under prefers-reduced-motion (WCAG
// 2.2.2 / 2.3.3); the static outline still marks in-progress preview blocks.
export const PREVIEW_STYLES_CSS = `
	.${ PREVIEW_CLASS_NAME } {
		position: relative;
		overflow: hidden;
		outline: 2px solid rgba(56, 88, 233, 0.38);
		outline-offset: 6px;
		box-shadow: 0 0 0 6px rgba(56, 88, 233, 0.08);
	}

	.${ PREVIEW_CLASS_NAME }::after {
		content: "";
		position: absolute;
		inset: 0;
		z-index: 2;
		pointer-events: none;
		background: linear-gradient(
			120deg,
			rgba(255, 255, 255, 0.03) 0%,
			rgba(255, 255, 255, 0.24) 45%,
			rgba(86, 132, 255, 0.18) 55%,
			rgba(255, 255, 255, 0.03) 100%
		);
		opacity: 0.7;
		animation: easy-site-editor-stream-preview-pulse 1.6s ease-in-out infinite;
	}

	@keyframes easy-site-editor-stream-preview-pulse {
		0% {
			opacity: 0.18;
		}

		50% {
			opacity: 0.5;
		}

		100% {
			opacity: 0.18;
		}
	}

	@media ( prefers-reduced-motion: reduce ) {
		.${ PREVIEW_CLASS_NAME }::after {
			animation: none;
			opacity: 0.24;
		}
	}
`;

function injectPreviewStylesIntoDocument( targetDocument: Document | null ) {
	if (
		! targetDocument ||
		targetDocument.getElementById( PREVIEW_STYLES_ID )
	) {
		return;
	}

	const styleElement = targetDocument.createElement( 'style' );
	styleElement.id = PREVIEW_STYLES_ID;
	styleElement.textContent = PREVIEW_STYLES_CSS;

	targetDocument.head.appendChild( styleElement );
}

function ensurePreviewStyles(): void {
	injectPreviewStylesIntoDocument( document );

	document.querySelectorAll( 'iframe' ).forEach( ( iframe ) => {
		try {
			injectPreviewStylesIntoDocument( iframe.contentDocument );
		} catch {
			// Ignore cross-document access issues.
		}
	} );
}

/**
 * Progressive page-design renderer hook.
 *
 * Owns the incremental block-preview state machine and the throttle/flush/retry
 * orchestration. All editor reads/writes go through the supplied `host`, so the
 * hook stays surface-agnostic; the host carries every surface-specific decision
 * (sub-registry, undo strategy, checkpoint store, global styles).
 *
 * @param host           The editor-surface adapter.
 * @param opts           Options.
 * @param opts.onApplied Called whenever a flush stages something into the editor.
 */
export function useStreamPageDesignRenderer(
	host: EditorHost,
	{ onApplied }: { onApplied?: () => void }
) {
	const hostRef = useRef( host );
	hostRef.current = host;
	const onAppliedRef = useRef( onApplied );
	onAppliedRef.current = onApplied;

	// Full accumulated markup per tool call. Each tool call also has an
	// incremental render state, so an open top-level block can appear as a
	// temporary preview while its inner blocks continue streaming.
	const accumulatedMarkupRef = useRef< Map< string, string > >( new Map() );
	const renderStateRef = useRef< Map< string, ToolCallRenderState > >(
		new Map()
	);
	const lastRenderedCssRef = useRef< Map< string, string > >( new Map() );
	const flushTimerRef = useRef< ReturnType< typeof setTimeout > | null >(
		null
	);
	const flushRetryTimerRef = useRef< ReturnType< typeof setTimeout > | null >(
		null
	);
	const previewStylesIntervalRef = useRef< ReturnType<
		typeof setInterval
	> | null >( null );
	const pendingToolCallIdRef = useRef< string | null >( null );
	// Tool calls whose pre-redesign checkpoint has already been captured, so we
	// snapshot the page exactly once per stream (before its first mutation).
	const capturedToolCallsRef = useRef< Set< string > >( new Set() );

	// Stage blocks into the editor surface through the host, which owns the
	// surface's streaming/untracked undo mode. (ESE marks every streamed replace
	// with history:'ignore' so it syncs to the entity with undoIgnore:true and
	// creates no undo level; reverting a redesign is handled by the checkpoint/
	// restore system, not native undo.)
	const stageInnerBlocks = useCallback(
		(
			rootClientId: string,
			blocks: CreatedBlock[],
			updateSelection = false
		): void => {
			hostRef.current.stageBlocks(
				rootClientId,
				blocks,
				updateSelection
			);
		},
		[]
	);

	const getRenderState = useCallback(
		( toolCallId: string ): ToolCallRenderState => {
			const existingState = renderStateRef.current.get( toolCallId );

			if ( existingState ) {
				return existingState;
			}

			const nextState: ToolCallRenderState = {
				currentPreview: null,
				didReplaceInitialContent: false,
				lastPageContent: '',
				pendingPageBuffer: '',
				topLevelBlocks: [],
			};

			renderStateRef.current.set( toolCallId, nextState );
			return nextState;
		},
		[]
	);

	const placeTopLevelBlocks = useCallback(
		(
			state: ToolCallRenderState,
			postContentClientId: string,
			blocks: CreatedBlock[]
		): void => {
			if ( ! blocks.length ) {
				return;
			}

			if ( ! state.didReplaceInitialContent ) {
				// First generated block: replace existing page content in a
				// single op so the editor never falls back to an empty state.
				state.topLevelBlocks = blocks;
				stageInnerBlocks( postContentClientId, blocks, false );
				state.didReplaceInitialContent = true;
				return;
			}

			state.topLevelBlocks = [ ...state.topLevelBlocks, ...blocks ];
			stageInnerBlocks(
				postContentClientId,
				state.topLevelBlocks,
				false
			);
		},
		[ stageInnerBlocks ]
	);

	const syncPreviewChildren = useCallback(
		( previewState: PreviewState ): void => {
			stageInnerBlocks(
				previewState.clientId,
				previewState.childBlocks,
				false
			);
		},
		[ stageInnerBlocks ]
	);

	const startTopLevelPreview = useCallback(
		(
			state: ToolCallRenderState,
			postContentClientId: string,
			markup: string
		): PreviewState | null => {
			const trimmedMarkup = markup.replace( /^\s+/, '' );
			const commentEnd = trimmedMarkup.indexOf( '-->' );

			if ( commentEnd === -1 ) {
				return null;
			}

			const parsedComment = parseBlockComment(
				trimmedMarkup.slice( 0, commentEnd + 3 )
			);

			if ( ! parsedComment || parsedComment.isSelfClosing ) {
				return null;
			}

			const preview = createPreviewBlockFromOpenMarkup( trimmedMarkup );

			if ( ! preview ) {
				return null;
			}

			placeTopLevelBlocks( state, postContentClientId, [
				preview.block,
			] );

			return createPreviewState(
				preview.block.clientId,
				preview.markup,
				true
			);
		},
		[ placeTopLevelBlocks ]
	);

	const appendPreviewChildBlocks = useCallback(
		(
			previewState: PreviewState,
			blocks: CreatedBlock[]
		): string | null => {
			if ( ! blocks.length ) {
				return null;
			}

			previewState.childBlocks = [
				...previewState.childBlocks,
				...blocks,
			];
			syncPreviewChildren( previewState );

			return getLastContainerClientId( blocks );
		},
		[ syncPreviewChildren ]
	);

	const startChildPreview = useCallback(
		(
			parentPreview: PreviewState,
			markup: string
		): PreviewState | null => {
			const preview = createPreviewBlockFromOpenMarkup( markup );

			if ( ! preview ) {
				return null;
			}

			const childPreview = createPreviewState(
				preview.block.clientId,
				preview.markup,
				isLikelyContainerBlockName( preview.block.name )
			);

			parentPreview.childBlocks = [
				...parentPreview.childBlocks,
				preview.block,
			];
			syncPreviewChildren( parentPreview );

			return childPreview;
		},
		[ syncPreviewChildren ]
	);

	const finalizeChildPreview = useCallback(
		(
			parentPreview: PreviewState,
			childPreview: PreviewState,
			finalMarkup: string
		): string | null => {
			const previewBlockIndex = parentPreview.childBlocks.findIndex(
				( block ) => block.clientId === childPreview.clientId
			);

			if ( previewBlockIndex === -1 ) {
				return null;
			}

			const finalBlocks = repairBlocksFromMarkup( finalMarkup );
			if ( ! finalBlocks.length ) {
				parentPreview.childBlocks = parentPreview.childBlocks.filter(
					( block ) => block.clientId !== childPreview.clientId
				);
				syncPreviewChildren( parentPreview );
				return null;
			}

			parentPreview.childBlocks = [
				...parentPreview.childBlocks.slice( 0, previewBlockIndex ),
				...finalBlocks,
				...parentPreview.childBlocks.slice( previewBlockIndex + 1 ),
			];
			syncPreviewChildren( parentPreview );

			return getLastContainerClientId( finalBlocks );
		},
		[ syncPreviewChildren ]
	);

	const updateTopLevelPreview = useCallback(
		function updatePreviewRecursively(
			previewState: PreviewState,
			shouldScrollOnFirstContent = false,
			rootPreviewState = previewState
		): string | null {
			const innerMarkup = getPreviewInnerMarkup( previewState.markup );
			const newInnerMarkup = innerMarkup.startsWith(
				previewState.lastInnerMarkup
			)
				? innerMarkup.slice( previewState.lastInnerMarkup.length )
				: innerMarkup;

			previewState.lastInnerMarkup = innerMarkup;

			if ( newInnerMarkup ) {
				previewState.pendingInnerBuffer += newInnerMarkup;
			}

			let scrollTargetClientId: string | null = null;

			while ( previewState.pendingInnerBuffer.trim() ) {
				if ( previewState.currentChildPreview ) {
					previewState.currentChildPreview.markup +=
						previewState.pendingInnerBuffer;
					previewState.pendingInnerBuffer = '';

					const completedPreview = extractCompleteTopLevelBlock(
						previewState.currentChildPreview.markup
					);

					if ( completedPreview ) {
						scrollTargetClientId =
							getThrottledNestedContainerScrollTarget(
								rootPreviewState,
								finalizeChildPreview(
									previewState,
									previewState.currentChildPreview,
									completedPreview.blockMarkup
								)
							) || scrollTargetClientId;
						previewState.currentChildPreview = null;
						previewState.pendingInnerBuffer =
							completedPreview.remaining;
						continue;
					}

					scrollTargetClientId = updatePreviewRecursively(
						previewState.currentChildPreview,
						false,
						rootPreviewState
					);
					break;
				}

				const completedBlock = extractCompleteTopLevelBlock(
					previewState.pendingInnerBuffer
				);

				if ( completedBlock ) {
					const blocks = repairBlocksFromMarkup(
						completedBlock.blockMarkup
					);
					scrollTargetClientId =
						getThrottledNestedContainerScrollTarget(
							rootPreviewState,
							appendPreviewChildBlocks( previewState, blocks )
						) || scrollTargetClientId;
					previewState.pendingInnerBuffer = completedBlock.remaining;
					continue;
				}

				const childPreview = startChildPreview(
					previewState,
					previewState.pendingInnerBuffer
				);

				if ( childPreview ) {
					previewState.currentChildPreview = childPreview;
					previewState.pendingInnerBuffer = '';
					scrollTargetClientId =
						updatePreviewRecursively(
							childPreview,
							false,
							rootPreviewState
						) ||
						getPreviewContainerScrollTarget(
							rootPreviewState,
							childPreview
						);
					break;
				}

				break;
			}

			if (
				shouldScrollOnFirstContent &&
				! previewState.scrolledAfterFirstContent &&
				previewState.childBlocks.length > 0
			) {
				previewState.scrolledAfterFirstContent = true;
				return previewState.clientId;
			}

			if (
				! shouldScrollOnFirstContent &&
				! previewState.scrolledAfterFirstContent &&
				previewState.childBlocks.length > 0
			) {
				previewState.scrolledAfterFirstContent = true;
				return getPreviewContainerScrollTarget(
					rootPreviewState,
					previewState
				);
			}

			return scrollTargetClientId;
		},
		[ appendPreviewChildBlocks, finalizeChildPreview, startChildPreview ]
	);

	const finalizeTopLevelPreview = useCallback(
		(
			state: ToolCallRenderState,
			postContentClientId: string,
			previewState: PreviewState,
			finalMarkup: string
		): string | null => {
			const finalBlocks = repairBlocksFromMarkup( finalMarkup );
			const previewBlockIndex = state.topLevelBlocks.findIndex(
				( block ) => block.clientId === previewState.clientId
			);

			if ( ! finalBlocks.length ) {
				if ( previewBlockIndex !== -1 ) {
					state.topLevelBlocks = state.topLevelBlocks.filter(
						( block ) => block.clientId !== previewState.clientId
					);
					stageInnerBlocks(
						postContentClientId,
						state.topLevelBlocks,
						false
					);
				}
				return null;
			}

			if ( previewBlockIndex === -1 ) {
				state.topLevelBlocks = [
					...state.topLevelBlocks,
					...finalBlocks,
				];
			} else {
				state.topLevelBlocks = [
					...state.topLevelBlocks.slice( 0, previewBlockIndex ),
					...finalBlocks,
					...state.topLevelBlocks.slice( previewBlockIndex + 1 ),
				];
			}

			stageInnerBlocks(
				postContentClientId,
				state.topLevelBlocks,
				false
			);

			return (
				getDeepestLastClientId( finalBlocks ) || previewState.clientId
			);
		},
		[ stageInnerBlocks ]
	);

	const processPageBuffer = useCallback(
		(
			state: ToolCallRenderState,
			postContentClientId: string
		): string | null => {
			let scrollTargetClientId: string | null = null;

			while ( state.pendingPageBuffer.trim() ) {
				if ( state.currentPreview ) {
					state.currentPreview.markup += state.pendingPageBuffer;
					state.pendingPageBuffer = '';

					const completedPreview = extractCompleteTopLevelBlock(
						state.currentPreview.markup
					);

					if ( completedPreview ) {
						finalizeTopLevelPreview(
							state,
							postContentClientId,
							state.currentPreview,
							completedPreview.blockMarkup
						);
						state.currentPreview = null;
						state.pendingPageBuffer = completedPreview.remaining;
						continue;
					}

					scrollTargetClientId =
						updateTopLevelPreview( state.currentPreview, true ) ||
						scrollTargetClientId;
					break;
				}

				const completedTopLevelBlock = extractCompleteTopLevelBlock(
					state.pendingPageBuffer
				);

				if ( completedTopLevelBlock ) {
					const blocks = repairBlocksFromMarkup(
						completedTopLevelBlock.blockMarkup
					);
					placeTopLevelBlocks( state, postContentClientId, blocks );
					scrollTargetClientId =
						blocks[ blocks.length - 1 ]?.clientId ||
						scrollTargetClientId;
					state.pendingPageBuffer = completedTopLevelBlock.remaining;
					continue;
				}

				const previewState = startTopLevelPreview(
					state,
					postContentClientId,
					state.pendingPageBuffer
				);

				if ( previewState ) {
					state.currentPreview = previewState;
					state.pendingPageBuffer = '';
					scrollTargetClientId =
						updateTopLevelPreview( state.currentPreview, true ) ||
						previewState.clientId;
					break;
				}

				break;
			}

			return scrollTargetClientId;
		},
		[
			finalizeTopLevelPreview,
			placeTopLevelBlocks,
			startTopLevelPreview,
			updateTopLevelPreview,
		]
	);

	// The clientId to stage top-level page blocks into (ESE: core/post-content),
	// or null when the canvas/target is not ready yet. A non-null return is the
	// renderer's "canvas is ready" signal.
	const getPostContentClientId = useCallback(
		(): string | null => hostRef.current.resolveTargetRoot(),
		[]
	);

	// Apply new page-section markup to the editor. Open top-level blocks are
	// inserted immediately as temporary preview blocks, their completed child
	// blocks are refreshed in place, and the preview block is replaced with the
	// final repaired block when the real closing tag arrives.
	const flush = useCallback(
		( toolCallId: string, isFinal: boolean ): boolean => {
			const markup = accumulatedMarkupRef.current.get( toolCallId ) || '';
			const postContentClientId = getPostContentClientId();

			if ( ! postContentClientId ) {
				return false;
			}

			// Snapshot the page BEFORE the redesign mutates it (the post-content
			// block is now mounted and nothing has been staged yet for this tool
			// call), so the surface can revert the whole redesign via its
			// checkpoint/restore system.
			if ( ! capturedToolCallsRef.current.has( toolCallId ) ) {
				capturedToolCallsRef.current.add( toolCallId );
				hostRef.current.captureCheckpoint( toolCallId, {
					toolId: STREAM_PAGE_DESIGN_TOOL_ID,
					summary: 'Page design',
				} );
			}

			let didStage = false;

			const pageSection = extractSection( markup, 'page' );
			if ( pageSection ) {
				const state = getRenderState( toolCallId );
				const nextPageContent = pageSection.content;
				const newPageContent = nextPageContent.startsWith(
					state.lastPageContent
				)
					? nextPageContent.slice( state.lastPageContent.length )
					: nextPageContent;

				state.lastPageContent = nextPageContent;

				if ( newPageContent ) {
					state.pendingPageBuffer += newPageContent;
					const scrollTargetClientId = processPageBuffer(
						state,
						postContentClientId
					);

					if ( scrollTargetClientId ) {
						scrollToBlockBottom( scrollTargetClientId );
						didStage = true;
					}
				}
			}

			// TEMP (page designs → theme styling only): when APPLY_GENERATED_CSS
			// is off the style section is never read, so no generated CSS reaches
			// global styles — neither the streaming preview (applyCustomCss below)
			// nor the final tracked commit (finalCSS stays null, so
			// commitFinalDesign folds no CSS into the undo level).
			const styleSection = APPLY_GENERATED_CSS
				? extractSection( markup, 'style' )
				: null;
			let finalCSS: string | null = null;
			if ( styleSection && ( isFinal || styleSection.complete ) ) {
				const css = stripStyleTags( styleSection.content );
				if ( css ) {
					finalCSS = css;
					// During streaming, stage CSS untracked for live preview. On
					// the final flush the commit below re-applies it as a tracked
					// edit instead, so it reverts with the blocks in one undo.
					if (
						! isFinal &&
						lastRenderedCssRef.current.get( toolCallId ) !== css
					) {
						// Mark as staged optimistically so concurrent flushes
						// don't re-stage the same CSS, but roll the cache back if
						// staging fails so a later flush retries instead of
						// leaving the CSS permanently marked as applied.
						lastRenderedCssRef.current.set( toolCallId, css );
						void hostRef.current
							.applyCustomCss( css )
							.catch( () => {
								if (
									lastRenderedCssRef.current.get(
										toolCallId
									) === css
								) {
									lastRenderedCssRef.current.delete(
										toolCallId
									);
								}
							} );
						didStage = true;
					}
				}
			}

			// On completion, fold the whole redesign into a single native undo
			// level (blocks + CSS) so the undo/redo buttons revert it in one step.
			if ( isFinal ) {
				hostRef.current.commitFinalDesign(
					toolCallId,
					postContentClientId,
					finalCSS
				);
				didStage = true;
			}

			return didStage;
		},
		[ getPostContentClientId, getRenderState, processPageBuffer ]
	);

	// Flushes, retrying across a few flush intervals while the post-content
	// block has not mounted yet. Without this, markup that arrives (or replays)
	// before the editor canvas is ready would flush once, stage nothing, and be
	// dropped — there is no further delta to trigger a re-flush once the stream
	// has ended.
	const flushOrRetry = useCallback(
		function attempt(
			toolCallId: string,
			isFinal: boolean,
			attemptsLeft = MAX_FLUSH_RETRIES
		): void {
			if ( ! getPostContentClientId() && attemptsLeft > 0 ) {
				if ( flushRetryTimerRef.current ) {
					clearTimeout( flushRetryTimerRef.current );
				}
				flushRetryTimerRef.current = setTimeout( () => {
					flushRetryTimerRef.current = null;
					attempt( toolCallId, isFinal, attemptsLeft - 1 );
				}, FLUSH_INTERVAL_MS );
				return;
			}

			if ( flush( toolCallId, isFinal ) ) {
				onAppliedRef.current?.();
			}
		},
		[ flush, getPostContentClientId ]
	);

	const stageStreamPageDesign = useCallback< StreamPageDesignHandler >(
		( update: StreamPageDesignUpdate ) => {
			accumulatedMarkupRef.current.set(
				update.toolCallId,
				update.markup
			);
			pendingToolCallIdRef.current = update.toolCallId;

			const result = {
				result: {
					success: true,
					message:
						'The generated page content has been staged in the editor for review.',
				},
				returnToAgent: false,
			};

			if ( update.isFinal ) {
				// The finalized design has no preview blocks, so the preview-only
				// styles are no longer needed — stop the upkeep interval.
				if ( previewStylesIntervalRef.current ) {
					window.clearInterval( previewStylesIntervalRef.current );
					previewStylesIntervalRef.current = null;
				}
				if ( flushTimerRef.current ) {
					clearTimeout( flushTimerRef.current );
					flushTimerRef.current = null;
				}
				flushOrRetry( update.toolCallId, true );
				return result;
			}

			// While a design is actively streaming, keep the preview-only styles
			// injected — including into the editor canvas iframe, which can mount
			// mid-stream — rather than polling for the hook's entire lifetime.
			if ( ! previewStylesIntervalRef.current ) {
				ensurePreviewStyles();
				previewStylesIntervalRef.current = window.setInterval(
					ensurePreviewStyles,
					1000
				);
			}

			// Throttle intermediate renders so the main thread stays free for
			// the editor to mount and we don't re-render on every tiny delta.
			if ( ! flushTimerRef.current ) {
				flushTimerRef.current = setTimeout( () => {
					flushTimerRef.current = null;
					const toolCallId = pendingToolCallIdRef.current;
					if ( toolCallId ) {
						flushOrRetry( toolCallId, false );
					}
				}, FLUSH_INTERVAL_MS );
			}

			return result;
		},
		[ flushOrRetry ]
	);

	useEffect( () => {
		setStreamPageDesignHandler( stageStreamPageDesign );

		return () => {
			setStreamPageDesignHandler( null );
			if ( flushTimerRef.current ) {
				clearTimeout( flushTimerRef.current );
				flushTimerRef.current = null;
			}
			if ( flushRetryTimerRef.current ) {
				clearTimeout( flushRetryTimerRef.current );
				flushRetryTimerRef.current = null;
			}
			if ( previewStylesIntervalRef.current ) {
				window.clearInterval( previewStylesIntervalRef.current );
				previewStylesIntervalRef.current = null;
			}
		};
	}, [ stageStreamPageDesign ] );
}
