/**
 * WordPress dependencies
 */
import { useDispatch } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import useLog from '@hooks/use-log';

/**
 * Creates a formatted suggestion action object
 *
 * @param {Object} action The action to format
 * @return {Object} Formatted action object
 */
export function formatSuggestionAction( action ) {
	return {
		key: action.key || action.actionName || action,
		actionName: action.actionName || action,
		description: action.description || '',
		type: action.type,
	};
}

export function createSuggestionClickHandler( {
	logUserChoice,
	clearSuggestions,
	setHasRetried,
	respond,
	userSay,
	action,
	shouldClear = true,
} ) {
	return () => {
		const responseMessage = () => {
			if ( action?.message ) {
				return action.message;
			}

			return action.actionName && action.description
				? `${ action.actionName } - ${ action.description }`
				: action.description || action.actionName || action;
		};

		const message = responseMessage();
		logUserChoice( message );
		setHasRetried( false );

		if ( shouldClear ) {
			clearSuggestions();
		}

		if ( respond ) {
			respond( message );
		} else {
			userSay( message );
		}
	};
}

/**
 * Hook for suggestion management
 *
 * @return {Object} Suggestion management utilities
 */
export function useSuggestionManagement() {
	const { clearSuggestions, setHasRetriedChatRequest } =
		useDispatch( aiStore );
	const { logUserChoice } = useLog();

	return {
		clearSuggestions,
		setHasRetriedChatRequest,
		logUserChoice,
	};
}
