/**
 * External dependencies
 */
import { ImageUploader } from '@automattic/agenttic-ui';

/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import {
	useCallback,
	useEffect,
	useMemo,
	useRef,
	useState,
} from '@wordpress/element';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import ThinkingMessage from '@components/thinking-message';
import useAnalyzeImage from '@ai/tasks/analyze-image/use-analyze-image';
import useBlocks from '@hooks/use-blocks';
import useLog from '@hooks/use-log';
import useUploadMedia from '@hooks/use-upload-media';
import { recordTracksEvent } from '@utils/tracks';

const maxUploadFileSize = window.bigSkyInitialState?.maxUploadSize || 2097152; // 2MB

/**
 * BigSky-specific wrapper for the ImageUploader component from agenttic-ui.
 * This component handles all WordPress/BigSky-specific upload logic while using
 * the generic ImageUploader component for the UI.
 *
 * @param {Object} root0               - Component props.
 * @param {Array}  root0.preloadImages - Array of images to preload into the uploader (e.g., previously uploaded)
 */
const BigSkyImageUploader = ( { preloadImages = [] } ) => {
	const { setDraggedImageFile, setInputtedFiles, setHideImageUploader } =
		useDispatch( aiStore );
	const { analyzeImage } = useAnalyzeImage();

	// Use separate useSelect calls for referential stability
	const uploadedImages = useSelect(
		( select ) => select( aiStore ).getUploadedImages(),
		[]
	);
	const { isDraggingOver, hideImageUploader } = useSelect(
		( select ) => ( {
			isDraggingOver: select( aiStore ).getIsDraggingOver(),
			hideImageUploader: select( aiStore ).getHideImageUploader(),
		} ),
		[]
	);

	const { getRootBlocks } = useBlocks();
	const processedPreloadImagesRef = useRef( new Set() );
	const { logAction, logError } = useLog();
	const { uploadImage } = useUploadMedia();

	const [ isUploading, setIsUploading ] = useState( false );
	const [ uploadingFiles, setUploadingFiles ] = useState( [] );
	const [ isDraggingFiles, setIsDraggingFiles ] = useState( false );

	// Detect when files are being dragged from outside (e.g., from computer)
	useEffect( () => {
		let dragCounter = 0;

		const handleDragEnter = ( e ) => {
			// Check if dragging files (not dragging an uploaded image)
			if ( e.dataTransfer?.types?.includes( 'Files' ) ) {
				dragCounter++;
				setIsDraggingFiles( true );
			}
		};

		const handleDragLeave = () => {
			dragCounter--;
			// Only hide if drag counter reaches 0 (left all drop zones)
			if ( dragCounter === 0 ) {
				setIsDraggingFiles( false );
			}
		};

		const handleDrop = () => {
			dragCounter = 0;
			setIsDraggingFiles( false );
		};

		const handleDragEnd = () => {
			dragCounter = 0;
			setIsDraggingFiles( false );
		};

		window.addEventListener( 'dragenter', handleDragEnter );
		window.addEventListener( 'dragleave', handleDragLeave );
		window.addEventListener( 'drop', handleDrop );
		window.addEventListener( 'dragend', handleDragEnd );

		return () => {
			window.removeEventListener( 'dragenter', handleDragEnter );
			window.removeEventListener( 'dragleave', handleDragLeave );
			window.removeEventListener( 'drop', handleDrop );
			window.removeEventListener( 'dragend', handleDragEnd );
		};
	}, [] );

	// Reset hideImageUploader when dragging
	useEffect( () => {
		if ( isDraggingOver || isDraggingFiles ) {
			setHideImageUploader( false );
		}
	}, [ isDraggingOver, isDraggingFiles, setHideImageUploader ] );

	// Update global store if there are preloaded images (only once per image)
	useEffect( () => {
		if ( preloadImages.length > 0 ) {
			const currentImages = uploadedImages;
			const newPreloadImages = preloadImages.filter(
				( image ) =>
					! processedPreloadImagesRef.current.has( image.url )
			);

			if ( newPreloadImages.length > 0 ) {
				const combinedImages = [
					...currentImages,
					...newPreloadImages,
				];
				const uniqueImages = combinedImages.filter(
					( image, index, self ) =>
						index === self.findIndex( ( t ) => t.url === image.url )
				);
				setInputtedFiles( uniqueImages );

				// Mark these images as processed
				newPreloadImages.forEach( ( image ) => {
					processedPreloadImagesRef.current.add( image.url );
				} );
			}
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [] );

	const handleFiles = useCallback(
		async ( files ) => {
			if ( ! files || files.length === 0 ) {
				return;
			}

			setHideImageUploader( false );
			setIsUploading( true );
			// Add files to uploading state
			setUploadingFiles(
				Array.from( files ).map( ( file ) => ( {
					id: file.name,
					file,
				} ) )
			);

			try {
				// Process all files concurrently using the shared upload utility
				const uploadPromises = Array.from( files ).map(
					( fileToUpload ) => uploadImage( fileToUpload )
				);

				// Wait for all uploads to complete
				const results = await Promise.allSettled( uploadPromises );

				// Process successful uploads
				const successfulUploads = results
					.filter( ( result ) => result.status === 'fulfilled' )
					.map( ( result ) => result.value )
					.flat(); // Flatten the array since each upload returns an array

				// Process failed uploads
				const failedUploads = results
					.filter( ( result ) => result.status === 'rejected' )
					.map( ( result ) => result.reason );

				// Log any failed uploads
				if ( failedUploads.length > 0 ) {
					failedUploads.forEach( ( error ) => {
						logError( error );
					} );
				}

				// Update state with successful uploads
				if ( successfulUploads.length > 0 ) {
					const currentImages = uploadedImages;

					// Filter out any duplicates based on URL and add new uploads
					const newImages = successfulUploads.filter(
						( uploadedImage ) =>
							! currentImages.some(
								( existingImage ) =>
									existingImage.url === uploadedImage.url
							)
					);

					if ( newImages.length > 0 ) {
						const updatedImages = [
							...currentImages,
							...newImages,
						];
						setInputtedFiles( updatedImages );

						// Track successful image uploads
						recordTracksEvent( 'file_upload_success', {
							count: newImages.length,
						} );
					}
				}
			} catch ( error ) {
				logError( error );
			} finally {
				setIsUploading( false );
				setUploadingFiles( [] );
			}
		},
		// eslint-disable-next-line react-hooks/exhaustive-deps
		[ setInputtedFiles, analyzeImage, getRootBlocks, logAction, logError ]
	);

	const handleDragStart = ( image ) => {
		setDraggedImageFile( image );
		recordTracksEvent( 'file_upload_drag_start' );
	};

	const handleDragEnd = () => {
		setDraggedImageFile( null );
	};

	const handleRemoveImage = useCallback(
		( imageToRemove ) => {
			const updatedFiles = uploadedImages.filter(
				( file ) => file.id !== imageToRemove.id
			);
			setInputtedFiles( updatedFiles );

			// Track image removal
			recordTracksEvent( 'file_upload_remove', {
				image_id: imageToRemove.id,
			} );

			if ( updatedFiles.length === 0 ) {
				setHideImageUploader( true );
				// Reset dragging state when removing the last image
				setIsDraggingFiles( false );
			}
		},
		[ uploadedImages, setHideImageUploader, setInputtedFiles ]
	);

	const handleError = useCallback(
		( error ) => {
			logError( error );
			recordTracksEvent( 'file_upload_invalid' );
		},
		[ logError ]
	);

	// Determine if the component should be visible
	const shouldShowComponent = useMemo( () => {
		// Don't show when hideImageUploader is true (unless dragging)
		if ( hideImageUploader && ! isDraggingOver && ! isDraggingFiles ) {
			return false;
		}

		// Always show if any of these conditions are true:
		// - User is dragging over the area (uploaded images)
		// - User is dragging files from outside
		// - There are uploaded images to display
		// - Currently uploading files
		return (
			isDraggingOver ||
			isDraggingFiles ||
			uploadedImages.length > 0 ||
			isUploading
		);
	}, [
		hideImageUploader,
		isDraggingOver,
		isDraggingFiles,
		uploadedImages.length,
		isUploading,
	] );

	// Handle browse (click) events
	const handleBrowse = useCallback( ( files ) => {
		recordTracksEvent( 'file_upload_click', {
			count: files.length,
		} );
	}, [] );

	// Handle drag and drop events
	const handleDrop = useCallback( ( files ) => {
		recordTracksEvent( 'file_upload_drop', {
			count: files.length,
		} );
	}, [] );

	// Handle general file selection (still needed for upload logic)
	const handleFilesSelected = useCallback(
		( files ) => {
			handleFiles( files );
		},
		[ handleFiles ]
	);

	return (
		<ImageUploader
			images={ uploadedImages }
			uploadingImages={ uploadingFiles }
			onFilesSelected={ handleFilesSelected }
			onBrowse={ handleBrowse }
			onDrop={ handleDrop }
			onRemoveImage={ handleRemoveImage }
			onImageDragStart={ handleDragStart }
			onImageDragEnd={ handleDragEnd }
			acceptedFileTypes={ [
				'image/jpeg',
				'image/png',
				'image/heic',
				'image/heif',
				'image/heic-sequence',
				'image/heif-sequence',
			] }
			maxFileSize={ maxUploadFileSize }
			uploadingIndicator={
				<div
					style={ {
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'center',
						width: '100%',
						height: '100%',
					} }
				>
					<ThinkingMessage />
				</div>
			}
			showFileMetadata={ true }
			allowDragToInsert={ true }
			onError={ handleError }
			visible={ shouldShowComponent }
		/>
	);
};

export default BigSkyImageUploader;
