import ColorVariationPicker from '@components/color-variation-picker';
import { useDispatch, useSelect } from '@wordpress/data';
import { store as aiStore } from '@store';
import useSiteMetadata from '@hooks/use-site-metadata';
import useStyles from '@hooks/use-styles';
import { memo, useEffect, useState } from '@wordpress/element';

enum PaletteType {
	Bold = 'Bold',
	BoldText = 'BoldText',
	BoldDark = 'BoldDark',
	Sophisticated = 'Sophisticated',
	SophisticatedDark = 'SophisticatedDark',
	Playful = 'Playful',
	PlayfulQuirky = 'PlayfulQuirky',
	Pastel = 'Pastel',
}

interface PaletteColor {
	color: string;
	name: string;
	slug: string;
}

interface ColorSettings {
	background?: string;
	text?: string;
}

interface ButtonElementColor {
	color: ColorSettings;
	':hover': {
		color: ColorSettings;
	};
}

interface VariationStyle {
	color?: ColorSettings;
	elements?: {
		button?: ButtonElementColor;
	};
}

interface ThemeSettings {
	color?: {
		palette?: {
			theme?: PaletteColor[];
		};
	};
}

interface ThemeStyles {
	color?: ColorSettings;
	blocks?: Record<
		string,
		{ variations?: Record< string, VariationStyle > }
	>;
}

interface Theme {
	settings?: ThemeSettings;
	styles?: ThemeStyles;
}

interface ColorVariation {
	title: string;
	settings: ThemeSettings;
	styles: ThemeStyles;
	label: string;
	paletteType: string;
}

interface CreateCurrentColorVariationParams {
	colorVariations: ColorVariation[];
	currentColorMeta: string | null;
	customVariationTemplates: Theme[];
	getCurrentPaletteColors: () => PaletteColor[];
	getCurrentTheme: () => Theme | null;
}

interface PrependCurrentColorVariationParams {
	colorVariations: ColorVariation[];
	getCurrentColor: () => string | null;
	getSiteMetadata: () => { currentColor?: string };
	setCurrentColor: ( color: string ) => void;
	getCurrentPaletteColors: () => PaletteColor[];
	getCurrentTheme: () => Theme | null;
	customVariationTemplates: Theme[];
}

interface ColorPaletteProps {
	personality: string;
	paletteType: string;
	topic: string;
	hues: Array< Array< { h: number; s: number; l: number } > >;
	description: string;
	specificColors: string[];
	variations: ColorVariation[];
	customVariationTemplates: Theme[];
}

const createCurrentColorVariation = ( {
	colorVariations,
	currentColorMeta: currentVariation,
	customVariationTemplates,
	getCurrentPaletteColors,
	getCurrentTheme,
}: CreateCurrentColorVariationParams ): ColorVariation | null => {
	if ( ! currentVariation ) {
		return null;
	}

	const currentColorExists = colorVariations.some(
		( variation ) => variation.title === currentVariation
	);
	if ( currentColorExists ) {
		return null;
	}

	const currentPaletteColors = getCurrentPaletteColors();
	const currentTheme = getCurrentTheme();

	if (
		! currentPaletteColors?.length ||
		! currentTheme ||
		! customVariationTemplates?.length
	) {
		return null;
	}

	// if the current variation is like this:
	// AI Website Builder Custom BoldText - 000000-000080-0E0F12-EEEFF3-FFFFFF
	// we need to get the palette type from the currentVariation, in this example it's BoldText
	// the palette type is the first word before the first dash
	let paletteType: string | null = null;
	if ( currentVariation.includes( ' - ' ) ) {
		const parts = currentVariation.split( ' - ' );
		if ( parts.length >= 2 ) {
			const beforeDash = parts[ 0 ];
			// Split by spaces and get the last word before the dash
			const words = beforeDash.split( ' ' );
			if ( words.length > 0 ) {
				paletteType = words[ words.length - 1 ];
			}
		}
	}

	const currentThemeCopy: Theme = JSON.parse(
		JSON.stringify( currentTheme )
	);
	const templateTheme: Theme = JSON.parse(
		JSON.stringify( customVariationTemplates[ 0 ] )
	);
	const styles = currentThemeCopy.styles?.color
		? currentThemeCopy.styles
		: templateTheme.styles;

	return {
		title: currentVariation,
		settings: {
			color: {
				palette: {
					theme: currentPaletteColors,
				},
			},
		},
		styles: styles || {},
		label: currentVariation,
		paletteType: paletteType || PaletteType.Bold,
	};
};

const prependCurrentColorVariation = ( {
	colorVariations,
	getCurrentColor,
	getSiteMetadata,
	setCurrentColor,
	getCurrentPaletteColors,
	getCurrentTheme,
	customVariationTemplates,
}: PrependCurrentColorVariationParams ): ColorVariation[] => {
	// Get the current color value dynamically instead of using captured value
	const currentColorValue =
		getCurrentColor() || getSiteMetadata().currentColor;
	// Create current color palette variation if it doesn't exist
	// colorVariations,
	const currentColorVariation = createCurrentColorVariation( {
		colorVariations,
		currentColorMeta: currentColorValue || null,
		customVariationTemplates,
		getCurrentPaletteColors,
		getCurrentTheme,
	} );

	// Ensure the current color is set in site metadata
	if (
		currentColorVariation &&
		currentColorValue !== currentColorVariation.title
	) {
		setCurrentColor( currentColorVariation.title );
	}

	return currentColorVariation
		? [ currentColorVariation, ...colorVariations ]
		: colorVariations;
};

const ColorPalette = ( parameters: ColorPaletteProps ): JSX.Element | null => {
	const { getSiteMetadata, setCurrentColor } = useSiteMetadata();
	const { getCurrentColor, getCurrentPaletteColors } = useSelect(
		( select ) => select( aiStore ),
		[]
	);
	const { getCurrentTheme } = useStyles();
	const { pushGeneratedVariations } = useDispatch( aiStore );

	const [ colorVariations, setColorVariations ] = useState<
		ColorVariation[]
	>( [] );
	useEffect( () => {
		const variations = prependCurrentColorVariation( {
			colorVariations: parameters.variations,
			getCurrentColor,
			getSiteMetadata,
			setCurrentColor,
			getCurrentPaletteColors,
			getCurrentTheme,
			customVariationTemplates: parameters.customVariationTemplates,
		} );

		setColorVariations( variations );
		pushGeneratedVariations( variations );
		// Disabling linting here. There are two reasons:
		// * It works, since the component is a one-off color palette.
		// * Adding setCurrentColor as dependency causes re-renders and fixing that is a bigger refactor, out of the scope of adding the color palette.
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [] );

	if ( colorVariations.length === 0 ) {
		return null;
	}

	return (
		<ColorVariationPicker
			colorVariations={ colorVariations }
			maxColorsToShow={ 4 }
			key="color-picker"
		/>
	);
};

export default memo( ColorPalette );
