/**
 * WordPress dependencies
 */
import { useDispatch, useRegistry } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { serialize } from '@wordpress/blocks';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import useNavigation from '@hooks/use-navigation';
import { recreateBlock } from '@utils/block-utils';
import { store as aiStore } from '@store';

export default function useAddPagesTool() {
	const registry = useRegistry();
	const { addNavigationItems } = useNavigation();
	const { saveEntityRecord } = useDispatch( coreStore );
	const { setPendingPageImageProcessing } = useDispatch( aiStore );

	const updateNavigationMenu = async (
		navigationMenuId: number | string | undefined,
		results: Array< {
			success: boolean;
			page?: any;
			name: string;
			id?: number;
			url?: string;
			error?: string;
		} >
	) => {
		let navigationMenu = null;
		if ( navigationMenuId ) {
			// Get navigation menu if provided
			navigationMenu = await registry
				.resolveSelect( coreStore )
				.getEditedEntityRecord(
					'postType',
					'wp_navigation',
					navigationMenuId
				);
		}

		if ( ! navigationMenu ) {
			console.warn( '⚠️ No navigation menu found to update' );
			return;
		}

		// Prepare navigation items for all successfully created pages and links
		const navigationItems = results
			.filter( ( result ) => result.success )
			.map( ( result ) => {
				// If result has a url property but no page, it's a link-only item (no page created)
				if ( result.url && ! result.page ) {
					return {
						label: result.name,
						type: 'custom',
						url: result.url,
					};
				}
				// Otherwise, it's a created page
				return {
					label: result.page.title?.rendered || result.name,
					type: 'page',
					id: result.page.id,
					url: result.page.link,
					kind: 'post-type',
				};
			} );

		// Add all navigation items in one go
		try {
			await addNavigationItems( navigationItems, navigationMenu );
		} catch ( navError ) {
			console.warn( '⚠️ Could not update navigation:', navError );
		}
	};

	const addPagesCallback = async ( args: {
		pages: Array< {
			name: string;
			slug: string;
			path?: string;
			layouts?: Array< {
				patterns?: Array< {
					blocks?: any[];
				} >;
			} >;
		} >;
		navigationMenuId?: number | string;
	} ) => {
		const { pages, navigationMenuId } = args || {};

		// Validate pages input
		if ( ! pages || ! Array.isArray( pages ) || pages.length === 0 ) {
			return {
				result: __(
					'Invalid pages. Must provide an array of page objects.',
					'big-sky'
				),
				returnToAgent: true,
			};
		}

		try {
			const pagesWithBlocks: Array< {
				pageId: number;
				blocks: any[];
				pageName: string;
			} > = [];

			// Create pages in parallel
			const createPagePromises = pages.map( async ( page, index ) => {
				try {
					// If page has a path property, skip page creation and just return a link result
					if ( page.path ) {
						return {
							success: true,
							name: page.name,
							url: page.path,
						};
					}

					const layoutPatterns = page.layouts?.[ 0 ]?.patterns || [];

					const layoutBlocks = layoutPatterns.flatMap(
						( pattern ) =>
							pattern.blocks?.map( recreateBlock ) || []
					);

					// 2. Serialize blocks to HTML
					const pageContent = serialize( layoutBlocks );

					// 3. Create the page
					const newPage = await saveEntityRecord(
						'postType',
						'page',
						{
							status: 'publish',
							title: page.name,
							content: pageContent,
							slug: page.slug,
							menu_order: index + 1,
							meta: {
								big_sky_generated: true,
							},
						},
						{ throwOnError: true }
					);

					pagesWithBlocks.push( {
						pageId: newPage.id,
						blocks: layoutBlocks,
						pageName: page.name,
					} );

					return {
						success: true,
						page: newPage,
						name: page.name,
						id: newPage.id,
					};
				} catch ( error: any ) {
					console.error(
						`❌ Error creating page "${ page.name }":`,
						error,
						{
							errorMessage: error.message,
							errorStack: error.stack,
							pageData: page,
						}
					);
					return {
						success: false,
						name: page.name,
						error: error.message,
					};
				}
			} );

			// Wait for all pages to be created
			const results = await Promise.all( createPagePromises );

			// Update the navigation menu with the new pages
			await updateNavigationMenu( navigationMenuId, results );

			// Store pages for later image processing (after workflow completes)
			// This allows the workflow to generate and cache images first,
			// which can then be reused for the new pages
			if ( pagesWithBlocks.length > 0 ) {
				setPendingPageImageProcessing( pagesWithBlocks );
			}

			// Summarize results
			const successful = results.filter( ( r ) => r.success );
			const failed = results.filter( ( r ) => ! r.success );
			const createdPages = successful.filter( ( r ) => r.page );
			const addedLinks = successful.filter( ( r ) => r.url && ! r.page );

			console.log( '📊 Page creation summary:', {
				total: pages.length,
				successful: successful.length,
				failed: failed.length,
				createdPages: createdPages.length,
				addedLinks: addedLinks.length,
				results,
			} );

			let resultMessage = '';
			if ( createdPages.length > 0 ) {
				resultMessage += `Successfully created ${
					createdPages.length
				} page(s): ${ createdPages
					.map( ( r ) => r.name )
					.join( ', ' ) }. `;
			}
			if ( addedLinks.length > 0 ) {
				resultMessage += `Added ${
					addedLinks.length
				} navigation link(s): ${ addedLinks
					.map( ( r ) => r.name )
					.join( ', ' ) }. `;
			}
			if ( failed.length > 0 ) {
				resultMessage += `Failed to create ${
					failed.length
				} page(s): ${ failed
					.map( ( r ) => `${ r.name } (${ r.error })` )
					.join( ', ' ) }.`;
			}

			return {
				result: resultMessage,
				returnToAgent: true,
			};
		} catch ( error: any ) {
			console.error( '❌ Error in add_pages tool:', error );
			return {
				result:
					__( 'Failed to create pages:', 'big-sky' ) + error.message,
				returnToAgent: true,
			};
		}
	};

	return {
		addPages: addPagesCallback,
	};
}
