/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Navigate ability callback type
 */
export type NavigateCallback = ( args: {
	path: string;
	refresh_navigation?: boolean;
	summary?: string;
	followUpTasks?: boolean;
} ) => Promise< {
	result: {
		success: boolean;
		message: string;
		error?: string;
		details?: unknown;
	};
	returnToAgent: boolean;
} >;

/**
 * Navigate ability
 *
 * Saves everything and navigates to the specified path.
 *
 * @param callback - The navigate callback function from the hook
 * @return The navigate ability definition
 */
export const editorNavigateAbility = (
	callback: NavigateCallback
): Ability => ( {
	name: 'big-sky/editor-navigate',
	label: __( 'Navigate', 'big-sky' ),
	category: 'big-sky',
	description:
		'Saves everything and navigates to the specified path in the editor. For page navigation, path must be a numeric editor path like "/page/123" or "page/123"; full URLs, slugs, "all-pages", and paths like "/visit" or "/page/visit" are invalid. If the user names a page and the current page is not the target, look up the numeric id from <site_pages> first, then navigate with the numeric editor path.',
	input_schema: {
		type: 'object',
		properties: {
			path: {
				type: 'string',
				pattern: '^/?page/[0-9]+/?$',
				description:
					'The editor path to navigate to. Valid values are numeric page paths like "/page/123" or "page/123". Invalid: full URLs, slugs, "all-pages", "/visit", "/page/visit". If the user names a page, look up the numeric id from <site_pages> first to get the numeric editor path.',
			},
			refresh_navigation: {
				type: 'boolean',
				description:
					'Set to true when navigation blocks on the destination page should be refreshed after navigation, for example after creating a new page and adding it to the navigation menu.',
			},
			summary: {
				type: 'string',
				description:
					"A short, friendly confirmation in the agent's own voice to show to the user after navigation completes.",
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Deprecated. This tool always returns to the agent with a success or error message.',
			},
		},
		required: [ 'path' ],
		additionalProperties: false,
	},
	output_schema: {
		type: 'object',
		properties: {
			result: {
				type: 'object',
				properties: {
					success: {
						type: 'boolean',
						description:
							'Whether navigation completed successfully.',
					},
					message: {
						type: 'string',
						description: 'Human-readable success or error message.',
					},
					error: {
						type: 'string',
						description: 'Error details when success is false.',
					},
					details: {
						type: 'object',
						description:
							'Optional details about the navigation target.',
					},
				},
				required: [ 'success', 'message' ],
			},
			returnToAgent: {
				type: 'boolean',
			},
		},
		required: [ 'result', 'returnToAgent' ],
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
