/**
 * WordPress dependencies
 */
import { useCallback, useMemo, useRef } from '@wordpress/element';
import { useDispatch, useRegistry, useSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';
import { store as editorStore } from '@wordpress/editor';

/**
 * Internal dependencies
 */
import { setStyleValue as setStyle } from '@utils/global-styles';
import useBlocks from '@hooks/use-blocks';
import useCheckpoint from '@hooks/use-checkpoint';
import {
	type CreatedBlock,
	type EditorBlock,
	type EditorHost,
	useStreamPageDesignRenderer,
} from '@shared/stream-page-design-core/renderer';
import {
	type CommitAdapters,
	commitStreamedPageDesign,
} from '@shared/stream-page-design-core/commit-final-design';
import { findPostContentBlock } from '@shared/stream-page-design-core/serialize-post-content';
import { checkpointKeys } from '@utils/constants';
import {
	DOCUMENT_ROOT,
	resolvePageDesignTargetRoot,
} from './resolve-target-root';

// Pre-redesign snapshot per toolCallId: the undo baseline for the single
// native undo level. Captured host-locally (NOT read back out of the aiStore
// checkpoint) so undo correctness does not depend on the aiStore capture's
// section-root assumptions matching the stream's resolved target root.
interface BeforeSnapshot {
	beforeBlocks: CreatedBlock[];
	globalStylesId: string | number | undefined;
	globalStyles: {
		settings: Record< string, unknown >;
		styles: Record< string, unknown >;
	} | null;
}

/**
 * Drives the shared progressive page-design renderer against the MAIN plugin's
 * standard Gutenberg editor (post/page/site editor) — the same renderer ESE
 * uses, bound to a StandardEditorHost.
 *
 * Unlike ESE's isolated canvas sub-registry, the standard editor writes through
 * the AMBIENT default @wordpress/data registry (the same path apply-block-edits
 * uses), so this host takes no injected registry. Undo/checkpoint follows the
 * main plugin's convention:
 *
 *  - streamed frames paint the canvas fully UNTRACKED (history:'ignore', which
 *    useBlockSync syncs to the entity with undoIgnore — no undo records at
 *    all, not even staged ones), and streaming preview CSS is written with
 *    undoIgnore for the same reason;
 *  - on the final flush the whole redesign folds into exactly ONE tracked
 *    native undo level via the shared commitStreamedPageDesign algorithm
 *    (pre-redesign reset untracked, then a persistent re-apply of live-
 *    clientId copies, with the final CSS staged isCached into that level);
 *  - a pre-redesign snapshot is captured in the aiStore (setCheckpoint) so the
 *    agent can also revert via restore-checkpoint.
 */
export default function useStreamPageDesignTool() {
	const registry = useRegistry() as { batch: ( cb: () => void ) => void };
	const { getSectionRootClientId } = useBlocks();
	const { setCheckpoint, hasCheckpoint } = useCheckpoint();
	const beforeSnapshotsRef = useRef< Map< string, BeforeSnapshot > >(
		new Map()
	);
	const {
		getBlocks,
		getGlobalStylesId,
		getEditedEntityRecord,
		getCurrentPostId,
	} = useSelect(
		( select ) => ( {
			getBlocks: ( select( blockEditorStore ) as any ).getBlocks as (
				rootClientId?: string
			) => EditorBlock[],
			getGlobalStylesId: () =>
				(
					select( coreStore ) as any
				 ).__experimentalGetCurrentGlobalStylesId(),
			getEditedEntityRecord: ( select( coreStore ) as any )
				.getEditedEntityRecord,
			getCurrentPostId: ( select( editorStore ) as any ).getCurrentPostId,
		} ),
		[]
		// eslint-disable-next-line @typescript-eslint/no-explicit-any
	) as any;
	const {
		replaceInnerBlocks,
		resetBlocks,
		clearSelectedBlock,
		__unstableMarkNextChangeAsNotPersistent: markNextChangeAsNotPersistent,
	} = useDispatch( blockEditorStore ) as {
		replaceInnerBlocks: (
			rootClientId: string,
			blocks: CreatedBlock[],
			updateSelection?: boolean
		) => void;
		resetBlocks: ( blocks: CreatedBlock[] ) => void;
		clearSelectedBlock: () => void;
		__unstableMarkNextChangeAsNotPersistent: ( options?: {
			history?: 'merge' | 'ignore';
		} ) => void;
	};
	const { editEntityRecord } = useDispatch( coreStore );

	// Read the live blocks of a resolved target root (document root included).
	const getRootBlocks = useCallback(
		( rootClientId: string ): EditorBlock[] =>
			( rootClientId === DOCUMENT_ROOT
				? getBlocks()
				: getBlocks( rootClientId ) ) || [],
		[ getBlocks ]
	);

	const writeCustomCss = useCallback(
		( css: string, options?: { undoIgnore?: boolean } ): void => {
			const globalStylesId = getGlobalStylesId();
			if ( ! globalStylesId ) {
				return;
			}
			const fresh = getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			editEntityRecord(
				'root',
				'globalStyles',
				globalStylesId,
				setStyle( fresh, 'css', css ),
				options
			);
		},
		[ editEntityRecord, getEditedEntityRecord, getGlobalStylesId ]
	);

	const resolveTargetRoot = useCallback( (): string | null => {
		// Short-circuit the common site-editor case before the O(N)
		// findPostContentBlock walk: a section container is the target
		// whenever one exists.
		const sectionRootClientId = getSectionRootClientId() ?? null;
		if ( sectionRootClientId ) {
			return sectionRootClientId;
		}
		return resolvePageDesignTargetRoot( {
			sectionRootClientId: null,
			postContentClientId:
				findPostContentBlock( getBlocks )?.clientId ?? null,
			hasResolvedPost: !! getCurrentPostId(),
		} );
	}, [ getBlocks, getCurrentPostId, getSectionRootClientId ] );

	const stageBlocks = useCallback(
		(
			rootClientId: string | null,
			blocks: CreatedBlock[],
			updateSelection = false
		): void => {
			if ( ! rootClientId ) {
				return;
			}
			// Streamed intermediate writes paint the canvas but must create NO
			// undo records at all: history:'ignore' makes useBlockSync sync
			// them to the entity with undoIgnore (plain not-persistent would
			// still stage isCached records that merge into the next level).
			// Batched so the controlled-inner-blocks subscriber can't consume
			// the flag between the mark and the write.
			registry.batch( () => {
				markNextChangeAsNotPersistent( { history: 'ignore' } );
				if ( rootClientId === DOCUMENT_ROOT ) {
					// Plain post/page editor: the top-level blocks are the
					// post body, so replace them wholesale.
					resetBlocks( blocks );
					return;
				}
				replaceInnerBlocks( rootClientId, blocks, updateSelection );
			} );
		},
		[
			markNextChangeAsNotPersistent,
			registry,
			replaceInnerBlocks,
			resetBlocks,
		]
	);

	const captureCheckpoint = useCallback(
		( toolCallId: string, meta: { toolId: string; summary: string } ) => {
			// Agent restore path: snapshot the editor state in the aiStore so
			// restore-checkpoint can revert the whole redesign.
			if ( ! hasCheckpoint( toolCallId ) ) {
				setCheckpoint( toolCallId, [ checkpointKeys.BLOCKS ], {
					toolCallId,
					toolId: meta.toolId,
					summary: meta.summary,
				} );
			}
			// Native-undo baseline: pre-redesign blocks of the SAME root the
			// stream will stage into, plus the global-styles record the final
			// CSS folds against.
			if ( ! beforeSnapshotsRef.current.has( toolCallId ) ) {
				const rootClientId = resolveTargetRoot();
				if ( ! rootClientId ) {
					return;
				}
				const globalStylesId = getGlobalStylesId();
				const globalStylesRecord = globalStylesId
					? getEditedEntityRecord(
							'root',
							'globalStyles',
							globalStylesId
					  )
					: null;
				beforeSnapshotsRef.current.set( toolCallId, {
					beforeBlocks: JSON.parse(
						JSON.stringify( getRootBlocks( rootClientId ) )
					),
					globalStylesId,
					globalStyles: globalStylesRecord
						? JSON.parse(
								JSON.stringify( {
									settings: globalStylesRecord.settings || {},
									styles: globalStylesRecord.styles || {},
								} )
						  )
						: null,
				} );
			}
		},
		[
			getEditedEntityRecord,
			getGlobalStylesId,
			getRootBlocks,
			hasCheckpoint,
			resolveTargetRoot,
			setCheckpoint,
		]
	);

	const commitFinalDesign = useCallback(
		(
			toolCallId: string,
			rootClientId: string | null,
			finalCss: string | null
		): void => {
			const snapshot = beforeSnapshotsRef.current.get( toolCallId );
			if ( ! snapshot || ! rootClientId ) {
				return;
			}
			beforeSnapshotsRef.current.delete( toolCallId );

			const { globalStylesId, globalStyles } = snapshot;
			const styleAdapters: Partial< CommitAdapters > =
				globalStylesId && globalStyles
					? {
							seedStylesBaseline: () =>
								editEntityRecord(
									'root',
									'globalStyles',
									globalStylesId,
									{
										settings: globalStyles.settings,
										styles: globalStyles.styles,
									},
									{ undoIgnore: true }
								),
							applyFinalCssTracked: ( css: string ) =>
								editEntityRecord(
									'root',
									'globalStyles',
									globalStylesId,
									{
										settings: globalStyles.settings,
										styles: {
											...globalStyles.styles,
											css,
										},
									},
									{ isCached: true }
								),
					  }
					: {};

			commitStreamedPageDesign(
				{
					getLiveBlocks: () => getRootBlocks( rootClientId ),
					stageUntracked: ( blocks ) =>
						stageBlocks( rootClientId, blocks, false ),
					replacePersistent: ( blocks ) => {
						if ( rootClientId === DOCUMENT_ROOT ) {
							resetBlocks( blocks );
							return;
						}
						replaceInnerBlocks( rootClientId, blocks, false );
					},
					clearSelection: clearSelectedBlock,
					...styleAdapters,
				},
				{ beforeBlocks: snapshot.beforeBlocks },
				finalCss
			);
		},
		[
			clearSelectedBlock,
			editEntityRecord,
			getRootBlocks,
			replaceInnerBlocks,
			resetBlocks,
			stageBlocks,
		]
	);

	const host = useMemo< EditorHost >(
		() => ( {
			getBlocks,
			resolveTargetRoot,
			stageBlocks,
			captureCheckpoint,
			commitFinalDesign,
			applyCustomCss: async ( css: string ): Promise< void > => {
				// Streaming preview CSS is untracked; the final CSS is folded
				// into the single undo level by commitFinalDesign instead.
				writeCustomCss( css, { undoIgnore: true } );
			},
		} ),
		[
			captureCheckpoint,
			commitFinalDesign,
			getBlocks,
			resolveTargetRoot,
			stageBlocks,
			writeCustomCss,
		]
	);

	useStreamPageDesignRenderer( host, {} );

	return {};
}
