/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { buildStreamPageDesignAbilityDescriptor } from '@shared/stream-page-design-core';

/**
 * Build the stream-page-design ability descriptor for the main Big Sky plugin,
 * with the plugin's `big-sky` category and translated strings. Registered on
 * both surfaces that expose Big Sky abilities to the agent: the wp-admin Dock
 * (use-abilities-registration) and the Calypso unified experience
 * (calypso-agent-provider/useAbilitiesSetup). The apply handler itself is mounted
 * separately by useStreamPageDesignTool (the shared renderer + StandardEditorHost).
 */
export function streamPageDesignAbility() {
	return buildStreamPageDesignAbilityDescriptor( {
		category: 'big-sky',
		strings: {
			label: __( 'Stream Page Design', 'big-sky' ),
			stagedMessage: __(
				'The generated page content has been staged in the editor for review.',
				'big-sky'
			),
			editorLoadingMessage: __(
				'The editor is still loading. Try the page design again once the page is editable.',
				'big-sky'
			),
		},
	} );
}
