/**
 * WordPress dependencies
 */
import { memo } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { assistants } from '@ai/assistants';

// Component that safely calls a single hook
const HookRunner = ( { hook } ) => {
	hook();
	return null;
};

const ToolkitsProvider = memo( () => {
	// Render a HookRunner for each assistant hook so we can load these
	// without having to name them while still complying with the rules of hooks.
	const filteredAssistants = assistants.filter(
		( assistant ) => assistant.toolkitHook
	);

	return (
		<>
			{ filteredAssistants.map( ( assistant ) => (
				<HookRunner
					key={ assistant.id }
					hook={ assistant.toolkitHook }
				/>
			) ) }
		</>
	);
} );
ToolkitsProvider.displayName = 'ToolkitsProvider';

export default ToolkitsProvider;
