/**
 * Internal dependencies
 */
import log from '@utils/log-debug';

const CHAT_OPEN_KEY = 'big-sky-chat-open';
const CHAT_DOCKED_KEY = 'big-sky-chat-docked';

export const getChatOpenState = () => {
	try {
		const val = window.localStorage.getItem( CHAT_OPEN_KEY );
		return val === null || val === 'true';
	} catch ( error ) {
		return true;
	}
};

export const setChatOpenState = ( isOpen ) => {
	try {
		window.localStorage.setItem( CHAT_OPEN_KEY, isOpen.toString() );
	} catch ( error ) {
		log.error( '[Chat] Failed to set open state:', error );
	}
};

export const getChatDockedState = () => {
	try {
		const val = window.localStorage.getItem( CHAT_DOCKED_KEY );
		return val === null || val === 'true';
	} catch ( error ) {
		return false;
	}
};

export const setChatDockedState = ( isDocked ) => {
	try {
		window.localStorage.setItem( CHAT_DOCKED_KEY, isDocked.toString() );
	} catch ( error ) {
		log.error( '[Chat] Failed to set docked state:', error );
	}
};
