/**
 * External dependencies
 */
import { AgentUI, EmptyView } from '@automattic/agenttic-ui';
import classnames from 'classnames';

/**
 * WordPress dependencies
 */
import { Popover } from '@wordpress/components';

import { useDispatch, useSelect } from '@wordpress/data';
import {
	useCallback,
	useEffect,
	useMemo,
	useRef,
	useState,
} from '@wordpress/element';
import {
	getEmptyViewSuggestions,
	useSuggestions,
} from '@ai/hooks/use-suggestions';

/**
 * Internal dependencies
 */
import { messageRoles } from '@utils/constants';
import { recordTracksEvent } from '@utils/tracks';
import {
	trackClose,
	trackExpand,
	trackMessageActions,
	trackSubmit,
	trackSuggestionClick,
	trackSuggestionsRendered,
} from '@utils/agenttic-tracking';
import './style.scss';

import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import useCanvas from '@hooks/use-canvas.js';
import { store as aiStore } from '@store';
import { useImageDrop } from '@hooks/use-image-drop';
import useCurrentScreen from '@hooks/use-current-screen';
import useIsThinking from '@hooks/use-is-thinking';
import useAbilitiesRegistration from '@abilities/use-abilities-registration';
import {
	hasComponentInContent,
	hasPickerComponent,
	isComponentToDisableOnPageChange,
	maybeMergeCompletedPlanMessage,
} from '@utils/message-utils';
import SidebarManager from '@components/sidebar-manager';
import { __ } from '@wordpress/i18n';
import { AI } from '@components/icons';
import BigSkyImageUploader from '@components/image-uploader-wrapper';
import ChatHeader from '@components/chat/header';
import CompleteSetupButton from './complete-setup-button.js';
import SelectedBlock from '@components/chat/selected-block';
import MessageFeedback from '@components/chat/message/message-feedback';
import CompletedPlan from '@components/chat/components/completed-plan';
import { ChatSuggestions } from '@ai/assistants/shared/make-suggestions/index.js';
import {
	groupSiteBuildMessages,
	hasSiteBuildMessages,
} from '@components/site-build-progress/group-messages';
import { comment, drawerRight, login } from '@wordpress/icons';
import useMobileKeyboardOffset from '@hooks/use-mobile-keyboard-offset';
import {
	getChatDockedState,
	getChatOpenState,
	setChatDockedState,
	setChatOpenState,
} from './utils.js';

const SNAP_POSITION = {
	NONE: 'none',
	LEFT: 'left',
	RIGHT: 'right',
	CENTER: 'center',
};

const CHAT_DARK_MODE_STORAGE_KEY = 'big-sky-chat-dark-mode';

export default function Dock() {
	const { suggestions, clearSuggestions } = useSuggestions();
	const [ currentInput, setCurrentInput ] = useState( '' );
	const [ floatingChatState, setFloatingChatState ] = useState(
		getChatOpenState() ? 'expanded' : 'collapsed'
	);
	const { isThinking } = useIsThinking();

	// Ensure abilities are registered when needed
	useAbilitiesRegistration();

	const { zoomIn } = useCanvas();
	const { postId: currentPostId, isPostEditor } = useCurrentScreen();
	const messages = useSelect( ( select ) => select( aiStore ).getMessages() );
	const {
		resetConversation,
		clearMessages,
		runAgent,
		abortAgentRequest,
		setSuppressSuggestions,
	} = useDispatch( aiStore );
	const {
		isBuildingSite,
		isSiteBuildStructurePhase,
		isDevMode,
		userLocale,
		thinkingMessage,
		isCiab,
	} = useSelect( ( select ) => {
		const ai = select( aiStore );

		return {
			isBuildingSite: ai.getIsBuildingSite(),
			isSiteBuildStructurePhase: ai.getIsSiteBuildStructurePhase(),
			isDevMode: ai.getIsDevMode(),
			userLocale: ai.getUserLocale(),
			thinkingMessage: ai.getThinkingMessage(),
			isCiab: ai.getIsCiab(),
		};
	} );

	const hideChatControls = isBuildingSite && isCiab;

	// Temporary flag to allow a12s to test dark mode
	const [ isChatDarkMode, setIsChatDarkMode ] = useState( () => {
		if ( ! isDevMode || typeof window === 'undefined' ) {
			return false;
		}

		try {
			const storedValue = window.localStorage?.getItem(
				CHAT_DARK_MODE_STORAGE_KEY
			);

			return storedValue === 'true';
		} catch ( error ) {
			return false;
		}
	} );

	const handleInputChange = useCallback(
		( value, options = {} ) => {
			const { focus = false } = options;
			setCurrentInput( value );
			setSuppressSuggestions( value.length !== 0 );

			// Focus the textarea and set cursor position to end if requested
			if ( focus ) {
				// Find the textarea within the agenttic container
				const textarea = document.querySelector(
					'.agenttic .Textarea-module_textarea'
				);
				if ( textarea ) {
					textarea.value = value;
					textarea.focus();
					textarea.setSelectionRange( value.length, value.length );
				}
			}
		},
		[ setSuppressSuggestions ]
	);

	// Listen for custom events from inline suggestions to set input value
	// This matches the behavior of handleSuggestionSubmit in AgentUIContainer
	useEffect( () => {
		const handleInlineSuggestionClick = ( event ) => {
			const { value } = event.detail;
			if ( value ) {
				const valueWithSpace = value.endsWith( ' ' )
					? value
					: `${ value } `;
				handleInputChange( valueWithSpace, { focus: true } );
			}
		};

		window.addEventListener(
			'big-sky-inline-suggestion-click',
			handleInlineSuggestionClick
		);
		return () => {
			window.removeEventListener(
				'big-sky-inline-suggestion-click',
				handleInlineSuggestionClick
			);
		};
	}, [ handleInputChange ] );

	const agentMessages = useMemo( () => {
		const messagesWithDisabled = messages.map( ( msg ) => {
			let disabled = msg.disabled || false;
			if (
				! disabled &&
				isComponentToDisableOnPageChange( msg ) &&
				currentPostId !== msg.postId
			) {
				disabled = true;
			}
			return {
				...msg,
				disabled,
			};
		} );

		// Add tracking to message actions
		const trackedMessages = trackMessageActions( messagesWithDisabled );

		const isEligibleForFeedback = ( msg, nextMsg ) => {
			if (
				msg.role !== messageRoles.ASSISTANT ||
				msg.type === 'response-actions' ||
				! Array.isArray( msg.content )
			) {
				return false;
			}

			if ( msg.context && msg.context === 'site-build-completed' ) {
				return false;
			}

			// Skip if already has feedback UI or is a confirmation dialog.
			if (
				hasComponentInContent( msg.content, CompletedPlan ) ||
				hasComponentInContent( msg.content, MessageFeedback ) ||
				hasComponentInContent( msg.content, ChatSuggestions )
			) {
				return false;
			}

			// If the next message is a CompletedPlan (response-actions message),
			// we render thumbs in the same row as those actions instead.
			if ( hasComponentInContent( nextMsg?.content, CompletedPlan ) ) {
				return false;
			}

			return true;
		};

		let messagesWithFeedback = trackedMessages.map( ( msg, index ) => {
			if (
				! isEligibleForFeedback( msg, trackedMessages[ index + 1 ] )
			) {
				return msg;
			}

			return {
				...msg,
				content: [
					...msg.content,
					{
						type: 'component',
						component: MessageFeedback,
						componentProps: {
							id: msg.id,
						},
					},
				],
			};
		} );

		// Group site-build messages only when needed
		const hasBuildMessages = hasSiteBuildMessages( messagesWithFeedback );
		// Show progress card during the styling phase. The dock is suppressed
		// while isSiteBuildStructurePhase is true (see the render gate below), so
		// this path runs once the structure phase completes and the dock mounts.

		if ( isBuildingSite || hasBuildMessages ) {
			// Show spinner during post-layout workflow (colors, fonts, images)
			return groupSiteBuildMessages(
				messagesWithFeedback,
				isBuildingSite ? thinkingMessage : null
			);
		}

		messagesWithFeedback = maybeMergeCompletedPlanMessage(
			messagesWithFeedback,
			CompletedPlan
		);

		return messagesWithFeedback;
	}, [ currentPostId, messages, thinkingMessage, isBuildingSite ] );

	// custom hook to handle image drops
	useImageDrop();

	// NOTE: Temporary fix to keep the chat above mobile keyboards until a permanent layout solution is implemented
	useMobileKeyboardOffset( '.agenttic', '.Textarea-module_textarea' );

	const popoverRef = useRef();

	// Used to prevent triggering the same track event multiple times
	const [ hasRecordedLongMessage, setHasRecordedLongMessage ] =
		useState( false );

	// Set the correct CSS classes on the top level dock container
	// depending on the state of the dock.
	useEffect( () => {
		const { canvasiFrameBody } = getCanvasIframeElements();
		canvasiFrameBody?.classList.add( 'big-sky__dock__is-chat' );
	}, [] );

	// Auto zoom-in when a picker component gets disabled
	useEffect( () => {
		// Find the most recent message with a picker component
		const lastPickerMessage = [ ...agentMessages ]
			.reverse()
			.find( ( msg ) => hasPickerComponent( msg ) );

		// If the last picker message is disabled
		if ( lastPickerMessage?.disabled ) {
			//zoomIn();
		}
	}, [ agentMessages, zoomIn ] );

	useEffect( () => {
		function updateBottom() {
			if ( ! popoverRef.current ) {
				return;
			}

			const { height } = window.visualViewport;
			const bottom = document.documentElement.clientHeight - height;

			popoverRef.current.style.bottom = `${ bottom }px`;
			popoverRef.current.style.height = `${ height }px`;
		}

		if ( window.visualViewport ) {
			updateBottom();
			window.visualViewport.addEventListener( 'resize', updateBottom );
			return () => {
				window.visualViewport.removeEventListener(
					'resize',
					updateBottom
				);
			};
		}
	}, [] );

	const handleOnClose = useCallback( () => {
		setFloatingChatState( 'collapsed' );
		setChatOpenState( false );
		// Zoom back in and restore suggestions when closing the chat
		zoomIn();
		setSuppressSuggestions( false );
	}, [ setSuppressSuggestions, zoomIn ] );

	const handleResetChat = useCallback( () => {
		abortAgentRequest();
		resetConversation();
		clearMessages();
		// Zoom back in and restore suggestions when closing the chat
		//zoomIn();
		setSuppressSuggestions( false );
	}, [
		abortAgentRequest,
		clearMessages,
		resetConversation,
		setSuppressSuggestions,
	] );

	// Store current suggestions for tracking (since agenttic-ui clears them before onSubmit)
	const currentSuggestionsRef = useRef( [] );
	useEffect( () => {
		currentSuggestionsRef.current = suggestions;
	}, [ suggestions ] );

	// Create tracked callback wrappers
	const trackedOnSubmit = useMemo(
		() => trackSubmit( runAgent ),
		[ runAgent ]
	);
	const trackedOnSuggestionClick = useMemo(
		() => trackSuggestionClick(),
		[]
	);
	const trackedOnClose = useMemo(
		() => trackClose( handleOnClose ),
		[ handleOnClose ]
	);

	const handleExpand = useCallback( () => {
		setFloatingChatState( 'expanded' );
		setChatOpenState( true );
	}, [] );

	const trackedOnExpand = useMemo(
		() => trackExpand( handleExpand ),
		[ handleExpand ]
	);

	// Track when EmptyView is rendered with specific suggestions
	const lastTrackedSuggestionsRef = useRef( null );
	useEffect( () => {
		// Determine which suggestions are actually shown in EmptyView
		const displayedSuggestions =
			agentMessages.length === 0 && suggestions.length === 0
				? getEmptyViewSuggestions()
				: suggestions;

		if ( displayedSuggestions.length === 0 ) {
			return;
		}

		// Create a stable identifier for the current suggestion set
		const suggestionIds = displayedSuggestions
			.map( ( s ) => s.id )
			.join( ',' );

		// Only track if the suggestion set has changed
		if ( lastTrackedSuggestionsRef.current !== suggestionIds ) {
			trackSuggestionsRendered( displayedSuggestions );
			lastTrackedSuggestionsRef.current = suggestionIds;
		}
	}, [ agentMessages.length, suggestions ] );

	const renderAgentUI = ( {
		isDocked,
		canDock,
		dock,
		undock,
		closeSidebar,
	} ) => {
		const resetChatMenuItem = {
			icon: comment,
			title: __( 'New chat', 'big-sky' ),
			isDisabled: ! agentMessages.length || isThinking,
			onClick: () => {
				handleResetChat();
				recordTracksEvent( 'ai_chat_more_options_click', {
					type: 'reset_chat',
				} );
			},
		};
		const undockMenuItem = {
			icon: login,
			title: __( 'Pop out sidebar', 'big-sky' ),
			onClick: () => {
				try {
					window.localStorage?.setItem(
						'agenttic-chat-position',
						SNAP_POSITION.RIGHT
					);
				} catch ( error ) {
					// Ignore errors
				}

				undock();
				setFloatingChatState( 'expanded' );
				recordTracksEvent( 'ai_chat_more_options_click', {
					type: 'undock',
				} );
			},
		};
		const dockMenuItem = {
			icon: drawerRight,
			title: __( 'Move to sidebar', 'big-sky' ),
			onClick: () => {
				dock();
				recordTracksEvent( 'ai_chat_more_options_click', {
					type: 'dock',
				} );
			},
		};

		// Temporary menu to allow a12s to test dark mode
		const toggleChatDarkModeMenuItem = isDevMode &&
			! isDocked && {
				icon: drawerRight,
				title: isChatDarkMode
					? __( 'Disable dark mode', 'big-sky' )
					: __( 'Enable dark mode', 'big-sky' ),
				onClick: () => {
					const nextValue = ! isChatDarkMode;

					setIsChatDarkMode( nextValue );

					try {
						window.localStorage?.setItem(
							CHAT_DARK_MODE_STORAGE_KEY,
							nextValue ? 'true' : 'false'
						);
					} catch ( error ) {
						// Ignore errors
					}
				},
			};

		const optionItems = [
			! hideChatControls && resetChatMenuItem,
			isDocked && undockMenuItem,
			! isDocked && canDock && dockMenuItem,
			toggleChatDarkModeMenuItem,
		].filter( Boolean );

		const chatInputKeyDownHandler = ( { key, target } ) => {
			if ( key !== 'Escape' || target.value !== '' ) {
				return;
			}

			if ( isDocked ) {
				closeSidebar();
			} else {
				trackedOnClose();
			}
		};

		// Suppress AgentUI's thinking message when the progress card is showing it.
		// The dock is suppressed while isSiteBuildStructurePhase is true (see the
		// render gate below), so this runs from the styling phase onward.
		const progressCardHasThinking =
			isBuildingSite &&
			thinkingMessage &&
			agentMessages.some( ( msg ) =>
				msg.id?.startsWith( 'site-build-group-' )
			);
		const agentThinkingMessage = progressCardHasThinking
			? null
			: thinkingMessage || 'Thinking...';
		const agentIsProcessing = progressCardHasThinking ? false : isThinking;

		// Determine suggestions to display
		let displaySuggestions;
		if ( suggestions.length === 0 && currentInput.length === 0 ) {
			displaySuggestions = isPostEditor ? [] : getEmptyViewSuggestions();
		} else {
			displaySuggestions = suggestions;
		}

		const agentUI = (
			<AgentUI.Container
				className={ classnames( 'agenttic', {
					dark: isChatDarkMode || isDocked,
				} ) }
				messages={ agentMessages }
				isProcessing={ agentIsProcessing }
				emptyView={
					<EmptyView
						heading={ __(
							'Howdy! How can I help you today?',
							'big-sky'
						) }
						help={
							displaySuggestions.length > 0 &&
							__(
								'Got a different request? Ask away.',
								'big-sky'
							)
						}
						suggestions={ displaySuggestions }
						icon={ <AI width={ 40 } height={ 40 } /> }
					/>
				}
				onSubmit={ trackedOnSubmit }
				variant={ isDocked ? 'embedded' : 'floating' }
				floatingChatState={ floatingChatState }
				suggestions={ suggestions }
				clearSuggestions={ clearSuggestions }
				onSuggestionClick={ (
					selectedSuggestion,
					availableSuggestions
				) =>
					trackedOnSuggestionClick(
						selectedSuggestion,
						availableSuggestions
					)
				}
				inputValue={ currentInput }
				onInputChange={ handleInputChange }
				onExpand={ trackedOnExpand }
				draggableStates={ [ 'collapsed', 'expanded' ] }
				onStop={ abortAgentRequest }
				onInputLimitExceeded={ () => {
					if ( floatingChatState !== 'expanded' ) {
						setFloatingChatState( 'expanded' );
					}
					if ( ! hasRecordedLongMessage ) {
						recordTracksEvent( 'chat_input_message_too_long' );
						setHasRecordedLongMessage( true );
					}
				} }
				locale={ userLocale }
				expandOnClick
				thinkingMessage={ agentThinkingMessage }
			>
				<AgentUI.ConversationView>
					{ ! hideChatControls && (
						<ChatHeader
							isChatDocked={ isDocked }
							onClose={ isDocked ? closeSidebar : trackedOnClose }
							options={ optionItems }
						/>
					) }
					<AgentUI.Messages />
					{ ! hideChatControls && (
						<AgentUI.Footer>
							<BigSkyImageUploader />
							<AgentUI.Suggestions />
							<AgentUI.Notice />
							<SelectedBlock />
							<AgentUI.Input
								onKeyDown={ chatInputKeyDownHandler }
							/>
						</AgentUI.Footer>
					) }
					<CompleteSetupButton />
				</AgentUI.ConversationView>
			</AgentUI.Container>
		);

		return isDocked ? (
			agentUI
		) : (
			<Popover animate={ false } className="agenttic-ui__wrapper">
				{ agentUI }
			</Popover>
		);
	};

	const sidebarContainer = useMemo( () => {
		const siteEditorContainer = document.querySelector(
			'#site-editor .edit-site-layout__canvas-container'
		);
		const pageEditorContainer = document.querySelector(
			'.block-editor #editor'
		);

		return siteEditorContainer || pageEditorContainer;
	}, [] );

	return (
		<>
			{ ! isSiteBuildStructurePhase && (
				<SidebarManager
					sidebarContainer={ sidebarContainer }
					sidebarModifierClass={
						hideChatControls ? 'big-sky-sidebar--ciab-build' : ''
					}
					onOpenSidebar={ () => {
						recordTracksEvent( 'sidebar_open_click' );
						setChatOpenState( true );
					} }
					onCloseSidebar={ () => {
						recordTracksEvent( 'sidebar_close_click' );
						setChatOpenState( false );
					} }
					onDock={ () => {
						recordTracksEvent( 'ai_chat_docked' );
						setChatDockedState( true );
					} }
					onUndock={ () => {
						recordTracksEvent( 'ai_chat_undocked' );
						setChatDockedState( false );
					} }
					defaultUndocked={ ! getChatDockedState() }
					defaultOpen={ getChatOpenState() }
				>
					{ renderAgentUI }
				</SidebarManager>
			) }
		</>
	);
}
